INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e52a2c34-7aa0-40ac-aa35-deb8a2c9c1ca', '醉吟', '醉吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["醉來忘渴復忘飢，冠帶形骸杳若遺。","耳底齋鐘初過後，心頭卯酒未消時。","臨風朗詠從人聽，看雪閑行任馬遲。","應被衆疑公事慢，承前府尹不吟詩。"]', '["醉来忘渴复忘飢，冠带形骸杳若遺。","耳底斋鐘初過後，心头卯酒未消时。","臨风朗詠從人听，看雪闲行任马遲。","應被衆疑公事慢，承前府尹不吟诗。"]', '诗', 'shi', '', NULL, '醉吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7936b3-0b78-412a-aa44-f0f116126bcd', '府酒五絕 變法', '府酒五絕 变法', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自慚到府來周歲，惠愛威稜一事無。","唯是改張官酒法，漸從濁水作醍醐。"]', '["自慚到府来周歲，惠愛威稜一事無。","唯是改張官酒法，漸從濁水作醍醐。"]', '诗', 'shi', '', NULL, '府酒五絕 變法 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46fa7935-797f-41c6-86e2-51c7a9726642', '府酒五絕 招客', '府酒五絕 招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日午微風且暮寒，春風冷峭雪乾殘。","碧氈帳下紅爐畔，試爲來嘗一醆看。"]', '["日午微风且暮寒，春风冷峭雪乾殘。","碧氈帳下紅爐畔，試爲来嘗一醆看。"]', '诗', 'shi', '', NULL, '府酒五絕 招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e940989b-c90d-46bd-852a-da3a0f8f3fd4', '府酒五絕 辨味', '府酒五絕 辨味', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["甘露太甜非正味，醴泉雖潔不芳馨。","桮中此物何人別，柔旨之中有典刑。"]', '["甘露太甜非正味，醴泉雖潔不芳馨。","桮中此物何人別，柔旨之中有典刑。"]', '诗', 'shi', '', NULL, '府酒五絕 辨味 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cfcdedfc-22e7-47ab-ae39-8dab5bc6753d', '府酒五絕 自勸', '府酒五絕 自勸', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶昔羈貧應舉年，脫衣典酒曲江邊。","十千一斗猶賒飲，何況官供不著錢。"]', '["憶昔羈貧應舉年，脫衣典酒曲江邊。","十千一斗猶賒饮，何況官供不著錢。"]', '诗', 'shi', '', NULL, '府酒五絕 自勸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e489a148-c3ca-4b64-9f6f-d26a9f69566c', '府酒五絕 諭妓', '府酒五絕 諭妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["燭淚夜黏桃葉袖，酒痕春汚石榴裙。","莫辭辛苦供歡宴，老後思量悔煞君。"]', '["燭泪夜黏桃葉袖，酒痕春汚石榴裙。","莫辞辛苦供歡宴，老後思量悔煞君。"]', '诗', 'shi', '', NULL, '府酒五絕 諭妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0dc11c2-231b-49d2-b4c8-32862ad75274', '晚歸早出', '晚归早出', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["筋力年年減，風光日日新。","退衙歸逼夜，拜表出侵晨。","何處臺無月，誰家池不春。","莫言無勝地，自是少閑人。","坐厭推囚案，行嫌引馬塵。","幾時辭府印，却作自由身。"]', '["筋力年年減，风光日日新。","退衙归逼夜，拜表出侵晨。","何处台無月，誰家池不春。","莫言無勝地，自是少闲人。","坐厭推囚案，行嫌引马塵。","幾时辞府印，却作自由身。"]', '诗', 'shi', '', NULL, '晚歸早出 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df3aadc2-f1ba-4fd6-b593-b1d36d657cf4', '南龍興寺殘雪', '南龙兴寺殘雪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南龍興寺春晴後，緩步徐吟繞四廊。","老趂風花應不稱，閑尋松雪正相當。","吏人引從多乘轝，賓客逢迎少下堂。","不擬人間更求事，些些疎嬾亦何妨。"]', '["南龙兴寺春晴後，緩步徐吟繞四廊。","老趂风花應不稱，闲尋松雪正相當。","吏人引從多乘轝，賓客逢迎少下堂。","不擬人间更求事，些些疎嬾亦何妨。"]', '诗', 'shi', '', NULL, '南龍興寺殘雪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e92829b3-e22f-4596-b6ca-c571471d5c32', '天宮閣早春', '天宮閣早春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天宮高閣上何頻，每上令人耳目新。","前日晚登緣看雪，今朝晴望爲迎春。","林鶯何處吟箏柱，牆柳誰家曬麴塵。","可惜三川虛作主，風光不屬白頭人。"]', '["天宮高閣上何頻，每上令人耳目新。","前日晚登緣看雪，今朝晴望爲迎春。","林鶯何处吟箏柱，牆柳誰家曬麴塵。","可惜三川虛作主，风光不屬白头人。"]', '诗', 'shi', '', NULL, '天宮閣早春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05715733-83b9-44ff-b10e-122f102878a8', '履道居三首 一', '履道居三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫嫌地窄林亭小，莫厭貧家活計微。","大有高門鏁寬宅，主人到老不曾歸。"]', '["莫嫌地窄林亭小，莫厭貧家活計微。","大有高门鏁寬宅，主人到老不曾归。"]', '诗', 'shi', '', NULL, '履道居三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f66a9815-7551-4bbe-a067-acf2560f0523', '履道居三首 二', '履道居三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東里素帷猶未徹，南鄰丹旐又新懸。","衡門蝸舍自慙媿，收得身來已五年。"]', '["东里素帷猶未徹，南鄰丹旐又新懸。","衡门蝸舍自慙媿，收得身来已五年。"]', '诗', 'shi', '', NULL, '履道居三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('329be486-6bde-415e-9533-bea1dc7c66bc', '履道居三首 三', '履道居三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世事平分衆所知，何嘗苦樂不相隨。","唯餘耽酒狂歌客，只有樂時無苦時。"]', '["世事平分衆所知，何嘗苦乐不相隨。","唯餘耽酒狂歌客，只有乐时無苦时。"]', '诗', 'shi', '', NULL, '履道居三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbf1b1a4-0b53-45d0-b4ce-e7014e5c0026', '和夢得冬日晨興', '和梦得冬日晨兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漏傳初五點，雞報第三聲。","帳下從容起，窗間曨{日怱}明。","照書燈未滅，煖酒火重生。","理曲弦歌動，先聞唱渭城。"]', '["漏傳初五点，雞報第三声。","帳下從容起，窗间曨{日怱}明。","照书灯未滅，煖酒火重生。","理曲弦歌动，先闻唱渭城。"]', '诗', 'shi', '', NULL, '和夢得冬日晨興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77afcb19-f3d0-421d-9e4a-0c44631db095', '雪夜對酒招客', '雪夜对酒招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["帳小青氈煖，桮香[綠]蟻新。","醉憐今夜月，歡憶去年人。","闇落燈花燼，閑生草座塵。","慇懃報弦管，明日有嘉賓。"]', '["帳小青氈煖，桮香[綠]蟻新。","醉怜今夜月，歡憶去年人。","闇落灯花燼，闲生草座塵。","慇懃報弦管，明日有嘉賓。"]', '诗', 'shi', '', NULL, '雪夜對酒招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88d3e8f-211f-4173-bdee-f63282139218', '贈晦叔憶夢得', '贈晦叔憶梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自別崔公四五秋，因何臨老轉風流。","歸來不說秦中事，歇定唯謀洛下遊。","酒面浮花應是喜，歌眉歛黛不關愁。","得君更有無厭意，猶恨尊前欠老劉。"]', '["自別崔公四五秋，因何臨老轉风流。","归来不说秦中事，歇定唯謀洛下游。","酒面浮花應是喜，歌眉歛黛不关愁。","得君更有無厭意，猶恨尊前欠老劉。"]', '诗', 'shi', '', NULL, '贈晦叔憶夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('167b8471-b49f-4698-a863-a3bb5e40e0de', '醉後重贈晦叔', '醉後重贈晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老伴知君少，歡情向我偏。","無論疎與數，相見輙欣然。","各以詩成癖，俱因酒得仙。","笑迴青眼語，醉竝白頭眠。","豈是今投分，多疑宿結緣。","人間更何事，攜手送衰年。"]', '["老伴知君少，歡情向我偏。","無論疎與數，相见輙欣然。","各以诗成癖，俱因酒得仙。","笑迴青眼語，醉竝白头眠。","豈是今投分，多疑宿結緣。","人间更何事，携手送衰年。"]', '诗', 'shi', '', NULL, '醉後重贈晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13f9e8ff-c156-477c-88f8-967688841f5a', '睡覺', '睡覺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["星河耿耿漏綿綿，月闇燈微欲曙天。","轉枕頻伸書帳下，披裘箕踞火爐前。","老眠早覺常殘夜，病力先衰不待年。","五欲已銷諸念息，世間無境可勾牽。"]', '["星河耿耿漏綿綿，月闇灯微欲曙天。","轉枕頻伸书帳下，披裘箕踞火爐前。","老眠早覺常殘夜，病力先衰不待年。","五欲已銷諸念息，世间無境可勾牽。"]', '诗', 'shi', '', NULL, '睡覺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28452f5a-2dd2-4d72-9259-8ede9a679eac', '詠興五首 解印出公府', '詠兴五首 解印出公府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["解印出公府，斗藪塵土衣。","百吏放爾散，雙鶴隨我歸。","歸來履道宅，下馬入柴扉。","馬嘶返舊櫪，鶴舞還故池。","雞犬何忻忻，隣里亦依依。","年顏老去日，生計勝前時。","有帛禦冬寒，有穀防歲饑。","飽於東方朔，樂於榮啓期。","人生且如此，此外吾不知。"]', '["解印出公府，斗藪塵土衣。","百吏放爾散，雙鹤隨我归。","归来履道宅，下马入柴扉。","马嘶返旧櫪，鹤舞還故池。","雞犬何忻忻，隣里亦依依。","年顏老去日，生計勝前时。","有帛禦冬寒，有穀防歲饑。","飽於东方朔，乐於榮啓期。","人生且如此，此外吾不知。"]', '诗', 'shi', '', NULL, '詠興五首 解印出公府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7a8bd3-2015-4327-bb9b-b596a39761a9', '詠興五首 出府歸吾廬', '詠兴五首 出府归吾廬', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["出府歸吾廬，靜然安且逸。","更無客干謁，時有僧問疾。","家僮十餘人，櫪馬三四匹。","慵發經旬臥，興來連日出。","出遊愛何處，嵩碧伊瑟瑟。","況有清和天，正當疎散日。","身閑自爲貴，何必居榮秩。","心足即非貧，豈唯金滿室。","吾觀權勢者，苦以身徇物。","炙手外炎炎，履冰中慄慄。","朝飢口忘味，夕惕心憂失。","但有富貴名，而無富貴實。"]', '["出府归吾廬，静然安且逸。","更無客干謁，时有僧问疾。","家僮十餘人，櫪马三四匹。","慵發經旬臥，兴来連日出。","出游愛何处，嵩碧伊瑟瑟。","況有清和天，正當疎散日。","身闲自爲貴，何必居榮秩。","心足即非貧，豈唯金满室。","吾观權勢者，苦以身徇物。","炙手外炎炎，履冰中慄慄。","朝飢口忘味，夕惕心憂失。","但有富貴名，而無富貴實。"]', '诗', 'shi', '', NULL, '詠興五首 出府歸吾廬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e4d2669-67e1-4b83-a8b8-b73abf5c240b', '詠興五首 池上有小舟', '詠兴五首 池上有小舟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池上有小舟，舟中有胡牀。","牀前有新酒，獨酌還獨嘗。","熏若春日氣，皎如秋水光。","可洗機巧心，可蕩塵垢腸。","岸曲舟行遲，一曲進一觴。","未知幾曲醉，醉入無何鄉。","寅緣潭島間，水竹深青蒼。","身閑心無事，白日爲我長。","我若未忘世，雖閑心亦忙。","世若未忘我，雖退身難藏。","我今異於是，身世交相忘。"]', '["池上有小舟，舟中有胡牀。","牀前有新酒，独酌還独嘗。","熏若春日氣，皎如秋水光。","可洗機巧心，可蕩塵垢腸。","岸曲舟行遲，一曲進一觴。","未知幾曲醉，醉入無何乡。","寅緣潭島间，水竹深青蒼。","身闲心無事，白日爲我长。","我若未忘世，雖闲心亦忙。","世若未忘我，雖退身难藏。","我今異於是，身世交相忘。"]', '诗', 'shi', '', NULL, '詠興五首 池上有小舟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88b5bba7-8787-4d28-b407-9a2b825779ef', '詠興五首 四月池水滿', '詠兴五首 四月池水满', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["四月池水滿，龜游魚躍出。","吾亦愛吾池，池邊開一室。","人魚雖異族，其樂歸於一。","且與爾爲徒，逍遙同過日。","爾無羨滄海，蒲藻可委質。","吾亦忘青雲，衡茅足容膝。","況吾與爾輩，本非蛟龍匹。","假如雲雨來，祗是池中物。"]', '["四月池水满，龟游鱼躍出。","吾亦愛吾池，池邊开一室。","人鱼雖異族，其乐归於一。","且與爾爲徒，逍遙同過日。","爾無羨滄海，蒲藻可委質。","吾亦忘青云，衡茅足容膝。","況吾與爾輩，本非蛟龙匹。","假如云雨来，祗是池中物。"]', '诗', 'shi', '', NULL, '詠興五首 四月池水滿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877e656b-5048-482f-8eb2-d65b981889bd', '詠興五首 小庭亦有月', '詠兴五首 小庭亦有月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小庭亦有月，小院亦有花。","可憐好風景，不解嫌貧家。","菱角執笙簧，谷兒抹琵琶。","紅綃信手舞，紫綃隨意歌。","邨歌與社舞，客哂主人誇。","但問樂不樂，豈在鐘鼓多。","客告暮將歸，主稱日未斜。","請客稍深酌，願見朱顏酡。","客知主意厚，分數隨口加。","堂上燭未秉，座中冠已峩。","左顧短紅袖，右命小青娥。","長跪謝貴客，蓬門勞見過。","客散有餘興，醉臥獨吟哦。","幕天而席地，誰奈劉伶何。"]', '["小庭亦有月，小院亦有花。","可怜好风景，不解嫌貧家。","菱角執笙簧，谷兒抹琵琶。","紅綃信手舞，紫綃隨意歌。","邨歌與社舞，客哂主人誇。","但问乐不乐，豈在鐘鼓多。","客告暮將归，主稱日未斜。","請客稍深酌，願见朱顏酡。","客知主意厚，分數隨口加。","堂上燭未秉，座中冠已峩。","左顧短紅袖，右命小青娥。","长跪謝貴客，蓬门勞见過。","客散有餘兴，醉臥独吟哦。","幕天而席地，誰奈劉伶何。"]', '诗', 'shi', '', NULL, '詠興五首 小庭亦有月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beba8b40-7d12-4c06-8fd3-ea906d3a9cfc', '秋涼閑臥', '秋涼闲臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["殘暑晝猶長，早涼秋尚嫩。","露荷散清香，風竹含疎韻。","幽閑竟日臥，衰病無人問。","薄暮宅門前，槐花深一寸。"]', '["殘暑晝猶长，早涼秋尚嫩。","露荷散清香，风竹含疎韻。","幽闲竟日臥，衰病無人问。","薄暮宅门前，槐花深一寸。"]', '诗', 'shi', '', NULL, '秋涼閑臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('db893f49-35d4-45a2-91a3-dca2b0b03a06', '酬思黯相公見過弊居戲贈', '酬思黯相公见過弊居戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["軒蓋光照地，行人爲裴回。","呼傳君子出，乃是故人來。","訪我入窮巷，引君登小臺。","臺前多竹樹，池上無塵埃。","貧家何所有，新酒三兩桮。","停杯欵曲語，上馬復遲迴。","留守不外宿，日斜宮漏催。","但留金刀贈，未接玉山頹。","家醞不敢惜，待君來即開。","邨妓不辭出，恐君囅然咍。"]', '["軒蓋光照地，行人爲裴回。","呼傳君子出，乃是故人来。","訪我入窮巷，引君登小台。","台前多竹樹，池上無塵埃。","貧家何所有，新酒三兩桮。","停杯欵曲語，上马复遲迴。","留守不外宿，日斜宮漏催。","但留金刀贈，未接玉山頹。","家醞不敢惜，待君来即开。","邨妓不辞出，恐君囅然咍。"]', '诗', 'shi', '', NULL, '酬思黯相公見過弊居戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc512cd4-28f4-4dc9-889f-78a62befc7b6', '再授賓客分司', '再授賓客分司', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["優穩四皓官，清崇三品列。","伊予再塵忝，內媿非才哲。","俸錢七八萬，給受無虛月。","分命在東司，又不勞朝謁。","既資閑養疾，亦賴慵藏拙。","賓友得從容，琴觴恣怡悅。","乘籃城外去，繫馬花前歇。","六遊金谷春，五看龍門雪。","吾若默無語，安知吾快活。","吾欲更盡言，復恐人豪奪。","應爲時所笑，苦惜分司闕。","但問適意無，豈論官冷熱。"]', '["優穩四皓官，清崇三品列。","伊予再塵忝，內媿非才哲。","俸錢七八万，給受無虛月。","分命在东司，又不勞朝謁。","既資闲養疾，亦賴慵藏拙。","賓友得從容，琴觴恣怡悅。","乘籃城外去，繫马花前歇。","六游金谷春，五看龙门雪。","吾若默無語，安知吾快活。","吾欲更尽言，复恐人豪奪。","應爲时所笑，苦惜分司闕。","但问適意無，豈論官冷熱。"]', '诗', 'shi', '', NULL, '再授賓客分司 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f568d77f-83f7-412d-bb87-189954bfa074', '把酒', '把酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["把酒仰問天，古今誰不死。","所貴未死間，少憂多歡喜。","窮通諒在天，憂喜即由己。","是故達道人，去彼而取此。","勿言未富貴，久忝居祿仕。","借問宗族間，幾人拖金紫。","勿憂漸衰老，且喜加年紀。","試數班行中，幾人及暮齒。","朝飱不過飽，五鼎徒爲爾。","夕寢止求安，一衾而已矣。","此外皆長物，於我雲相似。","有子不留金，何況兼無子。"]', '["把酒仰问天，古今誰不死。","所貴未死间，少憂多歡喜。","窮通諒在天，憂喜即由己。","是故達道人，去彼而取此。","勿言未富貴，久忝居祿仕。","借问宗族间，幾人拖金紫。","勿憂漸衰老，且喜加年紀。","試數班行中，幾人及暮齒。","朝飱不過飽，五鼎徒爲爾。","夕寢止求安，一衾而已矣。","此外皆长物，於我云相似。","有子不留金，何況兼無子。"]', '诗', 'shi', '', NULL, '把酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ebc958c-7f4a-45f8-ae67-ecd19494640b', '首夏', '首夏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林靜蚊未生，池靜蛙未鳴。","景長天氣好，竟日和且清。","春禽餘哢在，夏木新陰成。","兀爾水邊坐，翛然橋上行。","自問一何適，身閑官不輕。","料錢隨月用，生計逐日營。","食飽慙伯夷，酒足媿淵明。","壽倍顏氏子，富百黔婁生。","有一即爲樂，況吾四者幷。","所以私自慰，雖老有心情。"]', '["林静蚊未生，池静蛙未鳴。","景长天氣好，竟日和且清。","春禽餘哢在，夏木新陰成。","兀爾水邊坐，翛然橋上行。","自问一何適，身闲官不轻。","料錢隨月用，生計逐日營。","食飽慙伯夷，酒足媿淵明。","壽倍顏氏子，富百黔婁生。","有一即爲乐，況吾四者幷。","所以私自慰，雖老有心情。"]', '诗', 'shi', '', NULL, '首夏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be1f2b7d-d935-425f-91bf-b209a9f95465', '代鶴', '代鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我本海上鶴，偶逢江南客。","感君一顧恩，同來洛陽陌。","洛陽寡族類，皎皎唯兩翼。","貌是天與高，色非日浴白。","主人誠可戀，其奈軒庭窄。","飲啄雜雞羣，年深損標格。","故鄉渺何處，雲水重重隔。","誰念深籠中，七換摩天翮。"]', '["我本海上鹤，偶逢江南客。","感君一顧恩，同来洛陽陌。","洛陽寡族類，皎皎唯兩翼。","貌是天與高，色非日浴白。","主人誠可戀，其奈軒庭窄。","饮啄杂雞羣，年深損標格。","故乡渺何处，云水重重隔。","誰念深籠中，七換摩天翮。"]', '诗', 'shi', '', NULL, '代鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0ee3250-3d9c-4772-bb26-57e9e36849a8', '立秋夕有懷夢得', '立秋夕有懷梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露簟荻竹清，風扇蒲葵輕。","一與故人別，再見新蟬鳴。","是夕涼飆起，閑境入幽情。","迴燈見棲鶴，隔竹聞吹笙。","夜茶一兩杓，秋吟三數聲。","所思渺千里，雲外長洲城。"]', '["露簟荻竹清，风扇蒲葵轻。","一與故人別，再见新蟬鳴。","是夕涼飆起，闲境入幽情。","迴灯见棲鹤，隔竹闻吹笙。","夜茶一兩杓，秋吟三數声。","所思渺千里，云外长洲城。"]', '诗', 'shi', '', NULL, '立秋夕有懷夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e35481cb-0c73-45aa-9e5d-87c4d22a9352', '哭崔常侍晦叔', '哭崔常侍晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頑賤一拳石，精珍百鍊金。","名價既相遠，交分何其深。","中誠一以合，外物不能侵。","逶迤二十年，與世同浮沈。","晚有退閑約，白首歸雲林。","垂老忽相失，悲哉口語心。","春日嵩高陽，秋夜清洛陰。","丘園共誰卜，山水共誰尋。","風月共誰賞，詩篇共誰吟。","花開共誰看，酒熟共誰斟。","惠死莊杜口，鍾歿師廢琴。","道理使之然，從古非獨今。","吾道自此孤，我情安可任。","唯將病眼淚，一灑秋風襟。"]', '["頑賤一拳石，精珍百鍊金。","名價既相远，交分何其深。","中誠一以合，外物不能侵。","逶迤二十年，與世同浮沈。","晚有退闲約，白首归云林。","垂老忽相失，悲哉口語心。","春日嵩高陽，秋夜清洛陰。","丘园共誰卜，山水共誰尋。","风月共誰賞，诗篇共誰吟。","花开共誰看，酒熟共誰斟。","惠死莊杜口，鍾歿師廢琴。","道理使之然，從古非独今。","吾道自此孤，我情安可任。","唯將病眼泪，一灑秋风襟。"]', '诗', 'shi', '', NULL, '哭崔常侍晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('818b0533-8cde-4fdb-9c52-ef4298a7cf45', '新秋曉興', '新秋晓兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["濁暑忽已退，清宵未全長。","晨釭耿殘焰，宿閤凝微香。","喔喔雞下樹，輝輝日上梁。","枕低茵席軟，臥穩身入牀。","睡足景猶早，起初風乍涼。","展張小屏幛，收拾生衣裳。","還有惆悵事，遲遲未能忘。","拂鏡梳白髮，可憐冰照霜。"]', '["濁暑忽已退，清宵未全长。","晨釭耿殘焰，宿閤凝微香。","喔喔雞下樹，輝輝日上梁。","枕低茵席軟，臥穩身入牀。","睡足景猶早，起初风乍涼。","展張小屏幛，收拾生衣裳。","還有惆悵事，遲遲未能忘。","拂镜梳白髮，可怜冰照霜。"]', '诗', 'shi', '', NULL, '新秋曉興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c212364e-7e5d-462a-b68d-6e58d6a261d8', '秋日與張賓客舒著作同遊龍門醉中狂歌凡二百三十八字', '秋日與張賓客舒著作同游龙门醉中狂歌凡二百三十八字', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秋天高高秋光清，秋風褭褭秋蟲鳴。","嵩峰餘霞錦綺卷，伊水細浪鱗甲生。","洛陽閑客知無數，少出遊山多在城。","商嶺老人自追逐，蓬丘逸士相逢迎。","南出鼎門十八里，莊店邐迤橋道平。","不寒不熱好時節，鞍馬穩快衣衫輕。","竝轡踟躕下西岸，扣舷容與繞中汀。","開懷曠達無所繫，觸目勝絕不可名。","荷衰欲黃荇猶綠，魚樂自躍鷗不驚。","翠藻蔓長孔雀尾，彩船櫓急寒雁聲。","家醞一壺白玉液，野花數把黃金英。","晝遊四看西日暮，夜話三及東方明。","暫停桮觴輟吟詠，我有狂言君試聽。","丈夫一生有二志，兼濟獨善難得幷。","不能救療生民病，即須先濯塵土纓。","況吾頭白眼已闇，終日戚促何所成。","不如展眉開口笑，龍門醉臥香山行。"]', '["秋天高高秋光清，秋风褭褭秋蟲鳴。","嵩峰餘霞錦綺卷，伊水細浪鱗甲生。","洛陽闲客知無數，少出游山多在城。","商嶺老人自追逐，蓬丘逸士相逢迎。","南出鼎门十八里，莊店邐迤橋道平。","不寒不熱好时節，鞍马穩快衣衫轻。","竝轡踟躕下西岸，扣舷容與繞中汀。","开懷曠達無所繫，觸目勝絕不可名。","荷衰欲黄荇猶綠，鱼乐自躍鷗不驚。","翠藻蔓长孔雀尾，彩船櫓急寒雁声。","家醞一壺白玉液，野花數把黄金英。","晝游四看西日暮，夜話三及东方明。","暫停桮觴輟吟詠，我有狂言君試听。","丈夫一生有二志，兼濟独善难得幷。","不能救療生民病，即須先濯塵土纓。","況吾头白眼已闇，終日戚促何所成。","不如展眉开口笑，龙门醉臥香山行。"]', '诗', 'shi', '', NULL, '秋日與張賓客舒著作同遊龍門醉中狂歌凡二百三十八字 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ecd311-3b50-4462-bc82-93c7878beba6', '履信池櫻桃島上醉後走筆送別舒員外兼寄宗正李卿考功崔郎中', '履信池櫻桃島上醉後走笔送別舒員外兼寄宗正李卿考功崔郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["櫻桃島前春，去春花萬枝。","忽憶與宗卿閑飲日，又憶與考功狂醉時。","歲晚無花空有葉，風吹滿地乾重疊。","蹋葉悲秋復憶春，池邊樹下重殷勤。","今朝一酌臨寒水，此地三迴別故人。","櫻桃花，來春千萬朵，來春共誰花下坐。","不論崔李上青雲，明日舒三亦拋我。"]', '["櫻桃島前春，去春花万枝。","忽憶與宗卿闲饮日，又憶與考功狂醉时。","歲晚無花空有葉，风吹满地乾重叠。","蹋葉悲秋复憶春，池邊樹下重殷勤。","今朝一酌臨寒水，此地三迴別故人。","櫻桃花，来春千万朵，来春共誰花下坐。","不論崔李上青云，明日舒三亦拋我。"]', '诗', 'shi', '', NULL, '履信池櫻桃島上醉後走筆送別舒員外兼寄宗正李卿考功崔郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8588f4b-f21f-4712-8c0b-d64a4bc6bc6a', '秋池獨汎', '秋池独汎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭疎秋竹籬，清淺秋風池。","一隻短舫艇，一張斑鹿皮。","皮上有野叟，手中持酒巵。","半酣箕踞坐，自問身爲誰。","嚴子垂釣日，蘇門長嘯時。","悠然意自得，意外何人知。"]', '["蕭疎秋竹籬，清淺秋风池。","一隻短舫艇，一張斑鹿皮。","皮上有野叟，手中持酒巵。","半酣箕踞坐，自问身爲誰。","嚴子垂釣日，蘇门长嘯时。","悠然意自得，意外何人知。"]', '诗', 'shi', '', NULL, '秋池獨汎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fe800ce-fb7a-4165-b586-13d0f8f2632f', '冬日早起閑詠', '冬日早起闲詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水塘耀初旭，風竹飄餘霰。","幽境雖目前，不因閑不見。","晨起對爐香，道經尋兩卷。","晚坐拂琴塵，秋思彈一遍。","此外更無事，開尊時自勸。","何必東風來，一桮春上面。"]', '["水塘耀初旭，风竹飄餘霰。","幽境雖目前，不因闲不见。","晨起对爐香，道經尋兩卷。","晚坐拂琴塵，秋思彈一遍。","此外更無事，开尊时自勸。","何必东风来，一桮春上面。"]', '诗', 'shi', '', NULL, '冬日早起閑詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0117e5d5-c8db-4de8-acba-a7b3040ce44b', '歲暮', '歲暮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慘澹歲云暮，窮陰動經旬。","霜風裂人面，冰雪摧車輪。","而我當是時，獨不知苦辛。","晨炊廩有米，夕爨廚有薪。","夾帽長覆耳，重裘寬裹身。","加之一桮酒，煦嫗如陽春。","洛城士與庶，比屋多飢貧。","何處爐有火，誰家甑無塵。","如我飽煖者，百人無一人。","安得不慙媿，放歌聊自陳。"]', '["慘澹歲云暮，窮陰动經旬。","霜风裂人面，冰雪摧车輪。","而我當是时，独不知苦辛。","晨炊廩有米，夕爨廚有薪。","夾帽长覆耳，重裘寬裹身。","加之一桮酒，煦嫗如陽春。","洛城士與庶，比屋多飢貧。","何处爐有火，誰家甑無塵。","如我飽煖者，百人無一人。","安得不慙媿，放歌聊自陳。"]', '诗', 'shi', '', NULL, '歲暮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a918c50-8e39-4234-b4ec-b6b25abef385', '南池早春有懷', '南池早春有懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝遊北橋上，晚憩南塘畔。","西日雪全銷，東風冰盡泮。","簁簁魚尾掉，瞥瞥鵝毛換。","泥煖草芽生，沙虛泉脉散。","晴芳冒苔島，宿潤侵蒲岸。","洛下日初長，江南春欲半。","時光共拋擲，人事堪嗟歎。","倚櫂忽尋思，去年池上伴。"]', '["朝游北橋上，晚憩南塘畔。","西日雪全銷，东风冰尽泮。","簁簁鱼尾掉，瞥瞥鵝毛換。","泥煖草芽生，沙虛泉脉散。","晴芳冒苔島，宿潤侵蒲岸。","洛下日初长，江南春欲半。","时光共拋擲，人事堪嗟歎。","倚櫂忽尋思，去年池上伴。"]', '诗', 'shi', '', NULL, '南池早春有懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1844a3d-fdbe-4516-9e0b-1be943cc3f95', '古意', '古意', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["脉脉復脉脉，美人千里隔。","不見來幾時，瑤草三四碧。","玉琴聲悄悄，鸞鏡塵幂幂。","昔爲連理枝，今作分飛翮。","寄書多不達，加飯終無益。","心腸不自寬，衣帶何由窄。"]', '["脉脉复脉脉，美人千里隔。","不见来幾时，瑤草三四碧。","玉琴声悄悄，鸾镜塵幂幂。","昔爲連理枝，今作分飞翮。","寄书多不達，加飯終無益。","心腸不自寬，衣带何由窄。"]', '诗', 'shi', '', NULL, '古意 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('abdb806a-96be-4349-9dea-9d69424790f0', '山遊示小妓', '山游示小妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雙鬟垂未合，三十纔過半。","本是綺羅人，今爲山水伴。","春泉共揮弄，好樹同攀翫。","笑容花底迷，酒思風前亂。","紅凝舞袖急，黛慘歌聲緩。","莫唱楊柳枝，無腸與君斷。"]', '["雙鬟垂未合，三十纔過半。","本是綺羅人，今爲山水伴。","春泉共揮弄，好樹同攀翫。","笑容花底迷，酒思风前亂。","紅凝舞袖急，黛慘歌声緩。","莫唱楊柳枝，無腸與君斷。"]', '诗', 'shi', '', NULL, '山遊示小妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab67a2a1-434d-4b14-bde1-cab1c3029c7a', '神照禪師同宿', '神照禪師同宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["八年三月晦，山梨花滿枝。","龍門水西寺，夜與遠公期。","晏坐自相對，密語誰得知。","前後際斷處，一念不生時。"]', '["八年三月晦，山梨花满枝。","龙门水西寺，夜與远公期。","晏坐自相对，密語誰得知。","前後際斷处，一念不生时。"]', '诗', 'shi', '', NULL, '神照禪師同宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6be80d0-1ded-4705-a4e5-e07d605f5977', '張常侍相訪', '張常侍相訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西亭晚寂寞，鶯散柳陰繁。","水戶簾不卷，風牀席自翻。","忽聞車馬客，來訪蓬蒿門。","況是張常侍，安得不開尊。"]', '["西亭晚寂寞，鶯散柳陰繁。","水戶簾不卷，风牀席自翻。","忽闻车马客，来訪蓬蒿门。","況是張常侍，安得不开尊。"]', '诗', 'shi', '', NULL, '張常侍相訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1026e962-dab6-4aa8-ba24-a97e2588716e', '早夏遊宴', '早夏游宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雖慵興猶在，雖老心猶健。","昨日山水遊，今朝花酒宴。","山榴豔似火，玉蘂飄如霰。","榮落逐瞬遷，炎涼隨刻變。","未收木綿褥，已動蒲葵扇。","且喜物與人，年年得相見。"]', '["雖慵兴猶在，雖老心猶健。","昨日山水游，今朝花酒宴。","山榴豔似火，玉蘂飄如霰。","榮落逐瞬遷，炎涼隨刻变。","未收木綿褥，已动蒲葵扇。","且喜物與人，年年得相见。"]', '诗', 'shi', '', NULL, '早夏遊宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d54a9db-1241-4f29-a80c-983c998449ab', '感白蓮花', '感白蓮花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白白芙蓉花，本生吳江濆。","不與紅者雜，色類自區分。","誰移爾至此，姑蘇白使君。","初來苦顦顇，久乃芳氛氳。","月月葉換葉，年年根生根。","陳根與故葉，銷化成泥塵。","化者日已遠，來者日復新。","一爲池中物，永別江南春。","忽想西涼州，中有天寶民。","埋歿漢父祖，孳生胡子孫。","已忘鄉土戀，豈念君親恩。","生人尚復爾，草木何足云。"]', '["白白芙蓉花，本生吳江濆。","不與紅者杂，色類自區分。","誰移爾至此，姑蘇白使君。","初来苦顦顇，久乃芳氛氳。","月月葉換葉，年年根生根。","陳根與故葉，銷化成泥塵。","化者日已远，来者日复新。","一爲池中物，永別江南春。","忽想西涼州，中有天寶民。","埋歿漢父祖，孳生胡子孫。","已忘乡土戀，豈念君親恩。","生人尚复爾，草木何足云。"]', '诗', 'shi', '', NULL, '感白蓮花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa149687-f77d-41b6-924e-15ad6cb964d4', '詠所樂', '詠所乐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獸樂在山谷，魚樂在陂池。","蟲樂在深草，鳥樂在高枝。","所樂雖不同，同歸適其宜。","不以彼易此，況論是與非。","而我何所樂，所樂在分司。","分司有何樂，樂哉人不知。","官優有祿料，職散無羈縻。","嬾與道相近，鈍將閑自隨。","昨朝拜表迴，今晚行香歸。","歸來北窗下，解巾脫塵衣。","冷泉灌我頂，暖水濯四肢。","體中幸無疾，臥任清風吹。","心中又無事，坐任白日移。","或開書一篇，或引酒一巵。","但得如今日，終身無厭時。"]', '["獸乐在山谷，鱼乐在陂池。","蟲乐在深草，鸟乐在高枝。","所乐雖不同，同归適其宜。","不以彼易此，況論是與非。","而我何所乐，所乐在分司。","分司有何乐，乐哉人不知。","官優有祿料，職散無羈縻。","嬾與道相近，鈍將闲自隨。","昨朝拜表迴，今晚行香归。","归来北窗下，解巾脫塵衣。","冷泉灌我頂，暖水濯四肢。","體中幸無疾，臥任清风吹。","心中又無事，坐任白日移。","或开书一篇，或引酒一巵。","但得如今日，終身無厭时。"]', '诗', 'shi', '', NULL, '詠所樂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02f64524-4ac6-426b-b0a2-3c61f473c49e', '思舊', '思旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑日一思舊，舊遊如目前。","再思今何在，零落歸下泉。","退之服硫黃，一病訖不痊。","微之鍊秋石，未老身溘然。","杜子得丹訣，終日斷腥羶。","崔君誇藥力，經冬不衣綿。","或疾或暴夭，悉不過中年。","唯予不服食，老命反遲延。","況在少壯時，亦爲嗜慾牽。","但躭葷與血，不識汞與鉛。","飢來吞熱物，渴來飲寒泉。","詩役五藏神，酒汨三丹田。","隨日合破壞，至今粗完全。","齒牙未缺落，肢體尚輕便。","已開第七秩，飽食仍安眠。","且進桮中物，其餘皆付天。"]', '["闲日一思旧，旧游如目前。","再思今何在，零落归下泉。","退之服硫黄，一病訖不痊。","微之鍊秋石，未老身溘然。","杜子得丹訣，終日斷腥羶。","崔君誇藥力，經冬不衣綿。","或疾或暴夭，悉不過中年。","唯予不服食，老命反遲延。","況在少壯时，亦爲嗜慾牽。","但躭葷與血，不識汞與鉛。","飢来吞熱物，渴来饮寒泉。","诗役五藏神，酒汨三丹田。","隨日合破壞，至今粗完全。","齒牙未缺落，肢體尚轻便。","已开第七秩，飽食仍安眠。","且進桮中物，其餘皆付天。"]', '诗', 'shi', '', NULL, '思舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4ca9f3b-5892-49fb-9c33-7adc9b11240b', '寄盧少尹', '寄盧少尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老誨心不亂，莊戒形太勞。","生命既能保，死籍亦可逃。","嘉肴與旨酒，信是腐腸膏。","豔聲與麗色，真爲伐性刀。","補養在積功，如裘集衆毛。","將欲致千里，可得差一毫。","顏回何爲者，簟瓢纔自給。","肥醲不到口，年不登三十。","張蒼何爲者，染愛浩無際。","妾媵填後房，竟壽百餘歲。","蒼壽有何德，回夭有何辜。","誰謂具聖體，不如肥瓠軀。","遂使世俗心，多疑仙道書。","寄問盧先生，此理當何如。"]', '["老誨心不亂，莊戒形太勞。","生命既能保，死籍亦可逃。","嘉肴與旨酒，信是腐腸膏。","豔声與丽色，真爲伐性刀。","補養在積功，如裘集衆毛。","將欲致千里，可得差一毫。","顏回何爲者，簟瓢纔自給。","肥醲不到口，年不登三十。","張蒼何爲者，染愛浩無際。","妾媵填後房，竟壽百餘歲。","蒼壽有何德，回夭有何辜。","誰謂具聖體，不如肥瓠軀。","遂使世俗心，多疑仙道书。","寄问盧先生，此理當何如。"]', '诗', 'shi', '', NULL, '寄盧少尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a19971b2-76b4-4275-9b1b-ab55ac1c3e57', '池上清晨候皇甫郎中', '池上清晨候皇甫郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉景麗未熱，晨飆鮮且涼。","池幽綠蘋合，霜潔白蓮香。","深掃竹間逕，靜拂松下牀。","玉柄鶴翎扇，銀甖雲母漿。","屏除無俗物，瞻望唯清光。","何人擬相訪，嬴女從蕭郎。"]', '["晓景丽未熱，晨飆鲜且涼。","池幽綠蘋合，霜潔白蓮香。","深掃竹间逕，静拂松下牀。","玉柄鹤翎扇，銀甖云母漿。","屏除無俗物，瞻望唯清光。","何人擬相訪，嬴女從蕭郎。"]', '诗', 'shi', '', NULL, '池上清晨候皇甫郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14c1510d-2c74-4ece-b1a7-03cf5b7e85a7', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我知世無幻，了無干世意。","世知我無堪，亦無責我事。","由茲兩相忘，因得長自遂。","自遂意何如，閑官在閑地。","閑地唯東都，東都少名利。","閑官是賓客，賓客無牽累。","嵇康日日嬾，畢卓時時醉。","酒肆夜深歸，僧房日高睡。","形安不勞苦，神泰無憂畏。","從官三十年，無如今氣味。","鴻雖脫羅弋，鶴尚居祿位。","唯此未忘懷，有時猶內媿。"]', '["我知世無幻，了無干世意。","世知我無堪，亦無責我事。","由茲兩相忘，因得长自遂。","自遂意何如，闲官在闲地。","闲地唯东都，东都少名利。","闲官是賓客，賓客無牽累。","嵇康日日嬾，畢卓时时醉。","酒肆夜深归，僧房日高睡。","形安不勞苦，神泰無憂畏。","從官三十年，無如今氣味。","鴻雖脫羅弋，鹤尚居祿位。","唯此未忘懷，有时猶內媿。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7db29278-1cf2-4870-b69c-ab1985eee7c7', '北窗三友', '北窗三友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日北窗下，自問何所爲。","欣然得三友，三友者爲誰。","琴罷輙舉酒，酒罷輙吟詩。","三友遞相引，循環無已時。","一彈愜中心，一詠暢四肢。","猶恐中有間，以酒彌縫之。","豈獨吾拙好，古人多若斯。","嗜詩有淵明，嗜琴有啓期。","嗜酒有伯倫，三人皆吾師。","或乏儋石儲，或穿帶索衣。","弦歌復觴詠，樂道知所歸。","三師去已遠，高風不可追。","三友游甚熟，無日不相隨。","左擲白玉巵，右拂黃金徽。","興酣不疊紙，走筆操狂詞。","誰能持此詞，爲我謝親知。","縱未以爲是，豈以我爲非。"]', '["今日北窗下，自问何所爲。","欣然得三友，三友者爲誰。","琴罷輙舉酒，酒罷輙吟诗。","三友遞相引，循环無已时。","一彈愜中心，一詠暢四肢。","猶恐中有间，以酒彌縫之。","豈独吾拙好，古人多若斯。","嗜诗有淵明，嗜琴有啓期。","嗜酒有伯倫，三人皆吾師。","或乏儋石儲，或穿带索衣。","弦歌复觴詠，乐道知所归。","三師去已远，高风不可追。","三友游甚熟，無日不相隨。","左擲白玉巵，右拂黄金徽。","兴酣不叠紙，走笔操狂词。","誰能持此词，爲我謝親知。","縱未以爲是，豈以我爲非。"]', '诗', 'shi', '', NULL, '北窗三友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31911b6a-c2ca-4f33-a552-54825df4f32f', '吟四雖', '吟四雖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒酣後，歌歇時。","請君添一酌，聽我吟四雖。","年雖老，猶少於韋長史。","命雖薄，猶勝於鄭長水。","眼雖病，猶明於徐郎中。","家雖貧，猶富於郭庶子。","省躬審分何僥倖，值酒逢歌且歡喜。","忘榮知足委天和，亦應得盡生生理。"]', '["酒酣後，歌歇时。","請君添一酌，听我吟四雖。","年雖老，猶少於韋长史。","命雖薄，猶勝於鄭长水。","眼雖病，猶明於徐郎中。","家雖貧，猶富於郭庶子。","省躬審分何僥倖，值酒逢歌且歡喜。","忘榮知足委天和，亦應得尽生生理。"]', '诗', 'shi', '', NULL, '吟四雖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37bf0606-38ba-4d3b-895c-ecfc497508a3', '裴侍中晉公以集賢林亭即事詩三十六韻見贈猥蒙徵和才拙詞繁輙廣爲五百言以伸酬獻', '裴侍中晉公以集賢林亭即事诗三十六韻见贈猥蒙徵和才拙词繁輙廣爲五百言以伸酬獻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三江路千里，五湖天一涯。","何如集賢第，中有平津池。","池勝主見覺，景新人未知。","竹森翠琅玕，水深洞琉璃。","水竹以爲質，質立而文隨。","文之者何人，公來親指麾。","疏鑿出人意，結構得地宜。","靈襟一搜索，勝概無遁遺。","因下張沼沚，依高築階基。","嵩峰見數片，伊水分一支。","南溪修且直，長波碧逶迤。","北館壯復麗，倒影紅參差。","東島號晨光，杲曜迎朝曦。","西嶺名夕陽，杳曖留落暉。","前有水心亭，動蕩架漣漪。","後有開闔堂，寒溫變天時。","幽泉鏡泓澄，怪石山欹危。","春葩雪漠漠，夏果珠離離。","主人命方舟，宛在水中坻。","親賓次第至，酒樂前後施。","解纜始登汎，山遊仍水嬉。","沿洄無滯礙，向背窮幽奇。","瞥過遠橋下，飄旋深澗陲。","管弦去縹緲，羅綺來霏微。","櫂風逐舞迴，梁塵隨歌飛。","宴餘日云暮，醉客未放歸。","高聲索彩牋，大笑催金巵。","唱和筆走疾，問荅桮行遲。","一詠清兩耳，一酣暢四肢。","主客忘貴賤，不知俱是誰。","客有詩魔者，吟哦不知疲。","乞公殘紙墨，一掃狂歌詞。","維云社稷臣，赫赫文武姿。","十授丞相印，五建大將旗。","四朝致勛華，一身冠臯夔。","去年才七十，決赴懸車期。","公志不可奪，君恩亦難希。","從容就中道，俛僶來保釐。","貂蟬雖未脫，鸞皇已不羈。","歷徵今與古，獨步無等夷。","陸賈功業少，二疏官秩卑。","乘舟范蠡懼，辟穀留侯飢。","豈若公今日，身安家國肥。","羊祜在漢南，空留峴首碑。","柳惲在江南，祗賦汀洲詩。","謝安入東山，但說攜蛾眉。","山簡醉高陽，唯聞倒接䍦。","豈如公今日，餘力兼有之。","願公壽如山，安樂長在茲。","願我比蒲稗，永得相因依。"]', '["三江路千里，五湖天一涯。","何如集賢第，中有平津池。","池勝主见覺，景新人未知。","竹森翠琅玕，水深洞琉璃。","水竹以爲質，質立而文隨。","文之者何人，公来親指麾。","疏鑿出人意，結構得地宜。","靈襟一搜索，勝概無遁遺。","因下張沼沚，依高築階基。","嵩峰见數片，伊水分一支。","南溪修且直，长波碧逶迤。","北館壯复丽，倒影紅參差。","东島號晨光，杲曜迎朝曦。","西嶺名夕陽，杳曖留落暉。","前有水心亭，动蕩架漣漪。","後有开闔堂，寒溫变天时。","幽泉镜泓澄，怪石山欹危。","春葩雪漠漠，夏果珠離離。","主人命方舟，宛在水中坻。","親賓次第至，酒乐前後施。","解纜始登汎，山游仍水嬉。","沿洄無滯礙，向背窮幽奇。","瞥過远橋下，飄旋深澗陲。","管弦去縹緲，羅綺来霏微。","櫂风逐舞迴，梁塵隨歌飞。","宴餘日云暮，醉客未放归。","高声索彩牋，大笑催金巵。","唱和笔走疾，问荅桮行遲。","一詠清兩耳，一酣暢四肢。","主客忘貴賤，不知俱是誰。","客有诗魔者，吟哦不知疲。","乞公殘紙墨，一掃狂歌词。","維云社稷臣，赫赫文武姿。","十授丞相印，五建大將旗。","四朝致勛华，一身冠臯夔。","去年才七十，決赴懸车期。","公志不可奪，君恩亦难希。","從容就中道，俛僶来保釐。","貂蟬雖未脫，鸾皇已不羈。","歷徵今與古，独步無等夷。","陸賈功業少，二疏官秩卑。","乘舟范蠡懼，辟穀留侯飢。","豈若公今日，身安家国肥。","羊祜在漢南，空留峴首碑。","柳惲在江南，祗賦汀洲诗。","謝安入东山，但说携蛾眉。","山簡醉高陽，唯闻倒接䍦。","豈如公今日，餘力兼有之。","願公壽如山，安乐长在茲。","願我比蒲稗，永得相因依。"]', '诗', 'shi', '', NULL, '裴侍中晉公以集賢林亭即事詩三十六韻見贈猥蒙徵和才拙詞繁輙廣爲五百言以伸酬獻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c8a2a84-33f3-4bfd-b25c-2cc913d0754d', '晚歸香山寺因詠所懷', '晚归香山寺因詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我年日已老，我身日已閑。","閑出都門望，但見水與山。","關塞碧巖巖，伊流清潺潺。","中有古精舍，軒戶無扃關。","岸草歇可藉，逕蘿行可攀。","朝隨浮雲出，夕與飛鳥還。","吾道本迂拙，世途多險艱。","嘗聞嵇呂輩，尤悔生疎頑。","巢悟入箕潁，皓知返商巔。","豈唯樂肥遁，聊復祛憂患。","吾亦從此去，終老伊嵩間。"]', '["我年日已老，我身日已闲。","闲出都门望，但见水與山。","关塞碧巖巖，伊流清潺潺。","中有古精舍，軒戶無扃关。","岸草歇可藉，逕蘿行可攀。","朝隨浮云出，夕與飞鸟還。","吾道本迂拙，世途多險艱。","嘗闻嵇呂輩，尤悔生疎頑。","巢悟入箕潁，皓知返商巔。","豈唯乐肥遁，聊复祛憂患。","吾亦從此去，終老伊嵩间。"]', '诗', 'shi', '', NULL, '晚歸香山寺因詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dcdf269b-58d3-4501-acbd-821b4bde90ac', '張常侍池涼夜閑讌贈諸公', '張常侍池涼夜闲讌贈諸公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["竹橋新月上，水岸涼風至。","對月五六人，管弦三兩事。","留連池上酌，款曲城外意。","或嘯或謳吟，誰知此閑味。","迴看市朝客，矻矻趨名利。","朝忙少遊宴，夕困多眠睡。","清涼屬吾徒，相逢勿辭醉。"]', '["竹橋新月上，水岸涼风至。","对月五六人，管弦三兩事。","留連池上酌，款曲城外意。","或嘯或謳吟，誰知此闲味。","迴看市朝客，矻矻趨名利。","朝忙少游宴，夕困多眠睡。","清涼屬吾徒，相逢勿辞醉。"]', '诗', 'shi', '', NULL, '張常侍池涼夜閑讌贈諸公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('912f9d6c-f2f1-49fc-9361-2d7d4358efc3', '和皇甫郎中秋曉同登天宮閣言懷六韻', '和皇甫郎中秋晓同登天宮閣言懷六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["碧天忽已高，白日猶未短。","玲瓏曉樓閣，清脆秋絲管。","張翰一桮酣，嵇康終日嬾。","塵中足憂累，雲外多疎散。","病木斧斤遺，冥鴻羈緤斷。","逍遙二三子，永願爲閑伴。"]', '["碧天忽已高，白日猶未短。","玲瓏晓楼閣，清脆秋絲管。","張翰一桮酣，嵇康終日嬾。","塵中足憂累，云外多疎散。","病木斧斤遺，冥鴻羈緤斷。","逍遙二三子，永願爲闲伴。"]', '诗', 'shi', '', NULL, '和皇甫郎中秋曉同登天宮閣言懷六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ad746eb-c18f-4c2f-b9af-fc5e77ddd31b', '送呂漳州', '送呂漳州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝一壺酒，言送漳州牧。","半自要閑遊，愛花憐草綠。","花前下鞍馬，草上攜絲竹。","行客飲數桮，主人歌一曲。","端居惜風景，屢出勞僮僕。","獨醉似無名，借君作題目。"]', '["今朝一壺酒，言送漳州牧。","半自要闲游，愛花怜草綠。","花前下鞍马，草上携絲竹。","行客饮數桮，主人歌一曲。","端居惜风景，屢出勞僮僕。","独醉似無名，借君作題目。"]', '诗', 'shi', '', NULL, '送呂漳州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3edc8818-0eff-4805-8868-291aa99eb8f2', '短歌曲', '短歌曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世人求富貴，多爲奉嗜欲。","盛衰不自由，得失常相逐。","問君少年日，苦學將干祿。","負笈塵中遊，抱書雪前讀。","布衾不周體，藜茹纔充腹。","三十登宦途，五十被朝服。","奴溫新挾纊，馬肥初食粟。","未敢議歡遊，尚爲名檢束。","耳目聾闇後，堂上調絲竹。","牙齒缺落時，盤中堆酒肉。","彼來此已去，外餘中不足。","少壯與榮華，相避如寒燠。","青雲去地遠，白日經天速。","從古無奈何，短歌聽一曲。"]', '["世人求富貴，多爲奉嗜欲。","盛衰不自由，得失常相逐。","问君少年日，苦学將干祿。","負笈塵中游，抱书雪前读。","布衾不周體，藜茹纔充腹。","三十登宦途，五十被朝服。","奴溫新挾纊，马肥初食粟。","未敢議歡游，尚爲名檢束。","耳目聾闇後，堂上調絲竹。","牙齒缺落时，盤中堆酒肉。","彼来此已去，外餘中不足。","少壯與榮华，相避如寒燠。","青云去地远，白日經天速。","從古無奈何，短歌听一曲。"]', '诗', 'shi', '', NULL, '短歌曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d3d2354-068b-4d4a-9e18-a3139865ee04', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高人樂丘園，中人慕官職。","一事尚難成，兩途安可得。","遑遑干世者，多苦時命塞。","亦有愛閑人，又爲窮餓逼。","我今幸雙遂，祿仕兼游息。","未嘗羨榮華，不省勞心力。","妻孥與婢僕，亦免愁衣食。","所以吾一家，面無憂喜色。"]', '["高人乐丘园，中人慕官職。","一事尚难成，兩途安可得。","遑遑干世者，多苦时命塞。","亦有愛闲人，又爲窮餓逼。","我今幸雙遂，祿仕兼游息。","未嘗羨榮华，不省勞心力。","妻孥與婢僕，亦免愁衣食。","所以吾一家，面無憂喜色。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d03704c-8423-4662-a90e-68290cd40cef', '府西亭納涼歸', '府西亭納涼归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["避暑府西亭，晚歸有閑思。","夏淺蟬未多，綠槐陰滿地。","帶寬衫解領，馬穩人攏轡。","面上有涼風，眼前無俗事。","路經府門過，落日照官次。","牽聯縲紲囚，奔走塵埃吏。","低眉悄不語，誰復知茲意。","憶得五年前，晚衙時氣味。"]', '["避暑府西亭，晚归有闲思。","夏淺蟬未多，綠槐陰满地。","带寬衫解領，马穩人攏轡。","面上有涼风，眼前無俗事。","路經府门過，落日照官次。","牽聯縲紲囚，奔走塵埃吏。","低眉悄不語，誰复知茲意。","憶得五年前，晚衙时氣味。"]', '诗', 'shi', '', NULL, '府西亭納涼歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6bdb2b7e-568c-46e9-becb-eeff46b500a9', '老熱', '老熱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一飽百情足，一酣萬事休。","何人不衰老，我老心無憂。","仕者拘職役，農者勞田疇。","何人不苦熱，我熱身自由。","臥風北窗下，坐月南池頭。","腦涼脫烏帽，足熱濯清流。","慵發晝高枕，興來夜汎舟。","何乃有餘適，祗緣無過求。","或問諸親友，樂天是與不。","亦無別言語，多道天悠悠。","悠悠君不知，此味深且幽。","但恐君知後，亦來從我遊。"]', '["一飽百情足，一酣万事休。","何人不衰老，我老心無憂。","仕者拘職役，農者勞田疇。","何人不苦熱，我熱身自由。","臥风北窗下，坐月南池头。","腦涼脫烏帽，足熱濯清流。","慵發晝高枕，兴来夜汎舟。","何乃有餘適，祗緣無過求。","或问諸親友，乐天是與不。","亦無別言語，多道天悠悠。","悠悠君不知，此味深且幽。","但恐君知後，亦来從我游。"]', '诗', 'shi', '', NULL, '老熱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcffc7f7-f392-48fe-805d-c9cd42b21903', '新秋喜涼因寄兵部楊侍郎', '新秋喜涼因寄兵部楊侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["外強火未退，中銳金方戰。","一夕風雨來，炎涼隨數變。","徐徐炎景度，稍稍涼飆扇。","枕簟忽淒清，巾裳亦輕健。","老夫納秋候，心體殊安便。","睡足一屈伸，搔首摩挲面。","褰簾對池竹，幽寂如僧院。","俯觀游魚羣，仰數浮雲片。","閑忙各有趣，彼此寧相見。","昨日聞慕巢，召對延英殿。"]', '["外強火未退，中銳金方戰。","一夕风雨来，炎涼隨數变。","徐徐炎景度，稍稍涼飆扇。","枕簟忽淒清，巾裳亦轻健。","老夫納秋候，心體殊安便。","睡足一屈伸，搔首摩挲面。","褰簾对池竹，幽寂如僧院。","俯观游鱼羣，仰數浮云片。","闲忙各有趣，彼此寧相见。","昨日闻慕巢，召对延英殿。"]', '诗', 'shi', '', NULL, '新秋喜涼因寄兵部楊侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('760442d4-9a7c-4444-9212-d5890154df7d', '嬾放二首呈劉夢得吳方之 一', '嬾放二首呈劉梦得吳方之 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青衣報平旦，呼我起盥櫛。","今早天氣寒，郎君應不出。","又無賓客至，何以銷閑日。","已向微陽前，煖酒開詩帙。"]', '["青衣報平旦，呼我起盥櫛。","今早天氣寒，郎君應不出。","又無賓客至，何以銷闲日。","已向微陽前，煖酒开诗帙。"]', '诗', 'shi', '', NULL, '嬾放二首呈劉夢得吳方之 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4233a6e-b302-496a-a098-e85a032c57d0', '嬾放二首呈劉夢得吳方之 二', '嬾放二首呈劉梦得吳方之 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朝憐一牀日，暮愛一爐火。","牀暖日高眠，爐溫夜深坐。","雀羅門嬾出，鶴髮頭慵裹。","除却劉與吳，何人來問我。"]', '["朝怜一牀日，暮愛一爐火。","牀暖日高眠，爐溫夜深坐。","雀羅门嬾出，鹤髮头慵裹。","除却劉與吳，何人来问我。"]', '诗', 'shi', '', NULL, '嬾放二首呈劉夢得吳方之 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a516808c-976a-4059-b00c-e06e883cca1c', '六十六', '六十六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病知心力減，老覺光陰速。","五十八歸來，今年六十六。","鬢絲千萬白，池草八九綠。","童稚盡成人，園林半喬木。","看山倚高石，引水穿深竹。","雖有潺湲聲，至今聽未足。"]', '["病知心力減，老覺光陰速。","五十八归来，今年六十六。","鬢絲千万白，池草八九綠。","童稚尽成人，园林半喬木。","看山倚高石，引水穿深竹。","雖有潺湲声，至今听未足。"]', '诗', 'shi', '', NULL, '六十六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da46e373-98bd-4154-afbe-929348469124', '三適贈道友', '三適贈道友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["褐綾袍厚暖，臥蓋行坐披。","紫氈履寬穩，蹇步頗相宜。","足適已忘履，身適已忘衣。","況我心又適，兼忘是與非。","三適今爲一，怡怡復熙熙。","禪那不動處，混沌未鑿時。","此固不可說，爲君強言之。"]', '["褐綾袍厚暖，臥蓋行坐披。","紫氈履寬穩，蹇步頗相宜。","足適已忘履，身適已忘衣。","況我心又適，兼忘是與非。","三適今爲一，怡怡复熙熙。","禪那不动处，混沌未鑿时。","此固不可说，爲君強言之。"]', '诗', 'shi', '', NULL, '三適贈道友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('342d57c0-3644-4efe-8639-19ada687b0fa', '洛陽春贈劉李二賓客', '洛陽春贈劉李二賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水南冠蓋地，城東桃李園。","雪消洛陽堰，春入永通門。","淑景方靄靄，遊人稍喧喧。","年豐酒漿賤，日晏歌吹繁。","中有老朝客，華髮暎朱軒。","從容三兩人，藉草開一尊。","尊前春可惜，身外事勿論。","明日期何處，杏花遊趙村。"]', '["水南冠蓋地，城东桃李园。","雪消洛陽堰，春入永通门。","淑景方靄靄，游人稍喧喧。","年豐酒漿賤，日晏歌吹繁。","中有老朝客，华髮暎朱軒。","從容三兩人，藉草开一尊。","尊前春可惜，身外事勿論。","明日期何处，杏花游趙村。"]', '诗', 'shi', '', NULL, '洛陽春贈劉李二賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4bbe0a31-d4e2-4194-9763-117fb08e1006', '寒食', '寒食', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人老何所樂，樂在歸鄉國。","我歸故園來，九度逢寒食。","故園在何處，池館東城側。","四隣梨花時，二月伊水色。","豈獨好風土，仍多舊親戚。","出去恣歡遊，歸來聊燕息。","有官供祿俸，無事勞心力。","但恐優穩多，微躬銷不得。"]', '["人老何所乐，乐在归乡国。","我归故园来，九度逢寒食。","故园在何处，池館东城側。","四隣梨花时，二月伊水色。","豈独好风土，仍多旧親戚。","出去恣歡游，归来聊燕息。","有官供祿俸，無事勞心力。","但恐優穩多，微躬銷不得。"]', '诗', 'shi', '', NULL, '寒食 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('254d3b66-8f9d-4f78-a8d2-d777405b339c', '和裴令公一日日一年年雜言見贈', '和裴令公一日日一年年杂言见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一日日，作老翁。","一年年，過春風。","公心不以貴隔我，我散唯將閑伴公。","我無才能忝高秩，合是人間閑散物。","公有功德在生民，何因得作自由身。","前日魏王潭上宴連夜，今日午橋池頭遊拂晨。","山客硯前吟待月，野人尊前醉送春。","不敢與公閑中爭第一，亦應占得第二第三人。"]', '["一日日，作老翁。","一年年，過春风。","公心不以貴隔我，我散唯將闲伴公。","我無才能忝高秩，合是人间闲散物。","公有功德在生民，何因得作自由身。","前日魏王潭上宴連夜，今日午橋池头游拂晨。","山客硯前吟待月，野人尊前醉送春。","不敢與公闲中爭第一，亦應占得第二第三人。"]', '诗', 'shi', '', NULL, '和裴令公一日日一年年雜言見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07ea26ba-4e27-4a33-bc83-2b41ebfa0ba6', '題裴晉公女几山刻石詩後', '題裴晉公女几山刻石诗後', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處畫功業，何處題詩篇？","麒麟高閣上，女几小山前。","爾後多少時，四朝二十年。","賊骨化爲土，賊壘犂爲田。","一從賊壘平，陳蔡民晏然。","騾軍成牛戶，鬼火變人煙。","生子已嫁娶，種桑亦絲緜。","皆云公之德，欲報無由緣。","公今在何處，守都鎮三川。","舊宅留永樂，新居開集賢。","公今在何官，被衮珥貂蟬。","戰袍破猶在，髀肉生欲圓。","襟懷轉蕭灑，氣力彌精堅。","登山不拄杖，上馬能掉鞭。","利澤浸入池，福降昇自天。","昔號天下將，今稱地上仙。","勿追赤松遊，勿拍洪崖肩。","商山有遺老，可以奉周旋。"]', '["何处畫功業，何处題诗篇？","麒麟高閣上，女几小山前。","爾後多少时，四朝二十年。","賊骨化爲土，賊壘犂爲田。","一從賊壘平，陳蔡民晏然。","騾軍成牛戶，鬼火变人煙。","生子已嫁娶，種桑亦絲緜。","皆云公之德，欲報無由緣。","公今在何处，守都鎮三川。","旧宅留永乐，新居开集賢。","公今在何官，被衮珥貂蟬。","戰袍破猶在，髀肉生欲圓。","襟懷轉蕭灑，氣力彌精堅。","登山不拄杖，上马能掉鞭。","利澤浸入池，福降昇自天。","昔號天下將，今稱地上仙。","勿追赤松游，勿拍洪崖肩。","商山有遺老，可以奉周旋。"]', '诗', 'shi', '', NULL, '題裴晉公女几山刻石詩後 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c13f70df-ae15-4a3c-ba96-45e817a7c1ab', '洛陽有愚叟', '洛陽有愚叟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛陽有愚叟，白黑無分別。","浪跡雖似狂，謀身亦不拙。","點檢盤中飯，非精亦非糲。","點檢身上衣，無餘亦無闕。","天時方得所，不寒復不熱。","體氣正調和，不飢仍不渴。","閑將酒壺出，醉向人家歇。","野食或烹鮮，寓眠多擁褐。","抱琴榮啓樂，荷鍤劉伶達。","放眼看青山，任頭生白髮。","不知天地內，更得幾年活。","從此到終身，盡爲閑日月。"]', '["洛陽有愚叟，白黑無分別。","浪跡雖似狂，謀身亦不拙。","点檢盤中飯，非精亦非糲。","点檢身上衣，無餘亦無闕。","天时方得所，不寒复不熱。","體氣正調和，不飢仍不渴。","闲將酒壺出，醉向人家歇。","野食或烹鲜，寓眠多擁褐。","抱琴榮啓乐，荷鍤劉伶達。","放眼看青山，任头生白髮。","不知天地內，更得幾年活。","從此到終身，尽爲闲日月。"]', '诗', 'shi', '', NULL, '洛陽有愚叟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2373f1dd-9979-4f1d-8189-d2ff4398446d', '飽食閑坐', '飽食闲坐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅粒陸渾稻，白鱗伊水魴。","庖童呼我食，飯熱魚鮮香。","筯筯適我口，匙匙充我腸。","八珍與五鼎，無復心思量。","捫腹起盥漱，下階振衣裳。","繞庭行數匝，却上簷下牀。","箕踞擁裘坐，半身在日暘。","可憐飽暖味，誰肯來同嘗。","是歲太和八，兵銷時漸康。","朝廷重經術，草澤搜賢良。","堯舜求理切，夔龍啓沃忙。","懷才抱智者，無不走遑遑。","唯此不才叟，頑慵戀洛陽。","飽食不出門，閑坐不下堂。","子弟多寂寞，僮僕少精光。","衣食雖充給，神意不揚揚。","爲爾謀則短，爲吾謀甚長。"]', '["紅粒陸渾稻，白鱗伊水魴。","庖童呼我食，飯熱鱼鲜香。","筯筯適我口，匙匙充我腸。","八珍與五鼎，無复心思量。","捫腹起盥漱，下階振衣裳。","繞庭行數匝，却上簷下牀。","箕踞擁裘坐，半身在日暘。","可怜飽暖味，誰肯来同嘗。","是歲太和八，兵銷时漸康。","朝廷重經術，草澤搜賢良。","堯舜求理切，夔龙啓沃忙。","懷才抱智者，無不走遑遑。","唯此不才叟，頑慵戀洛陽。","飽食不出门，闲坐不下堂。","子弟多寂寞，僮僕少精光。","衣食雖充給，神意不揚揚。","爲爾謀則短，爲吾謀甚长。"]', '诗', 'shi', '', NULL, '飽食閑坐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a002d71c-9d9f-4e83-99a4-614a8ec61d13', '閑居自題', '闲居自題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["門前有流水，牆上多高樹。","竹逕繞荷池，縈迴百餘步。","波閑戲魚鼈，風靜下鷗鷺。","寂無城市喧，渺有江湖趣。","吾廬在其上，偃臥朝復暮。","洛下安一居，山中亦慵去。","時逢過客愛，問是誰家住。","此是白家翁，閉門終老處。"]', '["门前有流水，牆上多高樹。","竹逕繞荷池，縈迴百餘步。","波闲戲鱼鼈，风静下鷗鷺。","寂無城市喧，渺有江湖趣。","吾廬在其上，偃臥朝复暮。","洛下安一居，山中亦慵去。","时逢過客愛，问是誰家住。","此是白家翁，閉门終老处。"]', '诗', 'shi', '', NULL, '閑居自題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ca6b8ca-88e5-46b3-aad7-7fdd10f2831c', '覽鏡喜老', '覽镜喜老', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝覽明鏡，鬚鬢盡成絲。","行年六十四，安得不衰羸。","親屬惜我老，相顧興歎咨。","而我獨微笑，此意何人知。","笑罷仍命酒，掩鏡捋白髭。","爾輩且安坐，從容聽我詞。","生若不足戀，老亦何足悲。","生若苟可戀，老即生多時。","不老即須夭，不夭即須衰。","晚衰勝早夭，此理決不疑。","古人亦有言，浮生七十稀。","我今欠六歲，多幸或庶幾。","儻得及此限，何羨榮啓期。","當喜不當歎，更傾酒一巵。"]', '["今朝覽明镜，鬚鬢尽成絲。","行年六十四，安得不衰羸。","親屬惜我老，相顧兴歎咨。","而我独微笑，此意何人知。","笑罷仍命酒，掩镜捋白髭。","爾輩且安坐，從容听我词。","生若不足戀，老亦何足悲。","生若苟可戀，老即生多时。","不老即須夭，不夭即須衰。","晚衰勝早夭，此理決不疑。","古人亦有言，浮生七十稀。","我今欠六歲，多幸或庶幾。","儻得及此限，何羨榮啓期。","當喜不當歎，更傾酒一巵。"]', '诗', 'shi', '', NULL, '覽鏡喜老 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d9ab9d7-9810-44fa-92cb-eb02ac9d0907', '風雪中作', '风雪中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲暮風動地，夜寒雪連天。","老夫何處宿，暖帳溫爐前。","兩重褐綺衾，一領花茸氈。","粥熟呼不起，日高安穩眠。","是時心與身，了無閑事牽。","以此度風雪，閑居來六年。","忽思遠遊客，復想早朝士。","蹋凍侵夜行，凌寒未明起。","心爲身君父，身爲心臣子。","不得身自由，皆爲心所使。","我心既知足，我身自安止。","方寸語形骸，吾應不負爾。"]', '["歲暮风动地，夜寒雪連天。","老夫何处宿，暖帳溫爐前。","兩重褐綺衾，一領花茸氈。","粥熟呼不起，日高安穩眠。","是时心與身，了無闲事牽。","以此度风雪，闲居来六年。","忽思远游客，复想早朝士。","蹋凍侵夜行，凌寒未明起。","心爲身君父，身爲心臣子。","不得身自由，皆爲心所使。","我心既知足，我身自安止。","方寸語形骸，吾應不負爾。"]', '诗', 'shi', '', NULL, '風雪中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3986ae17-9069-4dcf-84c2-9e706fbf0496', '對琴酒', '对琴酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西窗明且暖，晚坐卷書帷。","琴匣拂開後，酒瓶添滿時。","角尊白螺醆，玉軫黃金徽。","未及彈與酌，相對已依依。","泠泠秋泉韻，貯在龍鳳池。","油油春雲心，一桮可致之。","自古有琴酒，得此味者稀。","祗因康與籍，及我三心知。"]', '["西窗明且暖，晚坐卷书帷。","琴匣拂开後，酒瓶添满时。","角尊白螺醆，玉軫黄金徽。","未及彈與酌，相对已依依。","泠泠秋泉韻，貯在龙鳳池。","油油春云心，一桮可致之。","自古有琴酒，得此味者稀。","祗因康與籍，及我三心知。"]', '诗', 'shi', '', NULL, '對琴酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c7baa30a-7c49-4d49-adfd-ed71dbd76b77', '雪中晏起偶詠所懷兼呈張常侍韋庶子皇甫郎中', '雪中晏起偶詠所懷兼呈張常侍韋庶子皇甫郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窮陰蒼蒼雪雰雰，雪深沒脛泥埋輪。","東家典錢歸礙夜，南家貰米出凌晨。","我獨何者無此弊，複帳重衾暖若春。","怕寒放嬾不肯動，日高眠足方頻伸。","瓶中有酒爐有炭，甕中有飯庖有薪。","奴溫婢飽身晏起，致茲快活良有因。","上無臯陶伯益廊廟材，的不能匡君輔國活生民。","下無巢父許由箕潁操，又不能食薇飲水自苦辛。","君不見南山悠悠多白雲，又不見西京浩浩唯紅塵。","紅塵鬧熱白雲冷，好於冷熱中間安置身。","三年徼倖忝洛尹，兩任優穩爲商賓。","非賢非愚非智慧，不貴不富不賤貧。","冉冉老去過六十，騰騰閑來經七春。","不知張韋與皇甫，私喚我作何如人。"]', '["窮陰蒼蒼雪雰雰，雪深沒脛泥埋輪。","东家典錢归礙夜，南家貰米出凌晨。","我独何者無此弊，複帳重衾暖若春。","怕寒放嬾不肯动，日高眠足方頻伸。","瓶中有酒爐有炭，甕中有飯庖有薪。","奴溫婢飽身晏起，致茲快活良有因。","上無臯陶伯益廊廟材，的不能匡君輔国活生民。","下無巢父許由箕潁操，又不能食薇饮水自苦辛。","君不见南山悠悠多白云，又不见西京浩浩唯紅塵。","紅塵鬧熱白云冷，好於冷熱中间安置身。","三年徼倖忝洛尹，兩任優穩爲商賓。","非賢非愚非智慧，不貴不富不賤貧。","冉冉老去過六十，腾腾闲来經七春。","不知張韋與皇甫，私喚我作何如人。"]', '诗', 'shi', '', NULL, '雪中晏起偶詠所懷兼呈張常侍韋庶子皇甫郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1eabd342-c1c8-4d47-a9cf-8e8fb3413058', '和裴侍中南園靜興見示', '和裴侍中南园静兴见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["池館清且幽，高懷亦如此。","有時簾動風，盡日橋照水。","靜將鶴爲伴，閑與雲相似。","何必學留侯，崎嶇覓松子。"]', '["池館清且幽，高懷亦如此。","有时簾动风，尽日橋照水。","静將鹤爲伴，闲與云相似。","何必学留侯，崎嶇覓松子。"]', '诗', 'shi', '', NULL, '和裴侍中南園靜興見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0e7252-0fff-4777-aa23-67c5ec87a213', '春寒', '春寒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝春氣寒，自問何所欲。","酥煖薤白酒，乳和地黃粥。","豈惟厭饞口，亦可調病腹。","助酌有枯魚，佐餐兼旨蓄。","省躬念前哲，醉飽多慚忸。","君不聞靖節先生尊長空，廣文先生飯不足。"]', '["今朝春氣寒，自问何所欲。","酥煖薤白酒，乳和地黄粥。","豈惟厭饞口，亦可調病腹。","助酌有枯鱼，佐餐兼旨蓄。","省躬念前哲，醉飽多慚忸。","君不闻靖節先生尊长空，廣文先生飯不足。"]', '诗', 'shi', '', NULL, '春寒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1af3716-bea5-43e8-b7b0-608eea119cd1', '菩提寺上方晚望香山寺寄舒員外', '菩提寺上方晚望香山寺寄舒員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚登西寶剎，晴望東精舍。","反照轉樓臺，輝輝似圖畫。","冰浮水明滅，雪壓松偃亞。","石閣僧上來，雲汀雁飛下。","西京鬧於市，東洛閑如社。","曾憶舊遊無，香山明月夜。"]', '["晚登西寶剎，晴望东精舍。","反照轉楼台，輝輝似圖畫。","冰浮水明滅，雪壓松偃亞。","石閣僧上来，云汀雁飞下。","西京鬧於市，东洛闲如社。","曾憶旧游無，香山明月夜。"]', '诗', 'shi', '', NULL, '菩提寺上方晚望香山寺寄舒員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c51dbfcc-debd-45b5-b056-f9744e2e3628', '二月一日作贈韋七庶子', '二月一日作贈韋七庶子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["園杏紅萼坼，庭蘭紫芽出。","不覺春已深，今朝二月一。","去冬病瘡痏，將養遵醫術。","今春入道場，清淨依僧律。","嘗聞聖賢語，所慎齋與疾。","遂使愛酒人，停桮一百日。","明朝二月二，疾平齋復畢。","應須挈一壺，尋花覓韋七。"]', '["园杏紅萼坼，庭蘭紫芽出。","不覺春已深，今朝二月一。","去冬病瘡痏，將養遵醫術。","今春入道場，清淨依僧律。","嘗闻聖賢語，所慎斋與疾。","遂使愛酒人，停桮一百日。","明朝二月二，疾平斋复畢。","應須挈一壺，尋花覓韋七。"]', '诗', 'shi', '', NULL, '二月一日作贈韋七庶子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a00782-6048-4491-b93d-79c716e313fd', '犬鳶', '犬鳶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚來天氣好，散步中門前。","門前何所有，偶覩犬與鳶。","鳶飽凌風飛，犬暖向日眠。","腹舒穩貼地，翅凝高摩天。","上無羅弋憂，下無羈鎖牽。","見彼物遂性，我亦心適然。","心適復何爲，一詠逍遙篇。","此仍著於適，尚未能忘言。"]', '["晚来天氣好，散步中门前。","门前何所有，偶覩犬與鳶。","鳶飽凌风飞，犬暖向日眠。","腹舒穩貼地，翅凝高摩天。","上無羅弋憂，下無羈鎖牽。","见彼物遂性，我亦心適然。","心適复何爲，一詠逍遙篇。","此仍著於適，尚未能忘言。"]', '诗', 'shi', '', NULL, '犬鳶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3897652-efc3-407d-8c77-36e8e40b045e', '夢劉二十八因詩問之', '梦劉二十八因诗问之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜夢夢得，初覺思踟躕。","忽忘來汝郡，猶疑在吳都。","吳都三千里，汝郡二百餘。","非夢亦不見，近與遠何殊。","尚能齊近遠，焉用論榮枯。","但問寢與食，近日兩何如。","病後能吟否，春來曾醉無。","樓臺與風景，汝又何如蘇。","相思一相報，勿復慵爲書。"]', '["昨夜梦梦得，初覺思踟躕。","忽忘来汝郡，猶疑在吳都。","吳都三千里，汝郡二百餘。","非梦亦不见，近與远何殊。","尚能齊近远，焉用論榮枯。","但问寢與食，近日兩何如。","病後能吟否，春来曾醉無。","楼台與风景，汝又何如蘇。","相思一相報，勿复慵爲书。"]', '诗', 'shi', '', NULL, '夢劉二十八因詩問之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b18ae8cf-acfc-4aaf-b0dd-28e0571b1033', '閑吟', '闲吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["貧窮汲汲求衣食，富貴營營役心力。","人生不富即貧窮，光陰易過閑難得。","我今幸在窮富間，雖在朝廷不入山。","看雪尋花翫風月，洛陽城裏七年閑。"]', '["貧窮汲汲求衣食，富貴營營役心力。","人生不富即貧窮，光陰易過闲难得。","我今幸在窮富间，雖在朝廷不入山。","看雪尋花翫风月，洛陽城裏七年闲。"]', '诗', 'shi', '', NULL, '閑吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5199b24-1928-4616-9497-c57f00546218', '西行', '西行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衣裘不單薄，車馬不羸弱。","藹藹三月天，閑行亦不惡。","壽安流水館，硤石青山郭。","官道柳陰陰，行宮花漠漠。","常聞俗間語，有錢在處樂。","我雖非富人，亦不苦寂寞。","家僮解弦管，騎從攜桮杓。","時向春風前，歇鞍開一酌。"]', '["衣裘不單薄，车马不羸弱。","藹藹三月天，闲行亦不惡。","壽安流水館，硤石青山郭。","官道柳陰陰，行宮花漠漠。","常闻俗间語，有錢在处乐。","我雖非富人，亦不苦寂寞。","家僮解弦管，騎從携桮杓。","时向春风前，歇鞍开一酌。"]', '诗', 'shi', '', NULL, '西行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeb84397-00b0-484a-8ea0-a835e83c5fc6', '東歸', '东归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翩翩平肩輿，中有醉老夫。","膝上展詩卷，竿頭懸酒壺。","食宿無定程，僕馬多緩驅。","臨水歇半日，望山傾一盂。","藉草坐嵬峩，攀花行踟躕。","風將景共暖，體與心同舒。","始悟有營者，居家如在途。","方知無繫者，在道如安居。","前夕宿三堂，今旦遊申湖。","殘春三百里，送我歸東都。"]', '["翩翩平肩輿，中有醉老夫。","膝上展诗卷，竿头懸酒壺。","食宿無定程，僕马多緩驱。","臨水歇半日，望山傾一盂。","藉草坐嵬峩，攀花行踟躕。","风將景共暖，體與心同舒。","始悟有營者，居家如在途。","方知無繫者，在道如安居。","前夕宿三堂，今旦游申湖。","殘春三百里，送我归东都。"]', '诗', 'shi', '', NULL, '東歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e64c470-9d23-43fe-a11b-ddebedd77088', '途中作', '途中作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["早起上肩舁，一杯平旦醉。","晚憩下肩舁，一覺殘春睡。","身不經營物，心不思量事。","但恐綺與里，只如吾氣味。"]', '["早起上肩舁，一杯平旦醉。","晚憩下肩舁，一覺殘春睡。","身不經營物，心不思量事。","但恐綺與里，只如吾氣味。"]', '诗', 'shi', '', NULL, '途中作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2959e870-0a7b-4c95-a018-6a160ca68ed7', '小臺', '小台', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新樹低如帳，小臺平似掌。","六尺白藤牀，一莖青竹杖。","風飄竹皮落，苔印鶴迹上。","幽境與誰同，閑人自來往。"]', '["新樹低如帳，小台平似掌。","六尺白藤牀，一莖青竹杖。","风飄竹皮落，苔印鹤迹上。","幽境與誰同，闲人自来往。"]', '诗', 'shi', '', NULL, '小臺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3909f623-a817-420a-9fd9-b6e1f2722909', '睡後茶興憶楊同州', '睡後茶兴憶楊同州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨晚飲太多，嵬峩連宵醉。","今朝餐又飽，爛熳移時睡。","睡足摩挲眼，眼前無一事。","信脚繞池行，偶然得幽致。","婆娑綠陰樹，斑駮青苔地。","此處置繩牀，傍邊洗茶器。","白瓷甌甚潔，紅爐炭方熾。","沫下麴塵香，花浮魚眼沸。","盛來有佳色，嚥罷餘芳氣。","不見楊慕巢，誰人知此味。"]', '["昨晚饮太多，嵬峩連宵醉。","今朝餐又飽，爛熳移时睡。","睡足摩挲眼，眼前無一事。","信脚繞池行，偶然得幽致。","婆娑綠陰樹，斑駮青苔地。","此处置繩牀，傍邊洗茶器。","白瓷甌甚潔，紅爐炭方熾。","沫下麴塵香，花浮鱼眼沸。","盛来有佳色，嚥罷餘芳氣。","不见楊慕巢，誰人知此味。"]', '诗', 'shi', '', NULL, '睡後茶興憶楊同州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d819e29f-810f-487a-9d01-a2d9a8c521fb', '題文集櫃', '題文集櫃', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["破柏作書櫃，櫃牢柏復堅。","收貯誰家集，題云白樂天。","我生業文字，自幼及老年。","前後七十卷，小大三千篇。","誠知終散失，未忍遽棄捐。","自開自鎖閉，置在書帷前。","身是鄧伯道，世無王仲宣。","只應分付女，留與外孫傳。"]', '["破柏作书櫃，櫃牢柏复堅。","收貯誰家集，題云白乐天。","我生業文字，自幼及老年。","前後七十卷，小大三千篇。","誠知終散失，未忍遽棄捐。","自开自鎖閉，置在书帷前。","身是鄧伯道，世無王仲宣。","只應分付女，留與外孫傳。"]', '诗', 'shi', '', NULL, '題文集櫃 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cb1e6b6-8c7f-4cc7-8a1d-19decda8dcef', '旱熱二首 一', '旱熱二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["彤雲散不雨，赫日吁可畏。","端坐猶揮汗，出門豈容易。","忽思公府內，青衫折腰吏。","復想驛路中，紅塵走馬使。","征夫更辛苦，逐客彌顦顇。","日入尚趨程，宵分不遑寐。","安知北窗叟，偃臥風颯至。","簟拂碧龍鱗，扇搖白鶴翅。","豈唯身所得，兼示心無事。","誰言苦熱天，元有清涼地。"]', '["彤云散不雨，赫日吁可畏。","端坐猶揮汗，出门豈容易。","忽思公府內，青衫折腰吏。","复想驛路中，紅塵走马使。","征夫更辛苦，逐客彌顦顇。","日入尚趨程，宵分不遑寐。","安知北窗叟，偃臥风颯至。","簟拂碧龙鱗，扇搖白鹤翅。","豈唯身所得，兼示心無事。","誰言苦熱天，元有清涼地。"]', '诗', 'shi', '', NULL, '旱熱二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde723ea-67c7-4892-b270-2d3ff5dcd116', '旱熱二首 二', '旱熱二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勃勃旱塵氣，炎炎赤日光。","飛禽颭將墜，行人渴欲狂。","壯者不耐飢，飢火燒其腸。","肥者不禁熱，喘急汗如漿。","此時方自悟，老瘦亦何妨。","肉輕足健逸，髮少頭清涼。","薄食不飢渴，端居省衣裳。","數匙粱飯冷，一領綃衫香。","持此聊過日，焉知畏景長。"]', '["勃勃旱塵氣，炎炎赤日光。","飞禽颭將墜，行人渴欲狂。","壯者不耐飢，飢火燒其腸。","肥者不禁熱，喘急汗如漿。","此时方自悟，老瘦亦何妨。","肉轻足健逸，髮少头清涼。","薄食不飢渴，端居省衣裳。","數匙粱飯冷，一領綃衫香。","持此聊過日，焉知畏景长。"]', '诗', 'shi', '', NULL, '旱熱二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('701772d3-adf6-404a-9839-cb33ba353f3e', '偶作二首 一', '偶作二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戰馬春放歸，農牛冬歇息。","何獨徇名人，終身役心力。","來者殊未已，去者不知還。","我今悟已晚，六十方退閑。","猶勝不悟者，老死紅塵間。"]', '["戰马春放归，農牛冬歇息。","何独徇名人，終身役心力。","来者殊未已，去者不知還。","我今悟已晚，六十方退闲。","猶勝不悟者，老死紅塵间。"]', '诗', 'shi', '', NULL, '偶作二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9162d1d-7113-468e-8b82-46d6b54f6a5c', '偶作二首 二', '偶作二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["名無高與卑，未得多健羨。","事無小與大，已得多厭賤。","如此常自苦，反此或自安。","此理知甚易，此道行甚難。","勿信人虛語，君當事上看。"]', '["名無高與卑，未得多健羨。","事無小與大，已得多厭賤。","如此常自苦，反此或自安。","此理知甚易，此道行甚难。","勿信人虛語，君當事上看。"]', '诗', 'shi', '', NULL, '偶作二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6de2e4-c3e9-45b4-bcee-1082b3ad417b', '池上作', '池上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西溪風生竹森森，南潭萍開水沈沈。","叢翠萬竿湘岸色，空碧一泊松江心。","浦派縈迴誤遠近，橋島向背迷窺臨。","澄瀾方丈若萬頃，倒影咫尺如千尋。","泛然獨遊邈然坐，坐念行心思古今。","菟裘不聞有泉沼，西河亦恐無雲林。","豈如白翁退老地，樹高竹密池塘深。","華亭雙鶴白矯矯，太湖四石青岑岑。","眼前盡日更無客，膝上此時唯有琴。","洛陽冠蓋自相索，誰肯來此同抽簪。"]', '["西溪风生竹森森，南潭萍开水沈沈。","叢翠万竿湘岸色，空碧一泊松江心。","浦派縈迴誤远近，橋島向背迷窺臨。","澄瀾方丈若万頃，倒影咫尺如千尋。","泛然独游邈然坐，坐念行心思古今。","菟裘不闻有泉沼，西河亦恐無云林。","豈如白翁退老地，樹高竹密池塘深。","华亭雙鹤白矯矯，太湖四石青岑岑。","眼前尽日更無客，膝上此时唯有琴。","洛陽冠蓋自相索，誰肯来此同抽簪。"]', '诗', 'shi', '', NULL, '池上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa2161b9-1126-4121-96cd-81f8383a3d86', '何處堪避暑', '何处堪避暑', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何處堪避暑，林間背日樓。","何處好追涼，池上隨風舟。","日高飢始食，食竟飽還遊。","遊罷睡一覺，覺來茶一甌。","眼明見青山，耳醒聞碧流。","脫襪閑濯足，解巾快掻頭。","如此來幾時，已過六七秋。","從心至百骸，無一不自由。","拙退是其分，榮耀非所求。","雖被世間笑，終無身外憂。","此語君莫怪，靜思吾亦愁。","如何三伏月，楊尹謫虔州。"]', '["何处堪避暑，林间背日楼。","何处好追涼，池上隨风舟。","日高飢始食，食竟飽還游。","游罷睡一覺，覺来茶一甌。","眼明见青山，耳醒闻碧流。","脫襪闲濯足，解巾快掻头。","如此来幾时，已過六七秋。","從心至百骸，無一不自由。","拙退是其分，榮耀非所求。","雖被世间笑，終無身外憂。","此語君莫怪，静思吾亦愁。","如何三伏月，楊尹謫虔州。"]', '诗', 'shi', '', NULL, '何處堪避暑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6067a35-9958-4d63-ac72-fdebc4acce30', '詔下', '詔下', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日詔下去罪人，今日詔下得賢臣。","進退者誰非我事，世間寵辱常紛紛。","我心與世兩相忘，時事雖聞如不聞。","但喜今年飽飯吃，洛陽禾稼如秋雲。","更傾一尊歌一曲，不獨忘世兼忘身。"]', '["昨日詔下去罪人，今日詔下得賢臣。","進退者誰非我事，世间寵辱常紛紛。","我心與世兩相忘，时事雖闻如不闻。","但喜今年飽飯吃，洛陽禾稼如秋云。","更傾一尊歌一曲，不独忘世兼忘身。"]', '诗', 'shi', '', NULL, '詔下 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a0141b-7d2d-487e-ac3c-1c74abd64ef2', '七月一日作', '七月一日作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七月一日天，秋生履道里。","閑居見清景，高興從此始。","林間暑雨歇，池上涼風起。","橋竹碧鮮鮮，岸莎青靡靡。","蒼然古磐石，清淺平流水。","何言中門前，便是深山裏。","雙僮侍坐臥，一杖扶行止。","飢聞麻粥香，渴覺雲湯美。","平生所好物，今日多在此。","此外更何思，市朝心已矣。"]', '["七月一日天，秋生履道里。","闲居见清景，高兴從此始。","林间暑雨歇，池上涼风起。","橋竹碧鲜鲜，岸莎青靡靡。","蒼然古磐石，清淺平流水。","何言中门前，便是深山裏。","雙僮侍坐臥，一杖扶行止。","飢闻麻粥香，渴覺云湯美。","平生所好物，今日多在此。","此外更何思，市朝心已矣。"]', '诗', 'shi', '', NULL, '七月一日作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dbada1f3-2a57-42f1-a90f-5d037090dbf2', '開襟', '开襟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["開襟何處好，竹下池邊地。","餘熱體猶煩，早涼風有味。","黃萎槐蘂結，紅破蓮芳墜。","無奈每年秋，先來入衰思。"]', '["开襟何处好，竹下池邊地。","餘熱體猶煩，早涼风有味。","黄萎槐蘂結，紅破蓮芳墜。","無奈每年秋，先来入衰思。"]', '诗', 'shi', '', NULL, '開襟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8dd7482-a024-4985-9ee4-aad421636c4f', '自賓客遷太子少傅分司', '自賓客遷太子少傅分司', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭上漸無髮，耳間新有毫。","形容逐日老，官秩隨年高。","優饒又加俸，閑穩仍分曹。","飲食免藜藿，居處非蓬蒿。","何言家尚貧，銀榼提綠醪。","勿謂身未貴，金章照紫袍。","誠合知止足，豈宜更貪饕。","默默心自問，於國有何勞。"]', '["头上漸無髮，耳间新有毫。","形容逐日老，官秩隨年高。","優饒又加俸，闲穩仍分曹。","饮食免藜藿，居处非蓬蒿。","何言家尚貧，銀榼提綠醪。","勿謂身未貴，金章照紫袍。","誠合知止足，豈宜更貪饕。","默默心自问，於国有何勞。"]', '诗', 'shi', '', NULL, '自賓客遷太子少傅分司 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dc4706c-8abe-4c76-a9a8-47e15c1615d5', '自在', '自在', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杲杲冬日光，明暖真可愛。","移榻向陽坐，擁裘仍解帶。","小奴搥我足，小婢搔我背。","自問我爲誰，胡然獨安泰。","安泰良有以，與君論梗概。","心了事未了，飢寒迫於外。","事了心未了，念慮煎於內。","我今實多幸，事與心和會。","內外及中間，了然無一礙。","所以日陽中，向君言自在。"]', '["杲杲冬日光，明暖真可愛。","移榻向陽坐，擁裘仍解带。","小奴搥我足，小婢搔我背。","自问我爲誰，胡然独安泰。","安泰良有以，與君論梗概。","心了事未了，飢寒迫於外。","事了心未了，念慮煎於內。","我今實多幸，事與心和會。","內外及中间，了然無一礙。","所以日陽中，向君言自在。"]', '诗', 'shi', '', NULL, '自在 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9714c59-3855-4fdd-872f-e40c815dda84', '詠史', '詠史', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["秦磨利刀斬李斯，齊燒沸鼎烹酈其。","可憐黃綺入商洛，閑臥白雲歌紫芝。","彼爲葅醢机上盡，此爲鸞皇天外飛。","去者逍遙來者死，乃知禍福非天爲。"]', '["秦磨利刀斬李斯，齊燒沸鼎烹酈其。","可怜黄綺入商洛，闲臥白云歌紫芝。","彼爲葅醢机上尽，此爲鸾皇天外飞。","去者逍遙来者死，乃知禍福非天爲。"]', '诗', 'shi', '', NULL, '詠史 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a24d2277-3595-493f-b361-b6f81cfeac01', '因夢有悟', '因梦有悟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["交友淪歿盡，悠悠勞夢思。","平生所厚者，昨夜夢見之。","夢中幾許事，枕上無多時。","欵曲數杯酒，從容一局碁。","初見韋尚書，金紫何輝輝。","中遇李侍郎，笑言甚怡怡。","終爲崔常侍，意色苦依依。","一夕三改變，夢心不驚疑。","此事人盡怪，此理誰得知。","我粗知此理，聞於竺乾師。","識行妄分別，智隱迷是非。","若轉識爲智，菩提其庶幾。"]', '["交友淪歿尽，悠悠勞梦思。","平生所厚者，昨夜梦见之。","梦中幾許事，枕上無多时。","欵曲數杯酒，從容一局碁。","初见韋尚书，金紫何輝輝。","中遇李侍郎，笑言甚怡怡。","終爲崔常侍，意色苦依依。","一夕三改变，梦心不驚疑。","此事人尽怪，此理誰得知。","我粗知此理，闻於竺乾師。","識行妄分別，智隐迷是非。","若轉識爲智，菩提其庶幾。"]', '诗', 'shi', '', NULL, '因夢有悟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d34c6cfd-3872-40dc-a4a5-3877cb093c6c', '春遊', '春游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上馬臨出門，出門復逡巡。","迴頭問妻子，應怪春遊頻。","誠知春遊頻，其奈老大身。","朱顏去復去，白髮新更新。","請君屈十指，爲我數交親。","大限年百歲，幾人及七旬。","我今六十五，走若下坂輪。","假使得七十，祗有五度春。","逢春不遊樂，但恐是癡人。"]', '["上马臨出门，出门复逡巡。","迴头问妻子，應怪春游頻。","誠知春游頻，其奈老大身。","朱顏去复去，白髮新更新。","請君屈十指，爲我數交親。","大限年百歲，幾人及七旬。","我今六十五，走若下坂輪。","假使得七十，祗有五度春。","逢春不游乐，但恐是癡人。"]', '诗', 'shi', '', NULL, '春遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b2f683d-a08b-4c27-bb48-7156ba1b8ad4', '題天竺南院贈閑元旻清四上人', '題天竺南院贈闲元旻清四上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雜芳澗草合，繁綠巖樹新。","山深景候晚，四月有餘春。","竹寺過微雨，石逕無纖塵。","白衣一居士，方袍四道人。","地是佛國土，人非俗交親。","城中山下別，相送亦殷勤。"]', '["杂芳澗草合，繁綠巖樹新。","山深景候晚，四月有餘春。","竹寺過微雨，石逕無纖塵。","白衣一居士，方袍四道人。","地是佛国土，人非俗交親。","城中山下別，相送亦殷勤。"]', '诗', 'shi', '', NULL, '題天竺南院贈閑元旻清四上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e586e12-312b-46e3-ac87-b7ce9d923781', '哭師臯', '哭師臯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南康丹旐引魂迴，洛陽籃舁送葬來。","北邙原邊尹村畔，月苦煙愁夜過半。","妻孥兄弟號一聲，十二人腸一時斷。","往者何人送者誰，樂天哭別師臯時。","平生分義向人盡，今日哀冤唯我知。","我知何益徒垂淚，籃轝迴竿馬迴轡。","何日重聞掃市歌，誰家收得琵琶伎。","蕭蕭風樹白楊影，蒼蒼露草青蒿氣。","更就墳前哭一聲，與君此別終天地。"]', '["南康丹旐引魂迴，洛陽籃舁送葬来。","北邙原邊尹村畔，月苦煙愁夜過半。","妻孥兄弟號一声，十二人腸一时斷。","往者何人送者誰，乐天哭別師臯时。","平生分義向人尽，今日哀冤唯我知。","我知何益徒垂泪，籃轝迴竿马迴轡。","何日重闻掃市歌，誰家收得琵琶伎。","蕭蕭风樹白楊影，蒼蒼露草青蒿氣。","更就墳前哭一声，與君此別終天地。"]', '诗', 'shi', '', NULL, '哭師臯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('473ee174-d582-419b-9077-0535957c95f6', '隱几贈客', '隐几贈客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宦情本淡薄，年貌又老醜。","紫綬與金章，於予亦何有。","有時獨隱几，荅然無所偶。","臥枕一卷書，起嘗一杯酒。","書將引昏睡，酒用扶衰朽。","客到忽已酣，脫巾坐搔首。","疎頑倚老病，容恕慚交友。","忽思莊生言，亦擬鞭其後。"]', '["宦情本淡薄，年貌又老醜。","紫綬與金章，於予亦何有。","有时独隐几，荅然無所偶。","臥枕一卷书，起嘗一杯酒。","书將引昏睡，酒用扶衰朽。","客到忽已酣，脫巾坐搔首。","疎頑倚老病，容恕慚交友。","忽思莊生言，亦擬鞭其後。"]', '诗', 'shi', '', NULL, '隱几贈客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14cebb2d-b656-41f4-bf23-40141eccd615', '夏日作', '夏日作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葛衣疎且單，紗帽輕復寬。","一衣與一帽，可以過炎天。","止於便吾體，何必被羅紈。","宿雨林笋嫩，晨露園葵鮮。","烹葵炮嫩笋，可以備朝餐。","止於適吾口，何必飫腥羶。","飯訖盥漱已，捫腹方果然。","婆娑庭前步，安穩窗下眠。","外養物不費，內歸心不煩。","不費用難盡，不煩神易安。","庶幾無夭閼，得以終天年。"]', '["葛衣疎且單，紗帽轻复寬。","一衣與一帽，可以過炎天。","止於便吾體，何必被羅紈。","宿雨林笋嫩，晨露园葵鲜。","烹葵炮嫩笋，可以備朝餐。","止於適吾口，何必飫腥羶。","飯訖盥漱已，捫腹方果然。","婆娑庭前步，安穩窗下眠。","外養物不費，內归心不煩。","不費用难尽，不煩神易安。","庶幾無夭閼，得以終天年。"]', '诗', 'shi', '', NULL, '夏日作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c44c5684-0db7-4355-88f2-515ac562cfe6', '晚涼偶詠', '晚涼偶詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日下西牆西，風來北窗北。","中有逐涼人，單牀獨棲息。","飄蕭過雲雨，搖曳歸飛翼。","新葉多好陰，初筠有佳色。","幽深小池館，優穩閑官職。","不愛勿復論，愛亦不易得。"]', '["日下西牆西，风来北窗北。","中有逐涼人，單牀独棲息。","飄蕭過云雨，搖曳归飞翼。","新葉多好陰，初筠有佳色。","幽深小池館，優穩闲官職。","不愛勿复論，愛亦不易得。"]', '诗', 'shi', '', NULL, '晚涼偶詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('024f6894-58ab-4730-a57a-96a3c9afdbfa', '酬牛相公宮城早秋寓言見示兼呈夢得', '酬牛相公宮城早秋寓言见示兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七月中氣後，金與火交爭。","一聞白雪唱，暑退清風生。","碧樹未搖落，寒蟬始悲鳴。","夜涼枕簟滑，秋燥衣巾輕。","疎受老慵出，劉楨疾未平。","何人伴公醉，新月上宮城。"]', '["七月中氣後，金與火交爭。","一闻白雪唱，暑退清风生。","碧樹未搖落，寒蟬始悲鳴。","夜涼枕簟滑，秋燥衣巾轻。","疎受老慵出，劉楨疾未平。","何人伴公醉，新月上宮城。"]', '诗', 'shi', '', NULL, '酬牛相公宮城早秋寓言見示兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4526ab6a-c723-43bc-b682-4fcd0e60f1fc', '小臺晚坐憶夢得', '小台晚坐憶梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["汲泉灑小臺，臺上無纖埃。","解帶面西坐，輕襟隨風開。","晚涼閑興動，憶同傾一杯。","月明候柴戶，藜杖何時來。"]', '["汲泉灑小台，台上無纖埃。","解带面西坐，轻襟隨风开。","晚涼闲兴动，憶同傾一杯。","月明候柴戶，藜杖何时来。"]', '诗', 'shi', '', NULL, '小臺晚坐憶夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23947308-550d-40eb-ac10-2226a4957601', '種桃歌', '種桃歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["食桃種其核，一年核生芽。","二年長枝葉，三年桃有花。","憶昨五六歲，灼灼盛芬華。","迨茲八九載，有減而無加。","去春已稀少，今春漸無多。","明年後年後，芳意當如何。","命酒樹下飲，停杯拾餘葩。","因桃忽自感，悲吒成狂歌。"]', '["食桃種其核，一年核生芽。","二年长枝葉，三年桃有花。","憶昨五六歲，灼灼盛芬华。","迨茲八九載，有減而無加。","去春已稀少，今春漸無多。","明年後年後，芳意當如何。","命酒樹下饮，停杯拾餘葩。","因桃忽自感，悲吒成狂歌。"]', '诗', 'shi', '', NULL, '種桃歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45bfc931-b2fa-402e-b3ba-7293f8306c24', '狂言示諸姪', '狂言示諸姪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世欺不識字，我忝攻文筆。","世欺不得官，我忝居班秩。","人老多病苦，我今幸無疾。","人老多憂累，我今婚嫁畢。","心安不移轉，身泰無牽率。","所以十年來，形神閑且逸。","況當垂老歲，所要無多物。","一裘煖過冬，一飯飽終日。","勿言舍宅小，不過寢一室。","何用鞍馬多，不能騎兩匹。","如我優幸身，人中十有七。","如我知足心，人中百無一。","傍觀愚亦見，當己賢多失。","不敢論他人，狂言示諸姪。"]', '["世欺不識字，我忝攻文笔。","世欺不得官，我忝居班秩。","人老多病苦，我今幸無疾。","人老多憂累，我今婚嫁畢。","心安不移轉，身泰無牽率。","所以十年来，形神闲且逸。","況當垂老歲，所要無多物。","一裘煖過冬，一飯飽終日。","勿言舍宅小，不過寢一室。","何用鞍马多，不能騎兩匹。","如我優幸身，人中十有七。","如我知足心，人中百無一。","傍观愚亦见，當己賢多失。","不敢論他人，狂言示諸姪。"]', '诗', 'shi', '', NULL, '狂言示諸姪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd1e68b-d552-4a67-a74a-32c6a666f1d5', '偶以拙詩數首寄呈裴少尹侍郎蒙以盛製四篇一時酬和重投長句美而謝之', '偶以拙诗數首寄呈裴少尹侍郎蒙以盛製四篇一时酬和重投长句美而謝之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["投君之文甚荒蕪，數篇價直一束芻。","報我之章何璀璨，纍纍四貫驪龍珠。","毛詩三百篇後得，文選六十卷中無。","一麋麗龜絕報賽，五鹿連柱難支梧。","高興獨因秋日盡，清吟多與好風俱。","銀鉤金錯兩殊重，宜上屏風張座隅。"]', '["投君之文甚荒蕪，數篇價直一束芻。","報我之章何璀璨，纍纍四貫驪龙珠。","毛诗三百篇後得，文選六十卷中無。","一麋丽龟絕報賽，五鹿連柱难支梧。","高兴独因秋日尽，清吟多與好风俱。","銀鉤金錯兩殊重，宜上屏风張座隅。"]', '诗', 'shi', '', NULL, '偶以拙詩數首寄呈裴少尹侍郎蒙以盛製四篇一時酬和重投長句美而謝之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce5bcc14-ed93-41d7-b2e7-a3ebc2165066', '六年冬暮贈崔常侍晦叔', '六年冬暮贈崔常侍晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬢毛霜一色，光景水爭流。","易過唯冬日，難銷是老愁。","香開綠蟻酒，煖擁褐綾裘。","已共崔君約，尊前倒即休。"]', '["鬢毛霜一色，光景水爭流。","易過唯冬日，难銷是老愁。","香开綠蟻酒，煖擁褐綾裘。","已共崔君約，尊前倒即休。"]', '诗', 'shi', '', NULL, '六年冬暮贈崔常侍晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41e3f463-1460-4aed-a203-56402ea427ef', '戲招諸客', '戲招諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["黃醅綠醑迎冬熟，絳帳紅爐逐夜開。","誰道洛中多逸客，不將書喚不曾來。"]', '["黄醅綠醑迎冬熟，絳帳紅爐逐夜开。","誰道洛中多逸客，不將书喚不曾来。"]', '诗', 'shi', '', NULL, '戲招諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('74c20329-8f1f-42e4-bfd1-f9834185e483', '十二月二十三日作兼呈晦叔', '十二月二十三日作兼呈晦叔', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["案頭曆日雖未盡，向後唯殘六七行。","牀下酒瓶雖不滿，猶應醉得兩三場。","病身不許依年老，拙宦虛教逐日忙。","聞健偷閑且勤飲，一杯之外莫思量。"]', '["案头曆日雖未尽，向後唯殘六七行。","牀下酒瓶雖不满，猶應醉得兩三場。","病身不許依年老，拙宦虛教逐日忙。","闻健偷闲且勤饮，一杯之外莫思量。"]', '诗', 'shi', '', NULL, '十二月二十三日作兼呈晦叔 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b645c497-62ad-4f04-ae20-741e0e32b1bf', '七年元日對酒五首 一', '七年元日对酒五首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慶弔經過嬾，逢迎跪拜遲。","不因時節日，豈覺此身羸。"]', '["慶弔經過嬾，逢迎跪拜遲。","不因时節日，豈覺此身羸。"]', '诗', 'shi', '', NULL, '七年元日對酒五首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c81bdf06-cc57-4e5e-9b1c-b952a27e332e', '七年元日對酒五首 二', '七年元日对酒五首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衆老憂添歲，余衰喜入春。","年開第七秩，屈指幾多人。"]', '["衆老憂添歲，余衰喜入春。","年开第七秩，屈指幾多人。"]', '诗', 'shi', '', NULL, '七年元日對酒五首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('78d6f1d3-6895-43a9-9977-4b61cb053bf0', '七年元日對酒五首 三', '七年元日对酒五首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三杯藍尾酒，一楪膠牙餳。","除却崔常侍，無人共我爭。"]', '["三杯藍尾酒，一楪膠牙餳。","除却崔常侍，無人共我爭。"]', '诗', 'shi', '', NULL, '七年元日對酒五首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd30747f-9559-4026-b633-f951c5db5079', '七年元日對酒五首 四', '七年元日对酒五首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今朝吳與洛，相憶一欣然。","夢得君知否，俱過本命年。"]', '["今朝吳與洛，相憶一欣然。","梦得君知否，俱過本命年。"]', '诗', 'shi', '', NULL, '七年元日對酒五首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94f6d933-1d67-4b12-a227-6065ba306274', '七年元日對酒五首 五', '七年元日对酒五首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["同歲崔何在，同年杜又無。","應無藏避處，只有且歡娛。"]', '["同歲崔何在，同年杜又無。","應無藏避处，只有且歡娛。"]', '诗', 'shi', '', NULL, '七年元日對酒五首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('151724fa-8ac4-4de5-957f-2fecca7a286f', '七年春題府廳', '七年春題府廳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["潦倒守三川，因循涉四年。","推誠廢鉤距，示耻用蒲鞭。","以此稱公事，將何銷俸錢。","雖非好官職，歲久亦妨賢。"]', '["潦倒守三川，因循涉四年。","推誠廢鉤距，示耻用蒲鞭。","以此稱公事，將何銷俸錢。","雖非好官職，歲久亦妨賢。"]', '诗', 'shi', '', NULL, '七年春題府廳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184cc912-91cc-4b60-a1b6-c01a9906d46f', '早春醉吟寄太原令狐相公蘇州劉郎中', '早春醉吟寄太原令狐相公蘇州劉郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪夜閑遊多秉燭，花時蹔出亦提壺。","別來少遇新詩敵，老去難逢舊飲徒。","大振威名降北虜，勤行惠化活東吳。","不知歌酒騰騰興，得似河南醉尹無。"]', '["雪夜闲游多秉燭，花时蹔出亦提壺。","別来少遇新诗敵，老去难逢旧饮徒。","大振威名降北虜，勤行惠化活东吳。","不知歌酒腾腾兴，得似河南醉尹無。"]', '诗', 'shi', '', NULL, '早春醉吟寄太原令狐相公蘇州劉郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3cc093e1-e345-4ffe-9721-f49b48891cfa', '洛下送牛相公出鎮淮南', '洛下送牛相公出鎮淮南', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["北闕至東京，風光十六程。","坐移丞相閣，春入廣陵城。","紅斾擁雙節，白鬚無一莖。","萬人開路看，百吏立班迎。","閫外君彌重，尊前我亦榮。","何須身自得，將相是門生。"]', '["北闕至东京，风光十六程。","坐移丞相閣，春入廣陵城。","紅斾擁雙節，白鬚無一莖。","万人开路看，百吏立班迎。","閫外君彌重，尊前我亦榮。","何須身自得，將相是门生。"]', '诗', 'shi', '', NULL, '洛下送牛相公出鎮淮南 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('380609ae-9cfc-49bb-857e-de43b33175aa', '箏', '箏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雲髻飄蕭綠，花顏旖旎紅。","雙眸剪秋水，十指剝春蔥。","楚豔爲門閥，秦聲是女工。","甲明銀玓瓅，柱觸玉玲瓏。","猨苦啼嫌月，鶯嬌語䛏風。","移愁來手底，送恨入弦中。","趙瑟清相似，胡琴鬧不同。","慢彈迴斷雁，急奏轉飛蓬。","霜珮鏘還委，冰泉咽復通。","珠聯千拍碎，刀截一聲終。","倚麗精神定，矜能意態融。","歇時情不斷，休去思無窮。","燈下青春夜，尊前白首翁。","且聽應得在，老耳未多聾。"]', '["云髻飄蕭綠，花顏旖旎紅。","雙眸剪秋水，十指剝春蔥。","楚豔爲门閥，秦声是女工。","甲明銀玓瓅，柱觸玉玲瓏。","猨苦啼嫌月，鶯嬌語䛏风。","移愁来手底，送恨入弦中。","趙瑟清相似，胡琴鬧不同。","慢彈迴斷雁，急奏轉飞蓬。","霜珮鏘還委，冰泉咽复通。","珠聯千拍碎，刀截一声終。","倚丽精神定，矜能意態融。","歇时情不斷，休去思無窮。","灯下青春夜，尊前白首翁。","且听應得在，老耳未多聾。"]', '诗', 'shi', '', NULL, '箏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4e0c217e-fb38-42a2-9b11-ab78b2dec630', '洛中春遊呈諸親友', '洛中春游呈諸親友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫歎年將暮，須憐歲又新。","府中三遇臘，洛下五逢春。","春樹花珠顆，春塘水麴塵。","春娃無氣力，春馬有精神。","並轡鞭徐動，連盤酒慢巡。","經過舊鄰里，追逐好交親。","笑語銷閑日，酣歌送老身。","一生歡樂事，亦不少於人。"]', '["莫歎年將暮，須怜歲又新。","府中三遇臘，洛下五逢春。","春樹花珠顆，春塘水麴塵。","春娃無氣力，春马有精神。","並轡鞭徐动，連盤酒慢巡。","經過旧鄰里，追逐好交親。","笑語銷闲日，酣歌送老身。","一生歡乐事，亦不少於人。"]', '诗', 'shi', '', NULL, '洛中春遊呈諸親友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b44b76b7-a788-403b-9bf8-9c55491b469d', '酬舒三員外見贈長句', '酬舒三員外见贈长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自請假來多少日，五旬光景似須臾。","已判到老爲狂客，不分當春作病夫。","楊柳花飄新白雪，櫻桃子綴小紅珠。","頭風不敢多多飲，能酌三分相勸無。"]', '["自請假来多少日，五旬光景似須臾。","已判到老爲狂客，不分當春作病夫。","楊柳花飄新白雪，櫻桃子綴小紅珠。","头风不敢多多饮，能酌三分相勸無。"]', '诗', 'shi', '', NULL, '酬舒三員外見贈長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb72f1ba-72fc-40c3-8cca-173c96198e07', '將歸一絕', '將归一絕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["欲去公門返野扉，預思泉竹已依依。","更憐家醞迎春熟，一甕醍醐待我歸。"]', '["欲去公门返野扉，預思泉竹已依依。","更怜家醞迎春熟，一甕醍醐待我归。"]', '诗', 'shi', '', NULL, '將歸一絕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f0e6ff3-3c6f-4530-ba60-3259058b43c8', '罷府歸舊居', '罷府归旧居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陋巷乘籃入，朱門挂印迴。","腰間拋組綬，纓上拂塵埃。","屈曲閑池沼，無非手自開。","青蒼好竹樹，亦是眼看栽。","石片擡琴匣，松枝閣酒杯。","此生終老處，昨日却歸來。"]', '["陋巷乘籃入，朱门挂印迴。","腰间拋組綬，纓上拂塵埃。","屈曲闲池沼，無非手自开。","青蒼好竹樹，亦是眼看栽。","石片擡琴匣，松枝閣酒杯。","此生終老处，昨日却归来。"]', '诗', 'shi', '', NULL, '罷府歸舊居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('921be510-61d6-4d24-bb98-65ed89112664', '睡覺偶吟', '睡覺偶吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官初罷後歸來夜，天欲明前睡覺時。","起坐思量更無事，身心安樂復誰知。"]', '["官初罷後归来夜，天欲明前睡覺时。","起坐思量更無事，身心安乐复誰知。"]', '诗', 'shi', '', NULL, '睡覺偶吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b3c7aea-d799-4134-87eb-3ab9a1a7ea6d', '問支琴石', '问支琴石', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["疑因星隕空中落，歎被泥埋澗底沈。","天上定應勝地上，支機未必及支琴。","提攜拂拭知恩否，雖不能言合有心。"]', '["疑因星隕空中落，歎被泥埋澗底沈。","天上定應勝地上，支機未必及支琴。","提携拂拭知恩否，雖不能言合有心。"]', '诗', 'shi', '', NULL, '問支琴石 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ace314e9-a760-4216-9e02-888e0c81ba91', '自喜', '自喜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身慵難勉強，性拙易遲迴。","布被辰時起，柴門午後開。","忙驅能者去，閑逐鈍人來。","自喜誰能會，無才勝有才。"]', '["身慵难勉強，性拙易遲迴。","布被辰时起，柴门午後开。","忙驱能者去，闲逐鈍人来。","自喜誰能會，無才勝有才。"]', '诗', 'shi', '', NULL, '自喜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('425946cb-3dc6-43d5-a5d1-bff11eaacaa0', '裴常侍以題薔薇架十八韻見示因廣爲三十韻以和之', '裴常侍以題薔薇架十八韻见示因廣爲三十韻以和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["託質依高架，攢花對小堂。","晚開春去後，獨秀院中央。","霽景朱明早，芳時白晝長。","穠因天與色，麗共日爭光。","剪碧排千萼，研朱染萬房。","煙條塗石綠，粉蘂撲雌黃。","根動彤雲涌，枝搖赤羽翔。","九微燈炫轉，七寶帳熒煌。","淑氣熏行徑，清陰接步廊。","照梁迷藻梲，耀壁變雕牆。","爛若藂然火，殷於葉得霜。","臙脂含臉笑，蘇合裛衣香。","浹洽濡晨露，玲瓏漏夕陽。","合羅排勘纈，醉暈淺深妝。","乍見疑迴面，遙看誤斷腸。","風朝舞飛燕，雨夜泣蕭娘。","桃李慙無語，芝蘭讓不芳。","山榴何細碎，石竹苦尋常。","蕙慘偎欄避，蓮羞映浦藏。","怯教蕉葉戰，妬得柳花狂。","豈可輕嘲詠，應須痛比方。","畫幈風自展，繡繖蓋誰張。","翠錦挑成字，丹砂印著行。","猩猩凝血點，瑟瑟蹙金匡。","散亂萎紅片，尖纖嫩紫芒。","觸僧飄毳褐，留妓冒羅裳。","寡和陽春曲，多情騎省郎。","緣誇美顏色，引出好文章。","東顧辭仁里，西歸入帝鄉。","假如君愛殺，留著莫移將。"]', '["託質依高架，攢花对小堂。","晚开春去後，独秀院中央。","霽景朱明早，芳时白晝长。","穠因天與色，丽共日爭光。","剪碧排千萼，研朱染万房。","煙條塗石綠，粉蘂撲雌黄。","根动彤云涌，枝搖赤羽翔。","九微灯炫轉，七寶帳熒煌。","淑氣熏行徑，清陰接步廊。","照梁迷藻梲，耀壁变雕牆。","爛若藂然火，殷於葉得霜。","臙脂含臉笑，蘇合裛衣香。","浹洽濡晨露，玲瓏漏夕陽。","合羅排勘纈，醉暈淺深妝。","乍见疑迴面，遙看誤斷腸。","风朝舞飞燕，雨夜泣蕭娘。","桃李慙無語，芝蘭讓不芳。","山榴何細碎，石竹苦尋常。","蕙慘偎欄避，蓮羞映浦藏。","怯教蕉葉戰，妬得柳花狂。","豈可轻嘲詠，應須痛比方。","畫幈风自展，繡繖蓋誰張。","翠錦挑成字，丹砂印著行。","猩猩凝血点，瑟瑟蹙金匡。","散亂萎紅片，尖纖嫩紫芒。","觸僧飄毳褐，留妓冒羅裳。","寡和陽春曲，多情騎省郎。","緣誇美顏色，引出好文章。","东顧辞仁里，西归入帝乡。","假如君愛殺，留著莫移將。"]', '诗', 'shi', '', NULL, '裴常侍以題薔薇架十八韻見示因廣爲三十韻以和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcb71c9-88c4-4244-aa24-2b40eb4f9f7b', '感舊詩卷', '感旧诗卷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜深吟罷一長吁，老淚燈前濕白鬚。","二十年前舊詩卷，十人酬和九人無。"]', '["夜深吟罷一长吁，老泪灯前濕白鬚。","二十年前旧诗卷，十人酬和九人無。"]', '诗', 'shi', '', NULL, '感舊詩卷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0919f4d-7a6b-4328-bf2c-2471fc31d253', '酬李二十侍郎', '酬李二十侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["笋老蘭長花漸稀，衰翁相對惜芳菲。","殘鶯著雨慵休囀，落絮無風凝不飛。","行掇木芽供野食，坐牽蘿蔓挂朝衣。","十年分手今同醉，醉未如泥莫道歸。"]', '["笋老蘭长花漸稀，衰翁相对惜芳菲。","殘鶯著雨慵休囀，落絮無风凝不飞。","行掇木芽供野食，坐牽蘿蔓挂朝衣。","十年分手今同醉，醉未如泥莫道归。"]', '诗', 'shi', '', NULL, '酬李二十侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d9f48bb-cc2f-44d5-8478-c3d788277ff5', '和夢得', '和梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綸閣沈沈無寵命，蘇臺籍籍有能聲。","豈唯不得清文力，但恐空傳冗吏名。","郎署迴翔何水部，江湖留滯謝宣城。","所嗟非獨君如此，自古才難共命爭。"]', '["綸閣沈沈無寵命，蘇台籍籍有能声。","豈唯不得清文力，但恐空傳冗吏名。","郎署迴翔何水部，江湖留滯謝宣城。","所嗟非独君如此，自古才难共命爭。"]', '诗', 'shi', '', NULL, '和夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e44ca5fe-3ecb-44db-8fed-134d38042348', '贈草堂宗密上人', '贈草堂宗密上人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾師道與佛相應，念念無爲法法能。","口藏宣傳十二部，心臺照耀百千燈。","盡離文字非中道，長住虛空是小乘。","少有人知菩薩行，世間只是重高僧。"]', '["吾師道與佛相應，念念無爲法法能。","口藏宣傳十二部，心台照耀百千灯。","尽離文字非中道，长住虛空是小乘。","少有人知菩薩行，世间只是重高僧。"]', '诗', 'shi', '', NULL, '贈草堂宗密上人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f965c4af-8fb5-4179-821b-4aa9f475000e', '喜照密閑實四上人見過', '喜照密闲實四上人见過', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫袍朝士白髯翁，與俗乖疎與道通。","官秩三迴分洛下，交遊一半在僧中。","臭[帤]世界終須出，香火因緣久願同。","齋後將何充供養，西軒泉石北窗風。"]', '["紫袍朝士白髯翁，與俗乖疎與道通。","官秩三迴分洛下，交游一半在僧中。","臭[帤]世界終須出，香火因緣久願同。","斋後將何充供養，西軒泉石北窗风。"]', '诗', 'shi', '', NULL, '喜照密閑實四上人見過 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aa3b5db0-1dec-4c14-8f7e-ac7f64c11afa', '贈皇甫六張十五李二十三賓客', '贈皇甫六張十五李二十三賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨日三川新罷守，今年四皓盡分司。","幸陪散秩閑居日，好是登山臨水時。","家未苦貧常醞酒，身雖衰病尚吟詩。","龍門泉石香山月，早晚同遊報一期。"]', '["昨日三川新罷守，今年四皓尽分司。","幸陪散秩闲居日，好是登山臨水时。","家未苦貧常醞酒，身雖衰病尚吟诗。","龙门泉石香山月，早晚同游報一期。"]', '诗', 'shi', '', NULL, '贈皇甫六張十五李二十三賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('565dde47-fa94-42ae-bcdc-762c38cc13d7', '微之敦詩晦叔相次長逝巋然自傷因成二絕 一', '微之敦诗晦叔相次长逝巋然自傷因成二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["併失鵷鸞侶，空留麋鹿身。","只應嵩洛下，長作獨遊人。"]', '["併失鵷鸾侶，空留麋鹿身。","只應嵩洛下，长作独游人。"]', '诗', 'shi', '', NULL, '微之敦詩晦叔相次長逝巋然自傷因成二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('196cd7ae-bd14-4f25-a614-46b6c536a079', '微之敦詩晦叔相次長逝巋然自傷因成二絕 二', '微之敦诗晦叔相次长逝巋然自傷因成二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["長夜君先去，殘年我幾何。","秋風滿衫淚，泉下故人多。"]', '["长夜君先去，殘年我幾何。","秋风满衫泪，泉下故人多。"]', '诗', 'shi', '', NULL, '微之敦詩晦叔相次長逝巋然自傷因成二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('002c015a-2991-4ebf-bc33-e0749ab556dc', '池上閑詠', '池上闲詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青莎臺上起書樓，綠藻潭中繫釣舟。","日晚愛行深竹裏，月明多上小橋頭。","蹔嘗新酒還成醉，亦出中門便當遊。","一部清商聊送老，白鬚蕭颯管弦秋。"]', '["青莎台上起书楼，綠藻潭中繫釣舟。","日晚愛行深竹裏，月明多上小橋头。","蹔嘗新酒還成醉，亦出中门便當游。","一部清商聊送老，白鬚蕭颯管弦秋。"]', '诗', 'shi', '', NULL, '池上閑詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b927a9a0-9479-4497-849e-966342f62e5c', '涼風歎', '涼风歎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昨夜涼風又颯然，螢飄葉墜臥牀前。","逢秋莫歎須知分，已過潘安三十年。"]', '["昨夜涼风又颯然，螢飄葉墜臥牀前。","逢秋莫歎須知分，已過潘安三十年。"]', '诗', 'shi', '', NULL, '涼風歎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7896c24e-7c04-4e75-9bec-4867baf47de4', '和高僕射罷節度讓尚書授少保分司喜遂遊山水之作', '和高僕射罷節度讓尚书授少保分司喜遂游山水之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蹔辭八座罷雙旌，便作登山臨水行。","能以忠貞酬重任，不將富貴礙高情。","朱門出去簪纓從，絳帳歸來歌吹迎。","鞍轡鬧裝光滿馬，何人信道是書生。"]', '["蹔辞八座罷雙旌，便作登山臨水行。","能以忠貞酬重任，不將富貴礙高情。","朱门出去簪纓從，絳帳归来歌吹迎。","鞍轡鬧裝光满马，何人信道是书生。"]', '诗', 'shi', '', NULL, '和高僕射罷節度讓尚書授少保分司喜遂遊山水之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9de06d8f-3fad-4fda-a244-4abd9c7e0225', '送考功崔郎中赴闕', '送考功崔郎中赴闕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["稱意新官又少年，秋涼身健好朝天。","青雲上了無多路，却要徐驅穩著鞭。"]', '["稱意新官又少年，秋涼身健好朝天。","青云上了無多路，却要徐驱穩著鞭。"]', '诗', 'shi', '', NULL, '送考功崔郎中赴闕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96108067-1aa0-48f2-a957-097e98c34c5b', '重修香山寺畢題二十二韻以紀之', '重修香山寺畢題二十二韻以紀之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["闕塞龍門口，祇園鷲嶺頭。","曾隨減劫壞，今遇勝緣修。","再瑩新金剎，重裝舊石樓。","病僧皆引起，忙客亦淹留。","四望窮沙界，孤標出贍州。","地圖鋪洛邑，天柱倚崧丘。","兩面蒼蒼岸，中心瑟瑟流。","波翻八灘雪，堰護一潭油。","臺殿朝彌麗，房廊夜更幽。","千花高下塔，一葉往來舟。","岫合雲初吐，林開霧半收。","靜聞樵子語，遠聽棹郎謳。","官散殊無事，身閑甚自由。","吟來攜筆硯，宿去抱衾裯。","霽月當窗白，涼風滿簟秋。","煙香封藥竈，泉冷洗茶甌。","南祖心應學，西方社可投。","先宜知止足，次要悟浮休。","覺路隨方樂，迷塗到老愁。","須除愛名障，莫作戀家囚。","便合窮年住，何言竟日遊。","可憐終老地，此是我菟裘。"]', '["闕塞龙门口，祇园鷲嶺头。","曾隨減劫壞，今遇勝緣修。","再瑩新金剎，重裝旧石楼。","病僧皆引起，忙客亦淹留。","四望窮沙界，孤標出贍州。","地圖鋪洛邑，天柱倚崧丘。","兩面蒼蒼岸，中心瑟瑟流。","波翻八灘雪，堰護一潭油。","台殿朝彌丽，房廊夜更幽。","千花高下塔，一葉往来舟。","岫合云初吐，林开霧半收。","静闻樵子語，远听棹郎謳。","官散殊無事，身闲甚自由。","吟来携笔硯，宿去抱衾裯。","霽月當窗白，涼风满簟秋。","煙香封藥竈，泉冷洗茶甌。","南祖心應学，西方社可投。","先宜知止足，次要悟浮休。","覺路隨方乐，迷塗到老愁。","須除愛名障，莫作戀家囚。","便合窮年住，何言竟日游。","可怜終老地，此是我菟裘。"]', '诗', 'shi', '', NULL, '重修香山寺畢題二十二韻以紀之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32665393-d2bb-455c-8152-5daf1f7285ff', '送楊八給事赴常州', '送楊八給事赴常州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無嗟別青瑣，且喜擁朱輪。","五十得三品，百千無一人。","須勤念黎庶，莫苦憶交親。","此外無過醉，毗陵何限春。"]', '["無嗟別青瑣，且喜擁朱輪。","五十得三品，百千無一人。","須勤念黎庶，莫苦憶交親。","此外無過醉，毗陵何限春。"]', '诗', 'shi', '', NULL, '送楊八給事赴常州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('796d2ab3-7d90-4856-b151-49e011156dea', '聞歌者唱微之詩', '闻歌者唱微之诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新詩絕筆聲名歇，舊卷生塵篋笥深。","時向歌中聞一句，未容傾耳已傷心。"]', '["新诗絕笔声名歇，旧卷生塵篋笥深。","时向歌中闻一句，未容傾耳已傷心。"]', '诗', 'shi', '', NULL, '聞歌者唱微之詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73845d0d-3584-4daa-97b9-ca73859ff4f1', '醉送李二十常侍赴鎮浙東', '醉送李二十常侍赴鎮浙东', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["靖安客舍花枝下，共脫青衫典濁醪。","今日洛橋還醉別，金杯翻汙麒麟袍。","喧闐夙駕君脂轄，酩酊離筵我藉糟。","好去商山紫芝伴，珊瑚鞭動馬頭高。"]', '["靖安客舍花枝下，共脫青衫典濁醪。","今日洛橋還醉別，金杯翻汙麒麟袍。","喧闐夙駕君脂轄，酩酊離筵我藉糟。","好去商山紫芝伴，珊瑚鞭动马头高。"]', '诗', 'shi', '', NULL, '醉送李二十常侍赴鎮浙東 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e714d456-4d51-490a-ae42-feab7529d259', '醉別程秀才', '醉別程秀才', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五度龍門點額迴，却緣多藝復多才。","貧泥客路黏難出，愁鎖鄉心掣不開。","何必更遊京國去，不如且入醉鄉來。","吳弦楚調瀟湘弄，爲我殷勤送一杯。"]', '["五度龙门点額迴，却緣多藝复多才。","貧泥客路黏难出，愁鎖乡心掣不开。","何必更游京国去，不如且入醉乡来。","吳弦楚調瀟湘弄，爲我殷勤送一杯。"]', '诗', 'shi', '', NULL, '醉別程秀才 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b603ebd-6ad7-493a-bddd-501ca2344341', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白衣居士紫芝仙，半醉行歌半坐禪。","今日維摩兼飲酒，當時綺季不請錢。","等閑池上留賓客，隨事燈前有管弦。","但問此身銷得否，分司氣味不論年。"]', '["白衣居士紫芝仙，半醉行歌半坐禪。","今日維摩兼饮酒，當时綺季不請錢。","等闲池上留賓客，隨事灯前有管弦。","但问此身銷得否，分司氣味不論年。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('13cc88b7-535c-4b7d-89df-18120ec96632', '把酒思閑事二首 一', '把酒思闲事二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["把酒思閑事，春愁誰最深。","乞錢羈客面，落第舉人心。","月下低眉立，燈前抱膝吟。","憑君勸一醉，勝與萬黃金。"]', '["把酒思闲事，春愁誰最深。","乞錢羈客面，落第舉人心。","月下低眉立，灯前抱膝吟。","憑君勸一醉，勝與万黄金。"]', '诗', 'shi', '', NULL, '把酒思閑事二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fab3a94-503b-4d35-8b11-8df2107fdedc', '把酒思閑事二首 二', '把酒思闲事二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["把酒思閑事，春嬌何處多。","試鞍新白馬，弄鏡小青娥。","掌上初教舞，花前欲按歌。","憑君勸一醉，勸了問如何。"]', '["把酒思闲事，春嬌何处多。","試鞍新白马，弄镜小青娥。","掌上初教舞，花前欲按歌。","憑君勸一醉，勸了问如何。"]', '诗', 'shi', '', NULL, '把酒思閑事二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5876ce59-4a0c-42d8-bd90-141ae68cba17', '衰荷', '衰荷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白露凋花花不殘，涼風吹葉葉初乾。","無人解愛蕭條境，更繞衰藂一匝看。"]', '["白露凋花花不殘，涼风吹葉葉初乾。","無人解愛蕭條境，更繞衰藂一匝看。"]', '诗', 'shi', '', NULL, '衰荷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ce224c4-d210-4663-b43c-2ee1adc87ebb', '池上送考功崔郎中兼別房竇二妓', '池上送考功崔郎中兼別房竇二妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["文昌列宿徵還日，洛浦行雲放散時。","鵷鷺上天花逐水，無因再會白家池。"]', '["文昌列宿徵還日，洛浦行云放散时。","鵷鷺上天花逐水，無因再會白家池。"]', '诗', 'shi', '', NULL, '池上送考功崔郎中兼別房竇二妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f3f01b2-a125-4116-b69d-d1b6cb1c06e8', '自問', '自问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["依仁臺廢悲風晚，履信池荒宿草春。","自問老身騎馬出，洛陽城裏覓何人。"]', '["依仁台廢悲风晚，履信池荒宿草春。","自问老身騎马出，洛陽城裏覓何人。"]', '诗', 'shi', '', NULL, '自問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3aa5fed-7929-4548-9806-8934bf6846d9', '送陳許高僕射赴鎮', '送陳許高僕射赴鎮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["敦詩說禮中軍師，重士輕財大丈夫。","常與師徒同苦樂，不教親故隔榮枯。","花鈿坐繞黃金印，絲管行隨白玉壺。","商皓老狂唯愛醉，時時能寄酒錢無。"]', '["敦诗说禮中軍師，重士轻財大丈夫。","常與師徒同苦乐，不教親故隔榮枯。","花鈿坐繞黄金印，絲管行隨白玉壺。","商皓老狂唯愛醉，时时能寄酒錢無。"]', '诗', 'shi', '', NULL, '送陳許高僕射赴鎮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('211b87d4-f55d-4a61-b858-e714d07c81af', '青氈帳二十韻', '青氈帳二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["合聚千羊毳，施張百子弮。","骨盤邊柳健，色染塞藍鮮。","北製因戎剏，南移逐虜遷。","汰風吹不動，禦雨濕彌堅。","有頂中央聳，無隅四嚮圓。","傍通門豁爾，內密氣溫然。","遠別關山外，初安庭戶前。","影孤明月夜，價重苦寒年。","軟煖圍氈毯，鎗摐束管弦。","最宜霜後地，偏稱雪中天。","側置低歌座，平鋪小舞筵。","閑多揭簾入，醉便擁袍眠。","鐵檠移燈背，銀囊帶火懸。","深藏曉蘭焰，闇貯宿香煙。","獸炭休親近，狐裘可棄捐。","硯溫融凍墨，瓶煖變春泉。","蕙帳徒招隱，茅庵浪坐禪。","貧僧應歎羨，寒士定留連。","賓客於中接，兒孫向後傳。","王家誇舊物，未及此青氈。"]', '["合聚千羊毳，施張百子弮。","骨盤邊柳健，色染塞藍鲜。","北製因戎剏，南移逐虜遷。","汰风吹不动，禦雨濕彌堅。","有頂中央聳，無隅四嚮圓。","傍通门豁爾，內密氣溫然。","远別关山外，初安庭戶前。","影孤明月夜，價重苦寒年。","軟煖圍氈毯，鎗摐束管弦。","最宜霜後地，偏稱雪中天。","側置低歌座，平鋪小舞筵。","闲多揭簾入，醉便擁袍眠。","鐵檠移灯背，銀囊带火懸。","深藏晓蘭焰，闇貯宿香煙。","獸炭休親近，狐裘可棄捐。","硯溫融凍墨，瓶煖变春泉。","蕙帳徒招隐，茅庵浪坐禪。","貧僧應歎羨，寒士定留連。","賓客於中接，兒孫向後傳。","王家誇旧物，未及此青氈。"]', '诗', 'shi', '', NULL, '青氈帳二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7330b304-e43a-4826-9ba7-d045b6507c1f', '荅夢得秋日書懷見寄', '荅梦得秋日书懷见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幸免非常病，甘當本分衰。","眼昏燈最覺，腰瘦帶先知。","樹葉霜紅日，髭鬚雪白時。","悲愁緣欲老，老過却無悲。"]', '["幸免非常病，甘當本分衰。","眼昏灯最覺，腰瘦带先知。","樹葉霜紅日，髭鬚雪白时。","悲愁緣欲老，老過却無悲。"]', '诗', 'shi', '', NULL, '荅夢得秋日書懷見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7fb32f2c-572d-4902-a896-4c453e456355', '同諸客題于家公主舊宅', '同諸客題于家公主旧宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平陽舊宅少人遊，應是遊人到即愁。","布穀鳥啼桃李院，絡絲蟲怨鳳皇樓。","臺傾滑石猶殘砌，簾斷珍珠不滿鉤。","聞道至今蕭史在，髭鬚雪白向明州。"]', '["平陽旧宅少人游，應是游人到即愁。","布穀鸟啼桃李院，絡絲蟲怨鳳皇楼。","台傾滑石猶殘砌，簾斷珍珠不满鉤。","闻道至今蕭史在，髭鬚雪白向明州。"]', '诗', 'shi', '', NULL, '同諸客題于家公主舊宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50f12723-796f-42ad-851b-8fc53963c31b', '荅夢得八月十五日夜翫月見寄', '荅梦得八月十五日夜翫月见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南國碧雲客，東京白首翁。","松江初有月，伊水正無風。","遠思兩鄉斷，清光千里同。","不知娃館上，何似石樓中。"]', '["南国碧云客，东京白首翁。","松江初有月，伊水正無风。","远思兩乡斷，清光千里同。","不知娃館上，何似石楼中。"]', '诗', 'shi', '', NULL, '荅夢得八月十五日夜翫月見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97034772-e5f4-4862-b6d4-95ebc1e27713', '初冬早起寄夢得', '初冬早起寄梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["起戴烏紗帽，行披白布裘。","爐溫先煖酒，手冷未梳頭。","早起煙霜白，初寒鳥雀愁。","詩成遣誰和，還是寄蘇州。"]', '["起戴烏紗帽，行披白布裘。","爐溫先煖酒，手冷未梳头。","早起煙霜白，初寒鸟雀愁。","诗成遣誰和，還是寄蘇州。"]', '诗', 'shi', '', NULL, '初冬早起寄夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51bb51c6-a88c-45b2-910b-0336ce5e5a44', '秋夜聽高調涼州', '秋夜听高調涼州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樓上金風聲漸緊，月中銀字韻初調。","促張弦柱吹高管，一曲涼州入泬寥。"]', '["楼上金风声漸緊，月中銀字韻初調。","促張弦柱吹高管，一曲涼州入泬寥。"]', '诗', 'shi', '', NULL, '秋夜聽高調涼州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f151ee81-f625-4e49-a426-77038e336425', '香山寺二絕 一', '香山寺二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["空山寂靜老夫閑，伴鳥隨雲往復還。","家醞滿瓶書滿架，半移生計入香山。"]', '["空山寂静老夫闲，伴鸟隨云往复還。","家醞满瓶书满架，半移生計入香山。"]', '诗', 'shi', '', NULL, '香山寺二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d29909c2-b452-4e76-8a47-cd478a322ca4', '香山寺二絕 二', '香山寺二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛風巖上攀松蓋，戀月潭邊坐石稜。","且共雲泉結緣境，他生當作此山僧。"]', '["愛风巖上攀松蓋，戀月潭邊坐石稜。","且共云泉結緣境，他生當作此山僧。"]', '诗', 'shi', '', NULL, '香山寺二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4acf547-700d-49ce-bcc3-3b3a7037a122', '送舒著作重授省郎赴闕', '送舒著作重授省郎赴闕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三歲相依在洛都，遊花宴月飽歡娛。","惜別笙歌多怨咽，願留軒蓋少踟躕。","劒磨光彩依前出，鵬舉風雲逐後驅。","從此求閑應不得，更能重醉白家無。"]', '["三歲相依在洛都，游花宴月飽歡娛。","惜別笙歌多怨咽，願留軒蓋少踟躕。","劒磨光彩依前出，鵬舉风云逐後驱。","從此求闲應不得，更能重醉白家無。"]', '诗', 'shi', '', NULL, '送舒著作重授省郎赴闕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a01070e1-643e-454e-8fe3-6a788d2cfaac', '同諸客嘲雪中馬上妓', '同諸客嘲雪中马上妓', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["珊瑚鞭嚲馬踟躕，引手低蛾索一盂。","腰爲逆風成弱柳，面因衝冷作凝酥。","銀箆穩篸烏羅帽，花襜宜乘吒撥駒。","雪裏君看何所似，王昭君妹寫真圖。"]', '["珊瑚鞭嚲马踟躕，引手低蛾索一盂。","腰爲逆风成弱柳，面因衝冷作凝酥。","銀箆穩篸烏羅帽，花襜宜乘吒撥駒。","雪裏君看何所似，王昭君妹寫真圖。"]', '诗', 'shi', '', NULL, '同諸客嘲雪中馬上妓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cbc31bb-8c8b-4374-a165-794f4800b86f', '喜劉蘇州恩賜金紫遙[想]賀宴以詩慶之', '喜劉蘇州恩賜金紫遙[想]賀宴以诗慶之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["海內姑蘇太守賢，恩加章綬豈徒然。","賀賓喜色欺杯酒，醉妓歡聲遏管弦。","魚珮葺鱗光照地，鶻銜瑞帶勢衝天。","莫嫌鬢上些些白，金紫由來稱長年。"]', '["海內姑蘇太守賢，恩加章綬豈徒然。","賀賓喜色欺杯酒，醉妓歡声遏管弦。","鱼珮葺鱗光照地，鶻銜瑞带勢衝天。","莫嫌鬢上些些白，金紫由来稱长年。"]', '诗', 'shi', '', NULL, '喜劉蘇州恩賜金紫遙[想]賀宴以詩慶之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e621165-94ad-4db2-94de-ebfb73ece84c', '藍田劉明府攜酌相過與皇甫郎中卯時同飲醉後贈之', '藍田劉明府携酌相過與皇甫郎中卯时同饮醉後贈之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臘月九日煖寒客，卯時十分空腹杯。","玄晏舞狂烏帽落，藍田醉倒玉山頹。","貌偷花色老蹔去，歌蹋柳枝春闇來。","不爲劉家賢聖物，愁翁笑口大難開。"]', '["臘月九日煖寒客，卯时十分空腹杯。","玄晏舞狂烏帽落，藍田醉倒玉山頹。","貌偷花色老蹔去，歌蹋柳枝春闇来。","不爲劉家賢聖物，愁翁笑口大难开。"]', '诗', 'shi', '', NULL, '藍田劉明府攜酌相過與皇甫郎中卯時同飲醉後贈之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a22da1e-a3be-49f5-8fe1-0d9b3ae4d4e1', '劉蘇州以華亭一鶴遠寄以詩謝之', '劉蘇州以华亭一鹤远寄以诗謝之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老鶴風姿異，衰翁詩思深。","素毛如我鬢，丹頂似君心。","松際雪相映，雞羣塵不侵。","殷勤遠來意，一隻重千金。"]', '["老鹤风姿異，衰翁诗思深。","素毛如我鬢，丹頂似君心。","松際雪相映，雞羣塵不侵。","殷勤远来意，一隻重千金。"]', '诗', 'shi', '', NULL, '劉蘇州以華亭一鶴遠寄以詩謝之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc09fdf3-6031-446a-a27e-30b1ed4d5c47', '早春憶蘇州寄夢得', '早春憶蘇州寄梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吳苑四時風景好，就中偏好是春天。","霞光曙後殷於火，水色晴來嫩似煙。","士女笙歌宜月下，使君金紫稱花前。","誠知歡樂堪留戀，其奈離鄉已四年。"]', '["吳苑四时风景好，就中偏好是春天。","霞光曙後殷於火，水色晴来嫩似煙。","士女笙歌宜月下，使君金紫稱花前。","誠知歡乐堪留戀，其奈離乡已四年。"]', '诗', 'shi', '', NULL, '早春憶蘇州寄夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de784111-1c38-412b-b94a-3db3b1f4536f', '嘗新酒憶晦叔二首 一', '嘗新酒憶晦叔二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["尊裏看無色，杯中動有光。","自君拋我去，此物共誰嘗。"]', '["尊裏看無色，杯中动有光。","自君拋我去，此物共誰嘗。"]', '诗', 'shi', '', NULL, '嘗新酒憶晦叔二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81dd517b-fbed-40d1-9302-6535ca10e088', '嘗新酒憶晦叔二首 二', '嘗新酒憶晦叔二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世上強欺弱，人間醉勝醒。","自君拋我去，此語更誰聽。"]', '["世上強欺弱，人间醉勝醒。","自君拋我去，此語更誰听。"]', '诗', 'shi', '', NULL, '嘗新酒憶晦叔二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45539b39-e29f-440c-9737-02bfc5e54ca0', '負春', '負春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病來道士教調氣，老去山僧勸坐禪。","孤負春風楊柳曲，去年斷酒到今年。"]', '["病来道士教調氣，老去山僧勸坐禪。","孤負春风楊柳曲，去年斷酒到今年。"]', '诗', 'shi', '', NULL, '負春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5bddd1f-d034-4116-8f22-1d7a568b18a8', '池上閑吟二首 一', '池上闲吟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["高臥閑行自在身，池邊六見柳條新。","幸逢堯舜無爲日，得作羲皇向上人。","四皓再除猶且健，三州罷守未全貧。","莫愁客到無供給，家醞香濃野菜春。"]', '["高臥闲行自在身，池邊六见柳條新。","幸逢堯舜無爲日，得作羲皇向上人。","四皓再除猶且健，三州罷守未全貧。","莫愁客到無供給，家醞香濃野菜春。"]', '诗', 'shi', '', NULL, '池上閑吟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06187b4a-0070-4d0b-bdb0-77145ab0f9f7', '池上閑吟二首 二', '池上闲吟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["非莊非宅非蘭若，竹樹池亭十畝餘。","非道非僧非俗吏，褐裘烏帽閉門居。","夢遊信意寧殊蝶，心樂身閑便是魚。","雖未定知生與死，其間勝負兩何如。"]', '["非莊非宅非蘭若，竹樹池亭十畝餘。","非道非僧非俗吏，褐裘烏帽閉门居。","梦游信意寧殊蝶，心乐身闲便是鱼。","雖未定知生與死，其间勝負兩何如。"]', '诗', 'shi', '', NULL, '池上閑吟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44ddbb45-11fb-4025-a953-642501430210', '早春招張賓客', '早春招張賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["久雨初晴天氣新，風煙草樹盡欣欣。","雖當冷落衰殘日，還有陽和暖活身。","池色溶溶藍染水，花光燄燄火燒春。","商山老伴相收拾，不用隨他年少人。"]', '["久雨初晴天氣新，风煙草樹尽欣欣。","雖當冷落衰殘日，還有陽和暖活身。","池色溶溶藍染水，花光燄燄火燒春。","商山老伴相收拾，不用隨他年少人。"]', '诗', 'shi', '', NULL, '早春招張賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e4e7c726-dbf6-424e-b9cc-a391f9253df8', '營閑事', '營闲事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["自笑營閑事，從朝到日斜。","澆畦引泉脉，掃徑避蘭芽。","暖變牆衣色，晴催木筆花。","桃根知酒渴，晚送一甌茶。"]', '["自笑營闲事，從朝到日斜。","澆畦引泉脉，掃徑避蘭芽。","暖变牆衣色，晴催木笔花。","桃根知酒渴，晚送一甌茶。"]', '诗', 'shi', '', NULL, '營閑事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62eb98b5-065c-4cc6-bc2b-0e890b605597', '感春', '感春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老思不禁春，風光照眼新。","花房紅鳥觜，池浪碧魚鱗。","倚櫂誰爲伴，持杯自問身。","心情多少在，六十二三人。"]', '["老思不禁春，风光照眼新。","花房紅鸟觜，池浪碧鱼鱗。","倚櫂誰爲伴，持杯自问身。","心情多少在，六十二三人。"]', '诗', 'shi', '', NULL, '感春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('610ceff4-26bd-4de4-a825-c3ec363646b0', '春池上戲贈李郎中', '春池上戲贈李郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滿池春水何人愛，唯我迴看指似君。","直似挼藍新汁色，與君南宅染羅裙。"]', '["满池春水何人愛，唯我迴看指似君。","直似挼藍新汁色，與君南宅染羅裙。"]', '诗', 'shi', '', NULL, '春池上戲贈李郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('54a19f5c-7a5c-4588-bbd1-9a354bea5771', '翫半開花贈皇甫郎中', '翫半开花贈皇甫郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勿訝春來晚，無嫌花發遲。","人憐全盛日，我愛半開時。","紫蠟黏爲蔕，紅蘇點作蕤。","成都新夾纈，梁漢碎臙脂。","樹杪真珠顆，牆頭小女兒。","淺深妝駮落，高下火參差。","蝶戲爭香朵，鶯啼選穩枝。","好教郎作伴，合共酒相隨。","醉翫無勝此，狂嘲更讓誰。","猶殘少年興，不似老人詩。","西日憑輕照，東風莫殺吹。","明朝應爛熳，後夜更離披。","林下遙相憶，尊前闇有期。","銜杯嚼蘂思，唯我與君知。"]', '["勿訝春来晚，無嫌花發遲。","人怜全盛日，我愛半开时。","紫蠟黏爲蔕，紅蘇点作蕤。","成都新夾纈，梁漢碎臙脂。","樹杪真珠顆，牆头小女兒。","淺深妝駮落，高下火參差。","蝶戲爭香朵，鶯啼選穩枝。","好教郎作伴，合共酒相隨。","醉翫無勝此，狂嘲更讓誰。","猶殘少年兴，不似老人诗。","西日憑轻照，东风莫殺吹。","明朝應爛熳，後夜更離披。","林下遙相憶，尊前闇有期。","銜杯嚼蘂思，唯我與君知。"]', '诗', 'shi', '', NULL, '翫半開花贈皇甫郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d88b2b27-bbf9-45fc-94dd-952f28b7332b', '池邊', '池邊', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳老香絲宛，荷新鈿扇圓。","殘春深樹裏，斜日小樓前。","醉遣收杯杓，閑聽理管弦。","池邊更無事，看補採蓮船。"]', '["柳老香絲宛，荷新鈿扇圓。","殘春深樹裏，斜日小楼前。","醉遣收杯杓，闲听理管弦。","池邊更無事，看補採蓮船。"]', '诗', 'shi', '', NULL, '池邊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1932ac3-5151-438b-8e51-c7b638b7578d', '家釀新熟每嘗輙醉妻姪等勸令少飲因成長句以諭之', '家釀新熟每嘗輙醉妻姪等勸令少饮因成长句以諭之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君應怪我朝朝飲，不說向君君不知。","身上幸無疼痛處，甕頭正是撇嘗時。","劉妻勸諫夫休醉，王姪分疎叔不癡。","六十三翁頭雪白，假如醒黠欲何爲。"]', '["君應怪我朝朝饮，不说向君君不知。","身上幸無疼痛处，甕头正是撇嘗时。","劉妻勸諫夫休醉，王姪分疎叔不癡。","六十三翁头雪白，假如醒黠欲何爲。"]', '诗', 'shi', '', NULL, '家釀新熟每嘗輙醉妻姪等勸令少飲因成長句以諭之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cde1e7c5-aa1b-45a2-b5a3-7be04b7bd112', '送常秀才下第東歸', '送常秀才下第东归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東歸多旅恨，西上少知音。","寒食看花眼，春風落日心。","百憂當二月，一醉直千金。","到處公卿席，無辭酒醆深。"]', '["东归多旅恨，西上少知音。","寒食看花眼，春风落日心。","百憂當二月，一醉直千金。","到处公卿席，無辞酒醆深。"]', '诗', 'shi', '', NULL, '送常秀才下第東歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb0b08fe-4d26-4678-ad04-f90d1d3f5d3d', '且遊', '且游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["手裏一杯滿，心中百事休。","春應唯仰醉，老更不禁愁。","弄水迴船尾，尋花信馬頭。","眼看筋力減，遊得且須遊。"]', '["手裏一杯满，心中百事休。","春應唯仰醉，老更不禁愁。","弄水迴船尾，尋花信马头。","眼看筋力減，游得且須游。"]', '诗', 'shi', '', NULL, '且遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37ddd661-ba74-4582-b457-e4ad52fcad67', '題王家莊臨水柳亭', '題王家莊臨水柳亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["弱柳緣堤種，虛亭壓水開。","條疑逐風去，波欲上階來。","翠羽偷魚入，紅腰學舞迴。","春愁正無緒，爭不盡殘杯。"]', '["弱柳緣堤種，虛亭壓水开。","條疑逐风去，波欲上階来。","翠羽偷鱼入，紅腰学舞迴。","春愁正無緒，爭不尽殘杯。"]', '诗', 'shi', '', NULL, '題王家莊臨水柳亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07c4f938-715a-4f1d-85ee-b8dadf2c60cb', '題令狐家木蘭花', '題令狐家木蘭花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["膩如玉指塗朱粉，光似金刀剪紫霞。","從此時時春夢裏，應添一樹女郎花。"]', '["膩如玉指塗朱粉，光似金刀剪紫霞。","從此时时春梦裏，應添一樹女郎花。"]', '诗', 'shi', '', NULL, '題令狐家木蘭花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c07c47a6-f2ca-4120-a83e-cf30b1b2fea8', '拜表迴閑遊', '拜表迴闲游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉珮金章紫花綬，紵衫藤帶白綸巾。","晨興拜表稱朝士，晚出遊山作野人。","達磨傳心令息念，玄元留意遣同塵。","八關淨戒齋銷日，一曲狂歌醉送春。","酒肆法堂方丈室，其間豈是兩般身。"]', '["玉珮金章紫花綬，紵衫藤带白綸巾。","晨兴拜表稱朝士，晚出游山作野人。","達磨傳心令息念，玄元留意遣同塵。","八关淨戒斋銷日，一曲狂歌醉送春。","酒肆法堂方丈室，其间豈是兩般身。"]', '诗', 'shi', '', NULL, '拜表迴閑遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('177aa578-cc9d-41ac-8cb5-a7a9ec8ccb25', '西街渠中種蓮疊石頗有幽致偶題小樓', '西街渠中種蓮叠石頗有幽致偶題小楼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["朱檻低牆上，清流小閣前。","雇人栽菡萏，買石造潺湲。","影落江心月，聲移谷口泉。","閑看捲簾坐，醉聽掩窗眠。","路笑淘官水，家愁費料錢。","是非君莫問，一對一翛然。"]', '["朱檻低牆上，清流小閣前。","雇人栽菡萏，買石造潺湲。","影落江心月，声移谷口泉。","闲看捲簾坐，醉听掩窗眠。","路笑淘官水，家愁費料錢。","是非君莫问，一对一翛然。"]', '诗', 'shi', '', NULL, '西街渠中種蓮疊石頗有幽致偶題小樓 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ca1001f-fdbb-40f3-8338-ded648912642', '晚春閑居楊工部寄詩楊常州寄茶同到因以長句荅之', '晚春闲居楊工部寄诗楊常州寄茶同到因以长句荅之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宿酲寂寞眠初起，春意闌珊日又斜。","勸我加餐因早笋，恨人休醉是殘花。","悶吟工部新來句，渴飲毗陵遠到茶。","兄弟東西官職冷，門前車馬向誰家。"]', '["宿酲寂寞眠初起，春意闌珊日又斜。","勸我加餐因早笋，恨人休醉是殘花。","悶吟工部新来句，渴饮毗陵远到茶。","兄弟东西官職冷，门前车马向誰家。"]', '诗', 'shi', '', NULL, '晚春閑居楊工部寄詩楊常州寄茶同到因以長句荅之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa1519b2-9672-4180-bb9b-ee784546df6a', '玉泉寺南三里澗下多深紅躑躅繁豔殊常感惜題詩以示遊者', '玉泉寺南三里澗下多深紅躑躅繁豔殊常感惜題诗以示游者', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉泉南澗花奇怪，不似花叢似火堆。","今日多情唯我到，每年無故爲誰開。","寧辭辛苦行三里，更與留連飲兩杯。","猶有一般辜負事，不將歌舞管弦來。"]', '["玉泉南澗花奇怪，不似花叢似火堆。","今日多情唯我到，每年無故爲誰开。","寧辞辛苦行三里，更與留連饮兩杯。","猶有一般辜負事，不將歌舞管弦来。"]', '诗', 'shi', '', NULL, '玉泉寺南三里澗下多深紅躑躅繁豔殊常感惜題詩以示遊者 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3086dd76-b86f-4ecc-8047-b708078596d0', '早服雲母散', '早服云母散', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["曉服雲英漱井華，寥然身若在煙霞。","藥銷日晏三匙飯，酒渴春深一椀茶。","每夜坐禪觀水月，有時行醉翫風花。","淨名事理人難解，身不出家心出家。"]', '["晓服云英漱井华，寥然身若在煙霞。","藥銷日晏三匙飯，酒渴春深一椀茶。","每夜坐禪观水月，有时行醉翫风花。","淨名事理人难解，身不出家心出家。"]', '诗', 'shi', '', NULL, '早服雲母散 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14488040-d6a1-4e2c-b698-f84d179590ad', '三月晦日晚聞鳥聲', '三月晦日晚闻鸟声', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["晚來林鳥語殷勤，似惜風光說向人。","遣脫破袍勞報煖，催沽美酒敢辭貧。","聲聲勸醉應須醉，一歲唯殘半日春。"]', '["晚来林鸟語殷勤，似惜风光说向人。","遣脫破袍勞報煖，催沽美酒敢辞貧。","声声勸醉應須醉，一歲唯殘半日春。"]', '诗', 'shi', '', NULL, '三月晦日晚聞鳥聲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b45a7650-d847-4b34-94dc-681030e0e0f1', '早夏遊平原迴', '早夏游平原迴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夏早日初長，南風草木香。","肩輿頗平穩，澗路甚清涼。","紫蕨行看採，青梅旋摘嘗。","療飢兼解渴，一醆冷雲漿。"]', '["夏早日初长，南风草木香。","肩輿頗平穩，澗路甚清涼。","紫蕨行看採，青梅旋摘嘗。","療飢兼解渴，一醆冷云漿。"]', '诗', 'shi', '', NULL, '早夏遊平原迴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52bd5ff2-6ac0-49c0-9312-c428f58d2a95', '宿天竺寺迴', '宿天竺寺迴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野寺經三宿，都城復一還。","家仍念婚嫁，身尚繫官班。","蕭灑秋臨水，沈吟晚下山。","長閑猶未得，逐日且偷閑。"]', '["野寺經三宿，都城复一還。","家仍念婚嫁，身尚繫官班。","蕭灑秋臨水，沈吟晚下山。","长闲猶未得，逐日且偷闲。"]', '诗', 'shi', '', NULL, '宿天竺寺迴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e5a0294-dcd3-4a51-b605-99cae1709a04', '侍中晉公欲到東洛先蒙書問期宿龍門思往感今輙獻長句', '侍中晉公欲到东洛先蒙书问期宿龙门思往感今輙獻长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["昔蒙興化池頭送，今許龍門潭上期。","聚散但慙長見念，榮枯安敢道相思。","功成名遂來雖久，雲臥山遊去未遲。","聞說風情筋力在，只如初破蔡州時。"]', '["昔蒙兴化池头送，今許龙门潭上期。","聚散但慙长见念，榮枯安敢道相思。","功成名遂来雖久，云臥山游去未遲。","闻说风情筋力在，只如初破蔡州时。"]', '诗', 'shi', '', NULL, '侍中晉公欲到東洛先蒙書問期宿龍門思往感今輙獻長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1be4afb0-31a4-43b3-8702-68502042b8f6', '奉和晉公侍中蒙除留守行及洛師感悅發中斐然成詠之作', '奉和晉公侍中蒙除留守行及洛師感悅發中斐然成詠之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鸞鳳翺翔在寥廓，貂蟬蕭灑出埃塵。","致成堯舜昇平代，收得夔龍強健身。","拋擲功名還史冊，分張歡樂與交親。","商山老皓雖休去，終是留侯門下人。"]', '["鸾鳳翺翔在寥廓，貂蟬蕭灑出埃塵。","致成堯舜昇平代，收得夔龙強健身。","拋擲功名還史冊，分張歡乐與交親。","商山老皓雖休去，終是留侯门下人。"]', '诗', 'shi', '', NULL, '奉和晉公侍中蒙除留守行及洛師感悅發中斐然成詠之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb1f1e00-a42b-4713-9702-7dacf03860d7', '送劉五司馬赴任硤州兼寄崔使君', '送劉五司马赴任硤州兼寄崔使君', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["位下才高多怨天，劉兄道勝獨恬然。","貧於揚子兩三倍，老過榮公六七年。","筆硯莫拋留壓案，簞瓢從陋也銷錢。","郡丞自合當優禮，何況夷陵太守賢。"]', '["位下才高多怨天，劉兄道勝独恬然。","貧於揚子兩三倍，老過榮公六七年。","笔硯莫拋留壓案，簞瓢從陋也銷錢。","郡丞自合當優禮，何況夷陵太守賢。"]', '诗', 'shi', '', NULL, '送劉五司馬赴任硤州兼寄崔使君 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4e7c27d-8474-4b48-9946-fe4e19cb4379', '菩提寺上方晚眺', '菩提寺上方晚眺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樓閣高低樹淺深，山光水色暝沈沈。","嵩煙半卷青綃幕，伊浪平鋪綠綺衾。","飛鳥滅時宜極目，遠風來處好開襟。","誰知不離簪纓內，長得逍遙自在心。"]', '["楼閣高低樹淺深，山光水色暝沈沈。","嵩煙半卷青綃幕，伊浪平鋪綠綺衾。","飞鸟滅时宜極目，远风来处好开襟。","誰知不離簪纓內，长得逍遙自在心。"]', '诗', 'shi', '', NULL, '菩提寺上方晚眺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f52081-6d77-4413-b7d7-1d7d7c8e9ad8', '楊柳枝詞八首 一', '楊柳枝词八首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六么水調家家唱，白雪梅花處處吹。","古歌舊曲君休聽，聽取新翻楊柳枝。"]', '["六么水調家家唱，白雪梅花处处吹。","古歌旧曲君休听，听取新翻楊柳枝。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08e1212d-c37a-4011-a548-5595f6aac7ad', '楊柳枝詞八首 二', '楊柳枝词八首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陶令門前四五樹，亞夫營裏百千條。","何似東都正二月，黃金枝映洛陽橋。"]', '["陶令门前四五樹，亞夫營裏百千條。","何似东都正二月，黄金枝映洛陽橋。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('475610ec-d8d1-44d1-b645-842f2ca5b2db', '楊柳枝詞八首 三', '楊柳枝词八首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["依依褭褭復青青，句引春風無限情。","白雪花繁空撲地，綠絲條弱不勝鶯。"]', '["依依褭褭复青青，句引春风無限情。","白雪花繁空撲地，綠絲條弱不勝鶯。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e76a50a6-101d-489a-aecb-1ced6e20464a', '楊柳枝詞八首 四', '楊柳枝词八首 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紅板江橋青酒旗，館娃宮暖日斜時。","可憐雨歇東風定，萬樹千條各自垂。"]', '["紅板江橋青酒旗，館娃宮暖日斜时。","可怜雨歇东风定，万樹千條各自垂。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fffe01f0-655e-428e-8ec5-5d5e98ea9156', '楊柳枝詞八首 五', '楊柳枝词八首 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇州楊柳任君誇，更有錢唐勝館娃。","若解多情尋小小，綠楊深處是蘇家。"]', '["蘇州楊柳任君誇，更有錢唐勝館娃。","若解多情尋小小，綠楊深处是蘇家。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88c89108-51a2-4733-9ae8-914231a94c3a', '楊柳枝詞八首 六', '楊柳枝词八首 六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蘇家小女舊知名，楊柳風前別有情。","剝條盤作銀環樣，卷葉吹爲玉笛聲。"]', '["蘇家小女旧知名，楊柳风前別有情。","剝條盤作銀环樣，卷葉吹爲玉笛声。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a452cfa-7b61-466c-ac7b-908dfd3f0c8d', '楊柳枝詞八首 七', '楊柳枝词八首 七', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉含濃露如啼眼，枝褭輕風似舞腰。","小樹不禁攀折苦，乞君留取兩三條。"]', '["葉含濃露如啼眼，枝褭轻风似舞腰。","小樹不禁攀折苦，乞君留取兩三條。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 七 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b1652de-4048-4d88-b8ed-d91d4ec5ae6a', '楊柳枝詞八首 八', '楊柳枝词八首 八', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["人言柳葉似愁眉，更有愁腸似柳絲。","柳絲挽斷腸牽斷，彼此應無續得期。"]', '["人言柳葉似愁眉，更有愁腸似柳絲。","柳絲挽斷腸牽斷，彼此應無續得期。"]', '诗', 'shi', '', NULL, '楊柳枝詞八首 八 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a5c31af-6696-45f0-90d8-4f3b877a3524', '讀老子', '读老子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["言者不如知者默，此語吾聞於老君。","若道老君是知者，緣何自著五千文。"]', '["言者不如知者默，此語吾闻於老君。","若道老君是知者，緣何自著五千文。"]', '诗', 'shi', '', NULL, '讀老子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6cadd52-2770-4210-86d3-3c17a3da94db', '讀莊子', '读莊子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莊生齊物同歸一，我道同中有不同。","遂性逍遙雖一致，鶯凰終挍勝蛇蟲。"]', '["莊生齊物同归一，我道同中有不同。","遂性逍遙雖一致，鶯凰終挍勝蛇蟲。"]', '诗', 'shi', '', NULL, '讀莊子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('811ac29a-a3fb-420c-b682-8b73a150ae00', '讀禪經', '读禪經', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["須知諸相皆非相，若住無餘却有餘。","言下忘言一時了，夢中說夢兩重虛。","空花豈得兼求果，陽燄如何更覓魚。","攝動是禪禪是動，不禪不動即如如。"]', '["須知諸相皆非相，若住無餘却有餘。","言下忘言一时了，梦中说梦兩重虛。","空花豈得兼求果，陽燄如何更覓鱼。","攝动是禪禪是动，不禪不动即如如。"]', '诗', 'shi', '', NULL, '讀禪經 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5813234-0a95-457a-b80e-bc8fe0132b1f', '感興二首 一', '感兴二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吉凶禍福有來由，但要深知不要憂。","只見火光燒潤屋，不聞風浪覆虛舟。","名爲公器無多取，利是身災合少求。","雖異匏瓜難不食，大都食足早宜休。"]', '["吉凶禍福有来由，但要深知不要憂。","只见火光燒潤屋，不闻风浪覆虛舟。","名爲公器無多取，利是身災合少求。","雖異匏瓜难不食，大都食足早宜休。"]', '诗', 'shi', '', NULL, '感興二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79cceb4a-0273-4d5f-a774-01311bd4c67c', '感興二首 二', '感兴二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["魚能深入寧憂釣，鳥解高飛豈觸羅。","熱處先爭炙手去，悔時其奈噬臍何。","尊前誘得猩猩血，幕上偷安鷰鷰窠。","我有一言君記取，世間自取苦人多。"]', '["鱼能深入寧憂釣，鸟解高飞豈觸羅。","熱处先爭炙手去，悔时其奈噬臍何。","尊前誘得猩猩血，幕上偷安鷰鷰窠。","我有一言君記取，世间自取苦人多。"]', '诗', 'shi', '', NULL, '感興二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fdebad6c-77b2-4bf0-8716-9cda25ab05c2', '問鶴', '问鹤', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["烏鳶爭食雀爭窠，獨立池邊風雪多。","盡日蹋冰翹一足，不鳴不動意如何。"]', '["烏鳶爭食雀爭窠，独立池邊风雪多。","尽日蹋冰翹一足，不鳴不动意如何。"]', '诗', 'shi', '', NULL, '問鶴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('685e910a-3468-4b42-9fca-9e1fe02a1f5f', '代鶴荅', '代鹤荅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鷹爪攫雞雞肋折，鶻拳蹴雁雁頭垂。","何如歛翅水邊立，飛上雲松棲穩枝。"]', '["鷹爪攫雞雞肋折，鶻拳蹴雁雁头垂。","何如歛翅水邊立，飞上云松棲穩枝。"]', '诗', 'shi', '', NULL, '代鶴荅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9df41e23-1cbf-47da-9214-3a9b5a35f2de', '閑臥有所思二首 一', '闲臥有所思二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["向夕搴簾臥枕琴，微涼入戶起開襟。","偶因明月清風夜，忽想遷臣逐客心。","何處投荒初恐懼，誰人繞澤正悲吟。","始知洛下分司坐，一日安閑直萬金。"]', '["向夕搴簾臥枕琴，微涼入戶起开襟。","偶因明月清风夜，忽想遷臣逐客心。","何处投荒初恐懼，誰人繞澤正悲吟。","始知洛下分司坐，一日安闲直万金。"]', '诗', 'shi', '', NULL, '閑臥有所思二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6411f5-1a30-4c98-95ba-9c1302f91f54', '閑臥有所思二首 二', '闲臥有所思二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["權門要路是身災，散地閑居少禍胎。","今日憐君嶺南去，當時笑我洛中來。","蟲全性命緣無毒，木盡天年爲不才。","大抵吉凶多自致，李斯一去二疎迴。"]', '["權门要路是身災，散地闲居少禍胎。","今日怜君嶺南去，當时笑我洛中来。","蟲全性命緣無毒，木尽天年爲不才。","大抵吉凶多自致，李斯一去二疎迴。"]', '诗', 'shi', '', NULL, '閑臥有所思二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0947d7f-1d18-4df1-8401-9c1ad0d99d24', '喜閑', '喜闲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蕭灑伊嵩下，優游黃綺間。","未曾一日悶，已得六年閑。","魚鳥爲徒侶，煙霞是往還。","伴僧禪閉目，迎客笑開顏。","興發宵遊寺，慵時晝掩關。","夜來風月好，悔不宿香山。"]', '["蕭灑伊嵩下，優游黄綺间。","未曾一日悶，已得六年闲。","鱼鸟爲徒侶，煙霞是往還。","伴僧禪閉目，迎客笑开顏。","兴發宵游寺，慵时晝掩关。","夜来风月好，悔不宿香山。"]', '诗', 'shi', '', NULL, '喜閑 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a29b4266-aa15-49fb-a60f-7c91d6b81d2a', '詩酒琴人例多薄命予酷好三事雅當此科而所得已多爲幸斯甚偶成狂詠聊寫媿懷', '诗酒琴人例多薄命予酷好三事雅當此科而所得已多爲幸斯甚偶成狂詠聊寫媿懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛琴愛酒愛詩客，多賤多窮多苦辛。","中散步兵終不貴，孟郊張籍過於貧。","一之已歎關於命，三者何堪併在身。","只合飄零隨草木，誰教凌厲出風塵。","榮名厚祿二千石，樂飲閑遊三十春。","何得無厭時咄咄，猶言薄命不如人。"]', '["愛琴愛酒愛诗客，多賤多窮多苦辛。","中散步兵終不貴，孟郊張籍過於貧。","一之已歎关於命，三者何堪併在身。","只合飄零隨草木，誰教凌厲出风塵。","榮名厚祿二千石，乐饮闲游三十春。","何得無厭时咄咄，猶言薄命不如人。"]', '诗', 'shi', '', NULL, '詩酒琴人例多薄命予酷好三事雅當此科而所得已多爲幸斯甚偶成狂詠聊寫媿懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b03a24-c565-4079-9afa-2f50bc3cf9f5', '寄明州于駙馬使君三絕句 一', '寄明州于駙马使君三絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["有花有酒有笙歌，其奈難逢親故何。","近海饒風春足雨，白鬚太守悶時多。"]', '["有花有酒有笙歌，其奈难逢親故何。","近海饒风春足雨，白鬚太守悶时多。"]', '诗', 'shi', '', NULL, '寄明州于駙馬使君三絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aeefe783-e69b-4308-ae21-75d203b1b88e', '寄明州于駙馬使君三絕句 二', '寄明州于駙马使君三絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["平陽音樂隨都尉，留滯三年在浙東。","吳越聲邪無法用，莫教偷入管弦中。"]', '["平陽音乐隨都尉，留滯三年在浙东。","吳越声邪無法用，莫教偷入管弦中。"]', '诗', 'shi', '', NULL, '寄明州于駙馬使君三絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fca155db-9375-4cd8-be50-2fe03e735c2c', '寄明州于駙馬使君三絕句 三', '寄明州于駙马使君三絕句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何郎小妓歌喉好，嚴老呼爲一串珠。","海味腥鹹損聲氣，聽看猶得斷腸無。"]', '["何郎小妓歌喉好，嚴老呼爲一串珠。","海味腥鹹損声氣，听看猶得斷腸無。"]', '诗', 'shi', '', NULL, '寄明州于駙馬使君三絕句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5caec4d-8c93-4287-a962-0f0eb8959b07', '閑臥', '闲臥', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["薄食當齋戒，散班同隱淪。","佛容爲弟子，天許作閑人。","唯置牀臨水，都無物近身。","清風散髮臥，兼不要紗巾。"]', '["薄食當斋戒，散班同隐淪。","佛容爲弟子，天許作闲人。","唯置牀臨水，都無物近身。","清风散髮臥，兼不要紗巾。"]', '诗', 'shi', '', NULL, '閑臥 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6feb0593-dbb7-44b8-8d05-8eb033c4e83c', '春早秋初因時即事兼寄浙東李侍郎', '春早秋初因时即事兼寄浙东李侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春早秋初晝夜長，可憐天氣好年光。","和風細動簾帷暖，清露微凝枕簟涼。","窗下曉眠初減被，池邊晚坐乍移牀。","閑從蕙草侵堦綠，靜任槐花滿地黃。","理曲管弦聞後院，熨衣燈火映深房。","四時新景何人別，遙憶多情李侍郎。"]', '["春早秋初晝夜长，可怜天氣好年光。","和风細动簾帷暖，清露微凝枕簟涼。","窗下晓眠初減被，池邊晚坐乍移牀。","闲從蕙草侵堦綠，静任槐花满地黄。","理曲管弦闻後院，熨衣灯火映深房。","四时新景何人別，遙憶多情李侍郎。"]', '诗', 'shi', '', NULL, '春早秋初因時即事兼寄浙東李侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19412a2f-f0b9-4ab8-ba03-9427a833eb2c', '新秋喜涼', '新秋喜涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["過得炎蒸月，尤宜老病身。","衣裳朝不潤，枕簟夜相親。","樓月纖纖早，波風褭褭新。","光陰與時節，先感是詩人。"]', '["過得炎蒸月，尤宜老病身。","衣裳朝不潤，枕簟夜相親。","楼月纖纖早，波风褭褭新。","光陰與时節，先感是诗人。"]', '诗', 'shi', '', NULL, '新秋喜涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a03a42e2-ce4f-4967-aaa5-15268d718a0a', '初夏閑吟兼呈韋賓客', '初夏闲吟兼呈韋賓客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["孟夏清和月，東都閑散官。","體中無病痛，眼下未飢寒。","世事聞常悶，交游見即歡。","杯觴留客切，妓樂取人寬。","雪鬢隨身老，雲心著處安。","此中殊有味，試說向君看。"]', '["孟夏清和月，东都闲散官。","體中無病痛，眼下未飢寒。","世事闻常悶，交游见即歡。","杯觴留客切，妓乐取人寬。","雪鬢隨身老，云心著处安。","此中殊有味，試说向君看。"]', '诗', 'shi', '', NULL, '初夏閑吟兼呈韋賓客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1c1c298-ba3d-46ba-b70e-512dd83f591b', '哭崔二十四常侍', '哭崔二十四常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["貂冠初別九重門，馬鬣新封四尺墳。","薤露歌詞非白雪，旌銘官爵是浮雲。","伯倫每置隨身鍤，元亮先爲自祭文。","莫道高風無繼者，一千年內有崔君。"]', '["貂冠初別九重门，马鬣新封四尺墳。","薤露歌词非白雪，旌銘官爵是浮云。","伯倫每置隨身鍤，元亮先爲自祭文。","莫道高风無繼者，一千年內有崔君。"]', '诗', 'shi', '', NULL, '哭崔二十四常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e441d9a0-276e-435e-bf64-95d16696a10e', '奉酬侍中夏中雨後遊城南莊見示八韻', '奉酬侍中夏中雨後游城南莊见示八韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["島樹間林巒，雲收雨氣殘。","四山嵐色重，五月水聲寒。","老鶴兩三隻，新篁千萬竿。","化成天竺寺，移得子陵灘。","心覺閑彌貴，身緣健更歡。","帝將風后待，人作謝公看。","甪里年雖老，高陽興未闌。","佳辰不見召，爭免趂杯盤。"]', '["島樹间林巒，云收雨氣殘。","四山嵐色重，五月水声寒。","老鹤兩三隻，新篁千万竿。","化成天竺寺，移得子陵灘。","心覺闲彌貴，身緣健更歡。","帝將风后待，人作謝公看。","甪里年雖老，高陽兴未闌。","佳辰不见召，爭免趂杯盤。"]', '诗', 'shi', '', NULL, '奉酬侍中夏中雨後遊城南莊見示八韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3338f611-7892-49c6-8377-8ec17424d141', '送兖州崔大夫駙馬赴鎮', '送兖州崔大夫駙马赴鎮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["戚里誇爲賢駙馬，儒家認作好詩人。","魯侯不得辜風景，沂水年年有暮春。"]', '["戚里誇爲賢駙马，儒家認作好诗人。","魯侯不得辜风景，沂水年年有暮春。"]', '诗', 'shi', '', NULL, '送兖州崔大夫駙馬赴鎮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65b6b15c-d619-482b-a55d-9a32396277dc', '少年問', '少年问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少年怪我問如何，何事朝朝醉復歌。","號作樂天應不錯，憂愁時少樂時多。"]', '["少年怪我问如何，何事朝朝醉复歌。","號作乐天應不錯，憂愁时少乐时多。"]', '诗', 'shi', '', NULL, '少年問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4517dc3-3429-4bc0-8234-31dc271d0f4d', '問少年', '问少年', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["千首詩堆青玉案，十分酒寫白金盂。","迴頭却問諸年少，作箇狂夫得了無。"]', '["千首诗堆青玉案，十分酒寫白金盂。","迴头却问諸年少，作箇狂夫得了無。"]', '诗', 'shi', '', NULL, '問少年 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b96a1832-961d-48f5-9004-7ea944e8c071', '代琵琶弟子謝女師曹供奉寄新調弄譜', '代琵琶弟子謝女師曹供奉寄新調弄譜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["琵琶師在九重城，忽得書來喜且驚。","一紙展看非舊譜，四弦翻出是新聲。","蕤賓掩抑嬌多怨，散水玲瓏峭更清。","珠顆淚霑金捍撥，紅妝弟子不勝情。"]', '["琵琶師在九重城，忽得书来喜且驚。","一紙展看非旧譜，四弦翻出是新声。","蕤賓掩抑嬌多怨，散水玲瓏峭更清。","珠顆泪霑金捍撥，紅妝弟子不勝情。"]', '诗', 'shi', '', NULL, '代琵琶弟子謝女師曹供奉寄新調弄譜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c93627bc-9bbd-4f06-8ab1-e579e39b75f5', '代林園戲贈', '代林园戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南院今秋遊宴少，西坊近日往來頻。","假如宰相池亭好，作客何如作主人。"]', '["南院今秋游宴少，西坊近日往来頻。","假如宰相池亭好，作客何如作主人。"]', '诗', 'shi', '', NULL, '代林園戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29f1cf01-40ac-4201-b7dd-0f429a29eb86', '戲荅林園', '戲荅林园', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豈獨西坊來往頻，偷閑處處作遊人。","衡門雖是棲遲地，不可終朝鏁老身。"]', '["豈独西坊来往頻，偷闲处处作游人。","衡门雖是棲遲地，不可終朝鏁老身。"]', '诗', 'shi', '', NULL, '戲荅林園 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('413b97cc-f71d-4a93-8b36-10ef468ce45c', '重戲贈', '重戲贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["集賢池館從他盛，履道林亭勿自輕。","往往歸來嫌窄小，年年爲主莫無情。"]', '["集賢池館從他盛，履道林亭勿自轻。","往往归来嫌窄小，年年爲主莫無情。"]', '诗', 'shi', '', NULL, '重戲贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b68bafd6-8cc5-42dd-978a-420b842baf8a', '重戲荅', '重戲荅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小水低亭自可親，大池高館不關身。","林園莫妬裴家好，憎故憐新豈是人。"]', '["小水低亭自可親，大池高館不关身。","林园莫妬裴家好，憎故怜新豈是人。"]', '诗', 'shi', '', NULL, '重戲荅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('765a8e0b-9798-438c-b806-3396a6c80d33', '早秋登天宮寺閣贈諸客', '早秋登天宮寺閣贈諸客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天宮閣上醉蕭辰，絲管閑聽酒慢巡。","爲向涼風清景道，今朝屬我兩三人。"]', '["天宮閣上醉蕭辰，絲管闲听酒慢巡。","爲向涼风清景道，今朝屬我兩三人。"]', '诗', 'shi', '', NULL, '早秋登天宮寺閣贈諸客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38434da3-f501-498a-a4f7-40767d11a417', '曉上天津橋閑望偶逢盧郎中張員外攜酒同傾', '晓上天津橋闲望偶逢盧郎中張員外携酒同傾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上陽宮裏曉鐘後，天津橋頭殘月前。","空闊境疑非下界，飄颻身似在寥天。","星河隱映初生日，樓閣蔥蘢半出煙。","此處相逢傾一醆，始知地上有神仙。"]', '["上陽宮裏晓鐘後，天津橋头殘月前。","空闊境疑非下界，飄颻身似在寥天。","星河隐映初生日，楼閣蔥蘢半出煙。","此处相逢傾一醆，始知地上有神仙。"]', '诗', 'shi', '', NULL, '曉上天津橋閑望偶逢盧郎中張員外攜酒同傾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eff11311-6798-465d-b2c3-270f8c2bf7ce', '八月十五日夜同諸客翫月', '八月十五日夜同諸客翫月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["月好共傳唯此夜，境閑皆道是東都。","嵩山表裏千重雪，洛水高低兩顆珠。","清景難逢宜愛惜，白頭相勸強歡娛。","誠知亦有來年會，保得晴明強健無。"]', '["月好共傳唯此夜，境闲皆道是东都。","嵩山表裏千重雪，洛水高低兩顆珠。","清景难逢宜愛惜，白头相勸強歡娛。","誠知亦有来年會，保得晴明強健無。"]', '诗', 'shi', '', NULL, '八月十五日夜同諸客翫月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6d62ff-dd7a-493c-a0a8-63b385f97408', '對晚開夜合花贈皇甫郎中', '对晚开夜合花贈皇甫郎中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["移晚校一月，花遲過半年。","紅開杪秋日，翠合欲昏天。","白露滴未死，涼風吹更鮮。","後時誰肯顧，唯我與君憐。"]', '["移晚校一月，花遲過半年。","紅开杪秋日，翠合欲昏天。","白露滴未死，涼风吹更鲜。","後时誰肯顧，唯我與君怜。"]', '诗', 'shi', '', NULL, '對晚開夜合花贈皇甫郎中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f5acfdd-df6d-4aa5-a42b-4fe3d965df3a', '醉遊平泉', '醉游平泉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["狂歌箕踞酒尊前，眼不看人面向天。","洛客最閑唯有我，一年四度到平泉。"]', '["狂歌箕踞酒尊前，眼不看人面向天。","洛客最闲唯有我，一年四度到平泉。"]', '诗', 'shi', '', NULL, '醉遊平泉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cae0f324-167e-4c8f-abf0-8c19e0ff7138', '題贈平泉韋徵君拾遺', '題贈平泉韋徵君拾遺', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["箕潁千年後，唯君得古風。","位留丹陛上，身入白雲中。","躁靜心相背，高低跡不同。","籠雞與梁燕，不信有冥鴻。"]', '["箕潁千年後，唯君得古风。","位留丹陛上，身入白云中。","躁静心相背，高低跡不同。","籠雞與梁燕，不信有冥鴻。"]', '诗', 'shi', '', NULL, '題贈平泉韋徵君拾遺 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2046d37-f9c4-40ed-a327-e10c26f7de43', '酬皇甫郎中對新菊花見憶', '酬皇甫郎中对新菊花见憶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["愛菊高人吟逸韻，悲秋病客感衰懷。","黃花助興方攜酒，紅葉添愁正滿堦。","居士葷腥今已斷，仙郎杯杓爲誰排。","媿君相憶東籬下，擬廢重陽一日齋。"]', '["愛菊高人吟逸韻，悲秋病客感衰懷。","黄花助兴方携酒，紅葉添愁正满堦。","居士葷腥今已斷，仙郎杯杓爲誰排。","媿君相憶东籬下，擬廢重陽一日斋。"]', '诗', 'shi', '', NULL, '酬皇甫郎中對新菊花見憶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('917f5f0e-0271-4135-8e6f-9d4b070e51a4', '夜宴醉後留獻裴侍中', '夜宴醉後留獻裴侍中', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九燭臺前十二姝，主人留醉任歡娛。","翩翻舞袖雙飛蝶，宛轉歌聲一索珠。","坐久欲醒還酩酊，夜深初散又踟躕。","南山賓客東山妓，此會人間曾有無。"]', '["九燭台前十二姝，主人留醉任歡娛。","翩翻舞袖雙飞蝶，宛轉歌声一索珠。","坐久欲醒還酩酊，夜深初散又踟躕。","南山賓客东山妓，此會人间曾有無。"]', '诗', 'shi', '', NULL, '夜宴醉後留獻裴侍中 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b141253-20f6-4fed-a0e4-7f682b08493c', '和韋庶子遠坊赴宴未夜先歸之作兼呈裴員外', '和韋庶子远坊赴宴未夜先归之作兼呈裴員外', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["促席留歡日未曛，遠坊歸思已紛紛。","無妨按轡行乘月，何必逃杯走似雲。","銀燭忍拋楊柳曲，金鞍潛送石榴裙。","到時常晚歸時早，笑樂三分校一分。"]', '["促席留歡日未曛，远坊归思已紛紛。","無妨按轡行乘月，何必逃杯走似云。","銀燭忍拋楊柳曲，金鞍潛送石榴裙。","到时常晚归时早，笑乐三分校一分。"]', '诗', 'shi', '', NULL, '和韋庶子遠坊赴宴未夜先歸之作兼呈裴員外 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e7a1a50-bd14-4798-a5e3-91fce0f78b55', '集賢池荅侍中問', '集賢池荅侍中问', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["主人晚入皇城宿，問客裴回何所須。","池月幸閑無用處，今宵能借客遊無。"]', '["主人晚入皇城宿，问客裴回何所須。","池月幸闲無用处，今宵能借客游無。"]', '诗', 'shi', '', NULL, '集賢池荅侍中問 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaac8550-c911-445a-90c3-9746fbd61551', '楊柳枝二十韻', '楊柳枝二十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小妓攜桃葉，新聲蹋柳枝。","妝成剪燭後，醉起拂衫時。","繡履嬌行緩，花筵笑上遲。","身輕委迴雪，羅薄透凝脂。","笙引簧頻煖，箏催柱數移。","樂童翻怨調，才子與妍詞。","便想人如樹，先將髮比絲。","風條搖兩帶，煙葉貼雙眉。","口動櫻桃破，鬟低翡翠垂。","枝柔腰嫋娜，荑嫩手葳蕤。","唳鶴啨呼侶，哀猨夜呌兒。","玉敲音歷歷，珠貫字纍纍。","袖爲收聲點，釵因赴節遺。","重重遍頭別，一一拍心知。","塞北愁攀折，江南苦別離。","黃遮金谷岸，綠映杏園池。","春惜芳華好，秋憐顏色衰。","取來歌裏唱，勝向笛中吹。","曲罷那能別，情多不自持。","纏頭無別物，一首斷腸詩。"]', '["小妓携桃葉，新声蹋柳枝。","妝成剪燭後，醉起拂衫时。","繡履嬌行緩，花筵笑上遲。","身轻委迴雪，羅薄透凝脂。","笙引簧頻煖，箏催柱數移。","乐童翻怨調，才子與妍词。","便想人如樹，先將髮比絲。","风條搖兩带，煙葉貼雙眉。","口动櫻桃破，鬟低翡翠垂。","枝柔腰嫋娜，荑嫩手葳蕤。","唳鹤啨呼侶，哀猨夜呌兒。","玉敲音歷歷，珠貫字纍纍。","袖爲收声点，釵因赴節遺。","重重遍头別，一一拍心知。","塞北愁攀折，江南苦別離。","黄遮金谷岸，綠映杏园池。","春惜芳华好，秋怜顏色衰。","取来歌裏唱，勝向笛中吹。","曲罷那能別，情多不自持。","纏头無別物，一首斷腸诗。"]', '诗', 'shi', '', NULL, '楊柳枝二十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cce0fc7-6785-4863-a4f6-e42c4ff4dcad', '荅皇甫十郎中秋深酒熟見憶', '荅皇甫十郎中秋深酒熟见憶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["煙景冷蒼茫，秋深夜夜霜。","爲思池上酌，先覺甕頭香。","未暇傾巾漉，還應染指嘗。","醍醐慙氣味，琥珀讓晶光。","若許陪歌席，須容散道場。","月終齋戒畢，猶及菊花黃。"]', '["煙景冷蒼茫，秋深夜夜霜。","爲思池上酌，先覺甕头香。","未暇傾巾漉，還應染指嘗。","醍醐慙氣味，琥珀讓晶光。","若許陪歌席，須容散道場。","月終斋戒畢，猶及菊花黄。"]', '诗', 'shi', '', NULL, '荅皇甫十郎中秋深酒熟見憶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10041b70-4ba3-4e72-80b5-18902f69bbfe', '老去', '老去', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老去媿妻兒，冬來有勸詞。","煖寒從飲酒，衝冷少吟詩。","戰勝心還壯，齋勤體校羸。","由來世間法，損益合相隨。"]', '["老去媿妻兒，冬来有勸词。","煖寒從饮酒，衝冷少吟诗。","戰勝心還壯，斋勤體校羸。","由来世间法，損益合相隨。"]', '诗', 'shi', '', NULL, '老去 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2ca4c0-f171-462a-8c54-8c8fbe0e6212', '送宗實上人遊江南', '送宗實上人游江南', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["忽辭洛下緣何事，擬向江南住幾時。","每過渡頭應問法，無妨菩薩是船師。"]', '["忽辞洛下緣何事，擬向江南住幾时。","每過渡头應问法，無妨菩薩是船師。"]', '诗', 'shi', '', NULL, '送宗實上人遊江南 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e6fad8f-4c48-46ad-ba13-b714aa6de458', '和同州楊侍郎誇柘枝見寄', '和同州楊侍郎誇柘枝见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["細吟馮翊使君詩，憶作餘杭太守時。","君有一般輸我事，柘枝看校十年遲。"]', '["細吟馮翊使君诗，憶作餘杭太守时。","君有一般輸我事，柘枝看校十年遲。"]', '诗', 'shi', '', NULL, '和同州楊侍郎誇柘枝見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2c80390-e330-46f5-ba9d-7abdd936d2d7', '冬初酒熟二首 一', '冬初酒熟二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜繁脆庭柳，風利剪池荷。","月色曉彌苦，鳥聲寒更多。","秋懷久寥落，冬計又如何。","一甕新醅酒，萍浮春水波。"]', '["霜繁脆庭柳，风利剪池荷。","月色晓彌苦，鸟声寒更多。","秋懷久寥落，冬計又如何。","一甕新醅酒，萍浮春水波。"]', '诗', 'shi', '', NULL, '冬初酒熟二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('02995350-424f-4e4b-ba6d-caa33f31f35e', '冬初酒熟二首 二', '冬初酒熟二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["酒熟無客來，因成獨酌謠。","人間老黃綺，地上散松喬。","忽忽醒還醉，悠悠暮復朝。","殘年多少在，盡付此中銷。"]', '["酒熟無客来，因成独酌謠。","人间老黄綺，地上散松喬。","忽忽醒還醉，悠悠暮复朝。","殘年多少在，尽付此中銷。"]', '诗', 'shi', '', NULL, '冬初酒熟二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('817643e5-6280-4dd3-91fd-b9f3754ba08f', '送姚杭州赴任因思舊遊二首 一', '送姚杭州赴任因思旧游二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與君細話杭州事，爲我留心莫等閑。","閭里固宜勤撫恤，樓臺亦要數躋攀。","笙歌縹緲虛空裏，風月依稀夢想間。","且喜詩人重管領，遙飛一醆賀江山。"]', '["與君細話杭州事，爲我留心莫等闲。","閭里固宜勤撫恤，楼台亦要數躋攀。","笙歌縹緲虛空裏，风月依稀梦想间。","且喜诗人重管領，遙飞一醆賀江山。"]', '诗', 'shi', '', NULL, '送姚杭州赴任因思舊遊二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ebc364-36ae-466d-a19e-b2d0d443cf32', '送姚杭州赴任因思舊遊二首 二', '送姚杭州赴任因思旧游二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["渺渺錢唐路幾千，想君到後事依然。","靜逢竺寺猨偷橘，閑看蘇家女採蓮。","故妓數人憑問詢，新詩兩首倩留傳。","舍人雖健無多興，老挍當時八九年。"]', '["渺渺錢唐路幾千，想君到後事依然。","静逢竺寺猨偷橘，闲看蘇家女採蓮。","故妓數人憑问詢，新诗兩首倩留傳。","舍人雖健無多兴，老挍當时八九年。"]', '诗', 'shi', '', NULL, '送姚杭州赴任因思舊遊二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b59cd4b-3572-4072-8777-1c1a47c2c023', '寄李相公', '寄李相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漸老只謀歡，雖貧不要官。","唯求造化力，試爲駐春看。"]', '["漸老只謀歡，雖貧不要官。","唯求造化力，試爲駐春看。"]', '诗', 'shi', '', NULL, '寄李相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f03297e4-dd0e-4670-821d-f0ca9b131bf6', '冬日平泉路晚歸', '冬日平泉路晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山路難行日易斜，煙村霜樹欲棲鵶。","夜歸不到應閑事，熱飲三杯即是家。"]', '["山路难行日易斜，煙村霜樹欲棲鵶。","夜归不到應闲事，熱饮三杯即是家。"]', '诗', 'shi', '', NULL, '冬日平泉路晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1618aa3c-ba65-42bf-bf15-f2dc0bd4e3be', '利仁北街作', '利仁北街作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["草色斑斑春雨晴，利仁坊北面西行。","踟躕立馬緣何事，認得張家歌吹聲。"]', '["草色斑斑春雨晴，利仁坊北面西行。","踟躕立马緣何事，認得張家歌吹声。"]', '诗', 'shi', '', NULL, '利仁北街作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de50d4b3-e65f-46d6-95ee-66b91218ba38', '洛陽堰閑行', '洛陽堰闲行', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛陽堰上新晴日，長夏門前欲暮春。","遇酒即沽逢樹歇，七年此地作閑人。"]', '["洛陽堰上新晴日，长夏门前欲暮春。","遇酒即沽逢樹歇，七年此地作闲人。"]', '诗', 'shi', '', NULL, '洛陽堰閑行 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0f20c58f-34fd-4d11-8077-1dd67371f5f1', '過永寧', '過永寧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["村杏野桃繁似雪，行人不醉爲誰開。","賴逢山縣盧明府，引我花前勸一杯。"]', '["村杏野桃繁似雪，行人不醉爲誰开。","賴逢山縣盧明府，引我花前勸一杯。"]', '诗', 'shi', '', NULL, '過永寧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('17236446-0d47-4960-b480-d0102ae38c27', '往年稠桑曾喪白馬題詩廳壁今來尚存又復感懷更題絕句', '往年稠桑曾喪白马題诗廳壁今来尚存又复感懷更題絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["路傍埋骨蒿草合，壁上題詩塵蘚生。","馬死七年猶悵望，自知無乃太多情。"]', '["路傍埋骨蒿草合，壁上題诗塵蘚生。","马死七年猶悵望，自知無乃太多情。"]', '诗', 'shi', '', NULL, '往年稠桑曾喪白馬題詩廳壁今來尚存又復感懷更題絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8acfd47-6c2f-43f3-becb-7808bf2664fd', '羅敷水', '羅敷水', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野店東頭花落處，一條流水號羅敷。","芳魂豔骨知何處，春草茫茫墓亦無。"]', '["野店东头花落处，一條流水號羅敷。","芳魂豔骨知何处，春草茫茫墓亦無。"]', '诗', 'shi', '', NULL, '羅敷水 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e0c7c1b-c750-45d5-858a-1110af4c9486', '路逢青州王大夫赴鎮立馬贈別', '路逢青州王大夫赴鎮立马贈別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["大斾擁金羈，書生得者稀。","何勞問官職，豈不見光輝。","赫赫人爭看，翩翩馬欲飛。","不期前歲尹，駐節語依依。"]', '["大斾擁金羈，书生得者稀。","何勞问官職，豈不见光輝。","赫赫人爭看，翩翩马欲飞。","不期前歲尹，駐節語依依。"]', '诗', 'shi', '', NULL, '路逢青州王大夫赴鎮立馬贈別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b77fec-16af-43d7-a06b-19bcbcc17d93', '和楊同州寒食乾坑會後聞楊工部欲到知予與工部有宿酲', '和楊同州寒食乾坑會後闻楊工部欲到知予與工部有宿酲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜飲歸常晚，朝眠起更遲。","舉頭中酒後，引手索茶時。","拂枕青長袖，欹簪白接䍦。","宿酲無興味，先是肺神知。"]', '["夜饮归常晚，朝眠起更遲。","舉头中酒後，引手索茶时。","拂枕青长袖，欹簪白接䍦。","宿酲無兴味，先是肺神知。"]', '诗', 'shi', '', NULL, '和楊同州寒食乾坑會後聞楊工部欲到知予與工部有宿酲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('458b9118-24ec-4746-9920-1ad8adc5cb1d', '和劉汝州酬侍中見寄長句因書集賢坊勝事戲而問之', '和劉汝州酬侍中见寄长句因书集賢坊勝事戲而问之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛川汝海封畿接，履道集賢來往頻。","一復時程雖不遠，百餘步地更相親。","朱門陪宴多投轄，青眼留歡任吐茵。","聞道郡齋還有酒，花前月下對何人。"]', '["洛川汝海封畿接，履道集賢来往頻。","一复时程雖不远，百餘步地更相親。","朱门陪宴多投轄，青眼留歡任吐茵。","闻道郡斋還有酒，花前月下对何人。"]', '诗', 'shi', '', NULL, '和劉汝州酬侍中見寄長句因書集賢坊勝事戲而問之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b020381-c590-4afd-b04c-460c3144b783', '池上二絕 一', '池上二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山僧對棊坐，局上竹陰清。","映竹無人見，時聞下子聲。"]', '["山僧对棊坐，局上竹陰清。","映竹無人见，时闻下子声。"]', '诗', 'shi', '', NULL, '池上二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bcc5f16-f5f4-4a49-bce5-f26630de8c4d', '池上二絕 二', '池上二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小娃撐小艇，偷採白蓮迴。","不解藏踪跡，浮萍一道開。"]', '["小娃撐小艇，偷採白蓮迴。","不解藏踪跡，浮萍一道开。"]', '诗', 'shi', '', NULL, '池上二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e36f65b2-4927-4499-830f-233135ce9b5d', '白羽扇', '白羽扇', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["素是自然色，圓因裁製功。","颯如松起籟，飄似鶴翻空。","盛夏不銷雪，終年無盡風。","引秋生手裏，藏月入懷中。","麈尾斑非疋，蒲葵陋不同。","何人稱相對，清瘦白鬚翁。"]', '["素是自然色，圓因裁製功。","颯如松起籟，飄似鹤翻空。","盛夏不銷雪，終年無尽风。","引秋生手裏，藏月入懷中。","麈尾斑非疋，蒲葵陋不同。","何人稱相对，清瘦白鬚翁。"]', '诗', 'shi', '', NULL, '白羽扇 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d296a69-3ba9-40b7-8dfa-bff460c114c5', '五月齋戒罷宴徹樂聞韋賓客皇甫郎中飲會亦稀又知欲攜酒饌出齋先以長句呈謝', '五月斋戒罷宴徹乐闻韋賓客皇甫郎中饮會亦稀又知欲携酒饌出斋先以长句呈謝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["妓房匣鏡滿紅埃，酒庫封瓶生綠苔。","居士爾時緣護戒，車公何事亦停杯。","散齋香火今朝散，開素盤筵後日開。","隨意往還君莫怪，坐禪僧去飲徒來。"]', '["妓房匣镜满紅埃，酒庫封瓶生綠苔。","居士爾时緣護戒，车公何事亦停杯。","散斋香火今朝散，开素盤筵後日开。","隨意往還君莫怪，坐禪僧去饮徒来。"]', '诗', 'shi', '', NULL, '五月齋戒罷宴徹樂聞韋賓客皇甫郎中飲會亦稀又知欲攜酒饌出齋先以長句呈謝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81d91d07-a8b2-4bf0-8ee1-3f2abbce7715', '閑園獨賞', '闲园独賞', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["午後郊園靜，晴來景物新。","雨添山氣色，風借水精神。","永日若爲度，獨遊何所親。","仙禽狎君子，芳樹倚佳人。","蟻鬬王爭肉，蝸移舍逐身。","蝶雙知伉儷，蜂分見君臣。","蠢蠕形雖小，逍遙性即均。","不知鵬與鷃，相去幾微塵。"]', '["午後郊园静，晴来景物新。","雨添山氣色，风借水精神。","永日若爲度，独游何所親。","仙禽狎君子，芳樹倚佳人。","蟻鬬王爭肉，蝸移舍逐身。","蝶雙知伉儷，蜂分见君臣。","蠢蠕形雖小，逍遙性即均。","不知鵬與鷃，相去幾微塵。"]', '诗', 'shi', '', NULL, '閑園獨賞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e84630c7-371c-4204-9f1e-4d93c7889f9e', '種柳三詠 一', '種柳三詠 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白頭種松桂，早晚見成林。","不及栽楊柳，明年便有陰。","春風爲催促，副取老人心。"]', '["白头種松桂，早晚见成林。","不及栽楊柳，明年便有陰。","春风爲催促，副取老人心。"]', '诗', 'shi', '', NULL, '種柳三詠 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62631936-3402-4661-8bca-9b5eceb5ffe4', '種柳三詠 二', '種柳三詠 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["從君種楊柳，夾水意如何。","準擬三年後，青絲拂綠波。","仍教小樓上，對唱柳枝歌。"]', '["從君種楊柳，夾水意如何。","準擬三年後，青絲拂綠波。","仍教小楼上，对唱柳枝歌。"]', '诗', 'shi', '', NULL, '種柳三詠 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5b8f11c-2ed3-4ad7-b2e0-7040166204e0', '種柳三詠 三', '種柳三詠 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["更想五年後，千千條麴塵。","路傍深映月，樓上闇藏春。","愁殺閑遊客，聞歌不見人。"]', '["更想五年後，千千條麴塵。","路傍深映月，楼上闇藏春。","愁殺闲游客，闻歌不见人。"]', '诗', 'shi', '', NULL, '種柳三詠 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4121f030-9f08-4f25-bfad-75391bc37196', '偶吟', '偶吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["好官病免曾三度，散地歸休已七年。","老自退閑非世棄，貧蒙強健是天憐。","韋荆南去留春服，王侍中來乞酒錢。","便得一年生計足，與君美食復甘眠。"]', '["好官病免曾三度，散地归休已七年。","老自退闲非世棄，貧蒙強健是天怜。","韋荆南去留春服，王侍中来乞酒錢。","便得一年生計足，與君美食复甘眠。"]', '诗', 'shi', '', NULL, '偶吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3a12b58-7384-49fd-891f-1d9df1828051', '池上即事', '池上即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["移牀避日依松竹，解帶當風挂薜蘿。","鈿砌池心綠蘋合，粉開花面白蓮多。","久陰新霽宜絲管，苦熱初涼入綺羅。","家醞瓶空人客絕，今宵爭奈月明何。"]', '["移牀避日依松竹，解带當风挂薜蘿。","鈿砌池心綠蘋合，粉开花面白蓮多。","久陰新霽宜絲管，苦熱初涼入綺羅。","家醞瓶空人客絕，今宵爭奈月明何。"]', '诗', 'shi', '', NULL, '池上即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7750e8b0-7892-416b-bc70-a2274b9edf6b', '南塘暝興', '南塘暝兴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水色昏猶白，霞光闇漸無。","風荷搖破扇，波月動連珠。","蟋蟀啼相應，鴛鴦宿不孤。","小僮頻報夜，歸步尚踟躕。"]', '["水色昏猶白，霞光闇漸無。","风荷搖破扇，波月动連珠。","蟋蟀啼相應，鴛鴦宿不孤。","小僮頻報夜，归步尚踟躕。"]', '诗', 'shi', '', NULL, '南塘暝興 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a387188-018f-4cc1-8351-88120e851628', '小宅', '小宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小宅里閭接，疎籬雞犬通。","渠分南巷水，窗借北家風。","庾信園殊小，陶潛屋不豐。","何勞問寬窄，寬窄在心中。"]', '["小宅里閭接，疎籬雞犬通。","渠分南巷水，窗借北家风。","庾信园殊小，陶潛屋不豐。","何勞问寬窄，寬窄在心中。"]', '诗', 'shi', '', NULL, '小宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da143c23-40dd-4b8a-8437-76f31b38060c', '諭親友', '諭親友', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["適情處處皆安樂，大抵園林勝市朝。","煩鬧榮華猶易過，優閑福祿更難銷。","自憐老大宜疎散，却被交親歎寂寥。","終日相逢不相見，兩心相去一何遙。"]', '["適情处处皆安乐，大抵园林勝市朝。","煩鬧榮华猶易過，優闲福祿更难銷。","自怜老大宜疎散，却被交親歎寂寥。","終日相逢不相见，兩心相去一何遙。"]', '诗', 'shi', '', NULL, '諭親友 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65d32d60-871d-4b8d-9c85-1393eb8ef828', '龍門送別皇甫澤州赴任韋山人南遊', '龙门送別皇甫澤州赴任韋山人南游', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隼旟歸洛知何日，鶴駕還嵩莫過春。","惆悵香山雲水冷，明朝便是獨遊人。"]', '["隼旟归洛知何日，鹤駕還嵩莫過春。","惆悵香山云水冷，明朝便是独游人。"]', '诗', 'shi', '', NULL, '龍門送別皇甫澤州赴任韋山人南遊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f72d578e-203f-4d1a-9203-2e1e81dc7df5', '劉蘇州寄釀酒糯米李浙東寄楊柳枝舞衫偶因嘗酒試衫輙成長句寄謝之', '劉蘇州寄釀酒糯米李浙东寄楊柳枝舞衫偶因嘗酒試衫輙成长句寄謝之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳枝謾蹋試雙袖，桑落初香嘗一杯。","金屑醅濃吳米釀，銀泥衫穩越娃裁。","舞時已覺愁眉展，醉後仍教笑口開。","慙媿故人憐寂寞，三千里外寄歡來。"]', '["柳枝謾蹋試雙袖，桑落初香嘗一杯。","金屑醅濃吳米釀，銀泥衫穩越娃裁。","舞时已覺愁眉展，醉後仍教笑口开。","慙媿故人怜寂寞，三千里外寄歡来。"]', '诗', 'shi', '', NULL, '劉蘇州寄釀酒糯米李浙東寄楊柳枝舞衫偶因嘗酒試衫輙成長句寄謝之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd86f5e0-895f-4267-bf91-d62afe1c801d', '詔授同州刺史病不赴任因詠所懷', '詔授同州刺史病不赴任因詠所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["同州慵不去，此意復誰知。","誠愛俸錢厚，其如身力衰。","可憐病判案，何似醉吟詩。","勞逸懸相遠，行藏決不疑。","徒煩人勸諫，只合自尋思。","白髮來無限，青山去有期。","野心惟怕鬧，家口莫愁飢。","賣却新昌宅，聊充送老資。"]', '["同州慵不去，此意复誰知。","誠愛俸錢厚，其如身力衰。","可怜病判案，何似醉吟诗。","勞逸懸相远，行藏決不疑。","徒煩人勸諫，只合自尋思。","白髮来無限，青山去有期。","野心惟怕鬧，家口莫愁飢。","賣却新昌宅，聊充送老資。"]', '诗', 'shi', '', NULL, '詔授同州刺史病不赴任因詠所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01de01c2-2f5a-4ba3-a6f7-e896c00a3ee3', '寄楊六侍郎', '寄楊六侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["西戶最榮君好去，左馮雖穩我慵來。","秋風一筯鱸魚鱠，張翰搖頭喚不迴。"]', '["西戶最榮君好去，左馮雖穩我慵来。","秋风一筯鱸鱼鱠，張翰搖头喚不迴。"]', '诗', 'shi', '', NULL, '寄楊六侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3351351-5e4a-4297-8b8c-77ca44b43ef9', '韋七自太子賓客再除祕書監以長句賀而餞之', '韋七自太子賓客再除祕书監以长句賀而餞之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["離筵莫愴且同歡，共賀新恩拜舊官。","屈就商山伴麋鹿，好歸芸閣狎鵷鸞。","落星石上蒼苔古，畫鶴廳前白露寒。","老監姓名應在壁，相思試爲拂塵看。"]', '["離筵莫愴且同歡，共賀新恩拜旧官。","屈就商山伴麋鹿，好归芸閣狎鵷鸾。","落星石上蒼苔古，畫鹤廳前白露寒。","老監姓名應在壁，相思試爲拂塵看。"]', '诗', 'shi', '', NULL, '韋七自太子賓客再除祕書監以長句賀而餞之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a831a988-8bb2-4882-a0f4-f865e6b3a5f6', '酒熟憶皇甫十', '酒熟憶皇甫十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新酒此時熟，故人何日來。","自從金谷別，不見玉山頹。","疎索柳花盌，寂寥荷葉杯。","今冬問氈帳，雪裏爲誰開。"]', '["新酒此时熟，故人何日来。","自從金谷別，不见玉山頹。","疎索柳花盌，寂寥荷葉杯。","今冬问氈帳，雪裏爲誰开。"]', '诗', 'shi', '', NULL, '酒熟憶皇甫十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d9e8d1-fff1-4a66-819c-31f81001fa22', '九年十一月二十一日感事而作', '九年十一月二十一日感事而作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["禍福茫茫不可期，大都早退似先知。","當君白首同歸日，是我青山獨往時。","顧索素琴應不暇，憶牽黃犬定難追。","麒麟作脯龍爲醢，何似泥中曳尾龜。"]', '["禍福茫茫不可期，大都早退似先知。","當君白首同归日，是我青山独往时。","顧索素琴應不暇，憶牽黄犬定难追。","麒麟作脯龙爲醢，何似泥中曳尾龟。"]', '诗', 'shi', '', NULL, '九年十一月二十一日感事而作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd786e91-4408-40e9-a198-1d21a4178fe8', '即事重題', '即事重題', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["重裘暖帽寬氈履，小閣低窗深地爐。","身穩心安眠未起，西京朝士得知無。"]', '["重裘暖帽寬氈履，小閣低窗深地爐。","身穩心安眠未起，西京朝士得知無。"]', '诗', 'shi', '', NULL, '即事重題 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b84e6b34-edd5-43c9-8f48-77855d0b071c', '將歸渭村先寄舍弟', '將归渭村先寄舍弟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一年年覺此身衰，一日日知前事非。","詠月嘲風先要減，登山臨水亦宜稀。","子平嫁娶貧中畢，元亮田園醉裏歸。","爲報阿連寒食下，與吾釀酒掃柴扉。"]', '["一年年覺此身衰，一日日知前事非。","詠月嘲风先要減，登山臨水亦宜稀。","子平嫁娶貧中畢，元亮田园醉裏归。","爲報阿連寒食下，與吾釀酒掃柴扉。"]', '诗', 'shi', '', NULL, '將歸渭村先寄舍弟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('faa6013b-5c49-4096-afab-4d9d4358b7a6', '看嵩洛有歎', '看嵩洛有歎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今日看嵩洛，迴頭歎世間。","榮華急如水，憂患大於山。","見苦方知樂，經忙始愛閑。","未聞籠裏鳥，飛出肯飛還。"]', '["今日看嵩洛，迴头歎世间。","榮华急如水，憂患大於山。","见苦方知乐，經忙始愛闲。","未闻籠裏鸟，飞出肯飞還。"]', '诗', 'shi', '', NULL, '看嵩洛有歎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff69fcd3-3ed0-4edb-883c-f0c5bd1e59f8', '詠懷', '詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["隨緣逐處便安閑，不入朝廷不住山。","心似虛舟浮水上，身同宿鳥寄林間。","尚平婚嫁了無累，馮翊符章封却還。","處分貧家殘活計，匹如身後莫相關。"]', '["隨緣逐处便安闲，不入朝廷不住山。","心似虛舟浮水上，身同宿鸟寄林间。","尚平婚嫁了無累，馮翊符章封却還。","处分貧家殘活計，匹如身後莫相关。"]', '诗', 'shi', '', NULL, '詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f2e0fec-11ce-41dd-bec4-62fde7499912', '詠老贈夢得', '詠老贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["與君俱老也，自問老何如。","眼澀夜先臥，頭慵朝未梳。","有時扶杖出，盡日閉門居。","嬾照新磨鏡，休看小字書。","情於故人重，迹共少年疎。","唯是閑談興，相逢尚有餘。"]', '["與君俱老也，自问老何如。","眼澀夜先臥，头慵朝未梳。","有时扶杖出，尽日閉门居。","嬾照新磨镜，休看小字书。","情於故人重，迹共少年疎。","唯是闲談兴，相逢尚有餘。"]', '诗', 'shi', '', NULL, '詠老贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18edec5f-06df-4bd0-9291-f3eb09fc93c5', '從同州刺史改授太子少傅分司', '從同州刺史改授太子少傅分司', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["承華東署三分務，履道西池七過春。","歌酒優游聊卒歲，園林蕭灑可終身。","留侯爵秩誠虛貴，疏受生涯未苦貧。","月俸百千官二品，朝廷雇我作閑人。"]', '["承华东署三分務，履道西池七過春。","歌酒優游聊卒歲，园林蕭灑可終身。","留侯爵秩誠虛貴，疏受生涯未苦貧。","月俸百千官二品，朝廷雇我作闲人。"]', '诗', 'shi', '', NULL, '從同州刺史改授太子少傅分司 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9a9bf4b-fba8-424b-b81c-309bcdade7aa', '奉和裴令公新成午橋莊綠野堂即事', '奉和裴令公新成午橋莊綠野堂即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舊徑開桃李，新池鑿鳳皇。","只添丞相閣，不改午橋莊。","遠處塵埃少，閑中日月長。","青山爲外屏，綠野是前堂。","引水多隨勢，栽松不趂行。","年華玩風景，春事看農桑。","花妬謝家妓，蘭偷荀令香。","遊絲飄酒席，瀑布濺琴牀。","巢許終身穩，蕭曹到老忙。","千年落公便，進退處中央。"]', '["旧徑开桃李，新池鑿鳳皇。","只添丞相閣，不改午橋莊。","远处塵埃少，闲中日月长。","青山爲外屏，綠野是前堂。","引水多隨勢，栽松不趂行。","年华玩风景，春事看農桑。","花妬謝家妓，蘭偷荀令香。","游絲飄酒席，瀑布濺琴牀。","巢許終身穩，蕭曹到老忙。","千年落公便，進退处中央。"]', '诗', 'shi', '', NULL, '奉和裴令公新成午橋莊綠野堂即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f5b4350-b3a6-488f-a965-62f74b8eac46', '自題小草亭', '自題小草亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新結一茅茨，規模儉且卑。","土堦全壘塊，山木半留皮。","陰合連藤架，藂香近菊籬。","壁宜藜杖倚，門稱荻簾垂。","窗裏風清夜，簷間月好時。","留連嘗酒客，句引坐禪師。","伴宿雙棲鶴，扶行一侍兒。","綠醅量醆飲，紅稻約升炊。","齷齪豪家笑，酸寒富室欺。","陶廬閑自愛，顏巷陋誰知。","螻蟻謀深穴，鷦鷯占小枝。","各隨其分足，焉用有餘爲。"]', '["新結一茅茨，規模儉且卑。","土堦全壘塊，山木半留皮。","陰合連藤架，藂香近菊籬。","壁宜藜杖倚，门稱荻簾垂。","窗裏风清夜，簷间月好时。","留連嘗酒客，句引坐禪師。","伴宿雙棲鹤，扶行一侍兒。","綠醅量醆饮，紅稻約升炊。","齷齪豪家笑，酸寒富室欺。","陶廬闲自愛，顏巷陋誰知。","螻蟻謀深穴，鷦鷯占小枝。","各隨其分足，焉用有餘爲。"]', '诗', 'shi', '', NULL, '自題小草亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91534793-58e2-4007-a6fd-0278574c7afb', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["細故隨緣盡，衰形具體微。","鬬閑僧尚鬧，較瘦鶴猶肥。","老遣寬裁襪，寒教厚絮衣。","馬從銜草展，雞任啄籠飛。","只要天和在，無令物性違。","自餘君莫問，何是復何非。"]', '["細故隨緣尽，衰形具體微。","鬬闲僧尚鬧，較瘦鹤猶肥。","老遣寬裁襪，寒教厚絮衣。","马從銜草展，雞任啄籠飞。","只要天和在，無令物性違。","自餘君莫问，何是复何非。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10215099-eae8-4f49-ab1e-9234041d9ebb', '新亭病後獨坐招李侍郎公垂', '新亭病後独坐招李侍郎公垂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新亭未有客，景日獨何爲。","趂暖泥茶竈，防寒夾竹籬。","頭風初定後，眼闇欲明時。","淺把三分酒，閑題數句詩。","應須置兩榻，一榻待公垂。"]', '["新亭未有客，景日独何爲。","趂暖泥茶竈，防寒夾竹籬。","头风初定後，眼闇欲明时。","淺把三分酒，闲題數句诗。","應須置兩榻，一榻待公垂。"]', '诗', 'shi', '', NULL, '新亭病後獨坐招李侍郎公垂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a0d4a9b1-1a35-4eb8-8b8b-5b8913ecf9e8', '閑臥寄劉同州', '闲臥寄劉同州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["軟褥短屏風，昏昏醉臥翁。","鼻香茶熟後，腰暖日陽中。","伴老琴長在，迎春酒不空。","可憐閑氣味，唯欠與君同。"]', '["軟褥短屏风，昏昏醉臥翁。","鼻香茶熟後，腰暖日陽中。","伴老琴长在，迎春酒不空。","可怜闲氣味，唯欠與君同。"]', '诗', 'shi', '', NULL, '閑臥寄劉同州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f1532d0e-df2b-47ff-9a54-3a8a6f43840b', '殘酌晚餐', '殘酌晚餐', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑傾殘酒後，煖擁小爐時。","舞看新翻曲，歌聽自作詞。","魚香肥潑火，飯細滑流匙。","除却慵饞外，其餘盡不知。"]', '["闲傾殘酒後，煖擁小爐时。","舞看新翻曲，歌听自作词。","鱼香肥潑火，飯細滑流匙。","除却慵饞外，其餘尽不知。"]', '诗', 'shi', '', NULL, '殘酌晚餐 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a65f36-c17c-4737-8706-fd941ac48535', '喜見劉同州夢得', '喜见劉同州梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紫綬白髭鬚，同年二老夫。","論心共牢落，見面且歡娛。","酒好攜來否，詩多記得無。","應須爲春草，五馬少踟躕。"]', '["紫綬白髭鬚，同年二老夫。","論心共牢落，见面且歡娛。","酒好携来否，诗多記得無。","應須爲春草，五马少踟躕。"]', '诗', 'shi', '', NULL, '喜見劉同州夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79de982b-0c9e-400c-8c5d-3cb7874a202d', '裴令公席上贈別夢得', '裴令公席上贈別梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年老官高多別離，轉難相見轉相思。","雪銷酒盡梁王起，便是鄒枚分散時。"]', '["年老官高多別離，轉难相见轉相思。","雪銷酒尽梁王起，便是鄒枚分散时。"]', '诗', 'shi', '', NULL, '裴令公席上贈別夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0915c42f-c0c2-4af1-bdcd-3f023f4e9929', '尋春題諸家園林', '尋春題諸家园林', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["聞健朝朝出，乘春處處尋。","天供閑日月，人借好園林。","漸以狂爲態，都無悶到心。","平生身得所，未省似而今。"]', '["闻健朝朝出，乘春处处尋。","天供闲日月，人借好园林。","漸以狂爲態，都無悶到心。","平生身得所，未省似而今。"]', '诗', 'shi', '', NULL, '尋春題諸家園林 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26029c03-139b-4250-8550-e77d70b14489', '又題一絕', '又題一絕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["貌隨年老欲何如，興遇春牽尚有餘。","遙見人家花便入，不論貴賤與親疎。"]', '["貌隨年老欲何如，兴遇春牽尚有餘。","遙见人家花便入，不論貴賤與親疎。"]', '诗', 'shi', '', NULL, '又題一絕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd37a863-b39c-4cb1-bb44-3aaf15c64680', '家園三絕 一', '家园三絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["滄浪峽水子陵灘，路遠江深欲去難。","何似家池通小院，臥房階下插魚竿。"]', '["滄浪峽水子陵灘，路远江深欲去难。","何似家池通小院，臥房階下插鱼竿。"]', '诗', 'shi', '', NULL, '家園三絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28ab6978-5543-4bfa-967e-8abc75a00bbc', '家園三絕 二', '家园三絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籬下先生時得醉，甕間吏部暫偷閑。","何如家醞雙魚榼，雪夜花時長在前。"]', '["籬下先生时得醉，甕间吏部暫偷闲。","何如家醞雙鱼榼，雪夜花时长在前。"]', '诗', 'shi', '', NULL, '家園三絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7618a91b-a9b6-444d-8575-61fd84f81afe', '家園三絕 三', '家园三絕 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鴛鴦怕捉竟難親，鸚鵡雖籠不著人。","何似家禽雙白鶴，閑行一步亦隨身。"]', '["鴛鴦怕捉竟难親，鸚鵡雖籠不著人。","何似家禽雙白鹤，闲行一步亦隨身。"]', '诗', 'shi', '', NULL, '家園三絕 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc616b8b-4fed-45e2-a8ad-a324bb938038', '老來生計', '老来生計', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老來生計君看取，白日遊行夜醉吟。","陶令有田唯種黍，鄧家無子不留金。","人間榮耀因緣淺，林下幽閑氣味深。","煩慮漸消虛白長，一年心勝一年心。"]', '["老来生計君看取，白日游行夜醉吟。","陶令有田唯種黍，鄧家無子不留金。","人间榮耀因緣淺，林下幽闲氣味深。","煩慮漸消虛白长，一年心勝一年心。"]', '诗', 'shi', '', NULL, '老來生計 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ab8e98e-8c22-4a5a-b903-6b32212b0206', '早春題少室東巖', '早春題少室东巖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三十六峰晴，雪銷嵐翠生。","月留三夜宿，春引四山行。","遠草初含色，寒禽未變聲。","東巖最高石，唯我有題名。"]', '["三十六峰晴，雪銷嵐翠生。","月留三夜宿，春引四山行。","远草初含色，寒禽未变声。","东巖最高石，唯我有題名。"]', '诗', 'shi', '', NULL, '早春題少室東巖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c132e3f-3b9a-45f8-9149-2c885c72b93f', '早春即事', '早春即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["眼重朝眠足，頭輕宿酒醒。","陽光滿前戶，雪水半中庭。","物變隨天氣，春生逐地形。","北簷梅晚白，東岸柳先青。","葱壠抽羊角，松巢墮鶴翎。","老來詩更拙，吟罷少人聽。"]', '["眼重朝眠足，头轻宿酒醒。","陽光满前戶，雪水半中庭。","物变隨天氣，春生逐地形。","北簷梅晚白，东岸柳先青。","葱壠抽羊角，松巢墮鹤翎。","老来诗更拙，吟罷少人听。"]', '诗', 'shi', '', NULL, '早春即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4d58623-baf8-4736-a2eb-06b77122e969', '歎春風兼贈李二十侍郎二絕 一', '歎春风兼贈李二十侍郎二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["樹根雪盡催花發，池岸冰消放草生。","唯有鬚霜依舊白，春風於我獨無情。"]', '["樹根雪尽催花發，池岸冰消放草生。","唯有鬚霜依旧白，春风於我独無情。"]', '诗', 'shi', '', NULL, '歎春風兼贈李二十侍郎二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53d04ab4-500a-4eee-9ca3-973787774f29', '歎春風兼贈李二十侍郎二絕 二', '歎春风兼贈李二十侍郎二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["道場齋戒今初畢，酒伴歡娛久不同。","不把一杯來勸我，無情亦得似春風。"]', '["道場斋戒今初畢，酒伴歡娛久不同。","不把一杯来勸我，無情亦得似春风。"]', '诗', 'shi', '', NULL, '歎春風兼贈李二十侍郎二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1363cce8-7648-4f35-b740-cae029b08558', '春來頻與李二賓客郭外同遊因贈長句', '春来頻與李二賓客郭外同游因贈长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風光引步酒開顏，送老消春嵩洛間。","朝蹋落花相伴出，暮隨飛鳥一時還。","我爲病叟誠宜退，君是才臣豈合閑。","可惜濟時心力在，放教臨水復登山。"]', '["风光引步酒开顏，送老消春嵩洛间。","朝蹋落花相伴出，暮隨飞鸟一时還。","我爲病叟誠宜退，君是才臣豈合闲。","可惜濟时心力在，放教臨水复登山。"]', '诗', 'shi', '', NULL, '春來頻與李二賓客郭外同遊因贈長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5788d6d0-ce3b-4b9d-86be-b18db8680405', '二月二日', '二月二日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["二月二日新雨晴，草芽菜甲一時生。","輕衫細馬春年少，十字津頭一字行。"]', '["二月二日新雨晴，草芽菜甲一时生。","轻衫細马春年少，十字津头一字行。"]', '诗', 'shi', '', NULL, '二月二日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3315eb0b-1f7b-4ab3-a68e-5d2941c4413d', '奉和令公綠野堂種花', '奉和令公綠野堂種花', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["綠野堂開占物華，路人指道令公家。","令公桃李滿天下，何用堂前更種花。"]', '["綠野堂开占物华，路人指道令公家。","令公桃李满天下，何用堂前更種花。"]', '诗', 'shi', '', NULL, '奉和令公綠野堂種花 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90461bfa-5f84-49c0-bb30-d3fe60b62ccf', '清明日登老君閣望洛城贈韓道士', '清明日登老君閣望洛城贈韓道士', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風光煙火清明日，歌哭悲歡城市間。","何事不隨東洛水，誰家又葬北邙山。","中橋車馬長無已，下渡舟航亦不閑。","冢墓纍纍人擾擾，遼東悵望鶴飛還。"]', '["风光煙火清明日，歌哭悲歡城市间。","何事不隨东洛水，誰家又葬北邙山。","中橋车马长無已，下渡舟航亦不闲。","冢墓纍纍人擾擾，遼东悵望鹤飞還。"]', '诗', 'shi', '', NULL, '清明日登老君閣望洛城贈韓道士 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98f439ef-d136-4aa1-8881-c04dffb03f10', '三月三日', '三月三日', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["畫堂三月初三日，絮撲窗紗燕拂簷。","蓮子數杯嘗冷酒，柘枝一曲試春衫。","階臨池面勝看鏡，戶映花藂當下簾。","指點樓南玩新月，玉鉤素手兩纖纖。"]', '["畫堂三月初三日，絮撲窗紗燕拂簷。","蓮子數杯嘗冷酒，柘枝一曲試春衫。","階臨池面勝看镜，戶映花藂當下簾。","指点楼南玩新月，玉鉤素手兩纖纖。"]', '诗', 'shi', '', NULL, '三月三日 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49675740-13db-4c61-b7ca-32329eb90265', '雨中聽琴者彈別鶴操', '雨中听琴者彈別鹤操', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雙鶴分離一何苦，連陰雨夜不堪聞。","莫教遷客孀妻聽，嗟歎悲啼䛏殺君。"]', '["雙鹤分離一何苦，連陰雨夜不堪闻。","莫教遷客孀妻听，嗟歎悲啼䛏殺君。"]', '诗', 'shi', '', NULL, '雨中聽琴者彈別鶴操 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30529770-c2d9-481b-a121-ad756b2cd30a', '酬鄭二司錄與李六郎中寒食日相過同宴見贈', '酬鄭二司錄與李六郎中寒食日相過同宴见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["偶因冷節會嘉賓，況是平生心所親。","迎接須衿疏傅老，祗供莫笑阮家貧。","杯盤狼籍宜侵夜，風景闌珊欲過春。","相對喜歡還悵望，同年只有此三人。"]', '["偶因冷節會嘉賓，況是平生心所親。","迎接須衿疏傅老，祗供莫笑阮家貧。","杯盤狼籍宜侵夜，风景闌珊欲過春。","相对喜歡還悵望，同年只有此三人。"]', '诗', 'shi', '', NULL, '酬鄭二司錄與李六郎中寒食日相過同宴見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05ffe97c-3c5d-4a48-bbda-0074c7a76cef', '喜楊六侍御同宿', '喜楊六侍御同宿', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["岸幘靜言明月夜，匡牀閑臥落花朝。","二三月裏饒春睡，七八年來不早朝。","濁水清塵難會合，高鵬低鷃各逍遙。","眼看又上青雲去，更卜同衾一兩宵。"]', '["岸幘静言明月夜，匡牀闲臥落花朝。","二三月裏饒春睡，七八年来不早朝。","濁水清塵难會合，高鵬低鷃各逍遙。","眼看又上青云去，更卜同衾一兩宵。"]', '诗', 'shi', '', NULL, '喜楊六侍御同宿 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7380bcd-6773-472a-9f9d-681f18e44002', '殘春詠懷贈楊慕巢侍郎', '殘春詠懷贈楊慕巢侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["位逾三品日，年過六旬時。","不道官班下，其如筋力衰。","猶憐好風景，轉重舊親知。","少壯難重得，歡娛且強爲。","興來池上酌，醉出袖中詩。","靜話開襟久，閑吟放醆遲。","落花無限雪，殘鬢幾多絲。","莫說傷心事，春翁易酒悲。"]', '["位逾三品日，年過六旬时。","不道官班下，其如筋力衰。","猶怜好风景，轉重旧親知。","少壯难重得，歡娛且強爲。","兴来池上酌，醉出袖中诗。","静話开襟久，闲吟放醆遲。","落花無限雪，殘鬢幾多絲。","莫说傷心事，春翁易酒悲。"]', '诗', 'shi', '', NULL, '殘春詠懷贈楊慕巢侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f6d46b2-3471-4274-bd04-72a04f95ea7c', '閑居春盡', '闲居春尽', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑泊池舟靜掩扉，老身慵出客來稀。","愁應暮雨留教住，春被殘鶯喚遣歸。","揭甕偷嘗新熟酒，開箱試著舊生衣。","冬裘夏葛相催促，垂老光陰速似飛。"]', '["闲泊池舟静掩扉，老身慵出客来稀。","愁應暮雨留教住，春被殘鶯喚遣归。","揭甕偷嘗新熟酒，开箱試著旧生衣。","冬裘夏葛相催促，垂老光陰速似飞。"]', '诗', 'shi', '', NULL, '閑居春盡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696bdf92-9cff-4fd6-bf94-b45f28aa5032', '春盡日天津橋醉吟偶呈李尹侍郎', '春尽日天津橋醉吟偶呈李尹侍郎', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["宿雨洗天津，無泥未有塵。","初晴迎早夏，落照送殘春。","興發詩隨口，狂來酒寄身。","水邊行嵬峩，橋上立逡巡。","疎傅心情老，吳公政化新。","三川徒有主，風景屬閑人。"]', '["宿雨洗天津，無泥未有塵。","初晴迎早夏，落照送殘春。","兴發诗隨口，狂来酒寄身。","水邊行嵬峩，橋上立逡巡。","疎傅心情老，吳公政化新。","三川徒有主，风景屬闲人。"]', '诗', 'shi', '', NULL, '春盡日天津橋醉吟偶呈李尹侍郎 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c2808ce-2e41-4d93-a57d-59e71d35f74d', '池上逐涼二首 一', '池上逐涼二首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青苔地上消殘暑，綠樹陰前逐晚涼。","輕屐單衫薄紗帽，淺池平岸庳藤牀。","簪纓怪我情何薄，泉石諳君味甚長。","徧問交親爲老計，多言宜靜不宜忙。"]', '["青苔地上消殘暑，綠樹陰前逐晚涼。","轻屐單衫薄紗帽，淺池平岸庳藤牀。","簪纓怪我情何薄，泉石諳君味甚长。","徧问交親爲老計，多言宜静不宜忙。"]', '诗', 'shi', '', NULL, '池上逐涼二首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca468563-e19a-47ed-bbc3-0bb47188315d', '池上逐涼二首 二', '池上逐涼二首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窗間睡足休高枕，水畔閑來上小船。","櫂遣禿頭奴子撥，茶教纖手侍兒煎。","門前便是紅塵地，林外無非赤日天。","誰信好風清簟上，更無一事但翛然。"]', '["窗间睡足休高枕，水畔闲来上小船。","櫂遣禿头奴子撥，茶教纖手侍兒煎。","门前便是紅塵地，林外無非赤日天。","誰信好风清簟上，更無一事但翛然。"]', '诗', 'shi', '', NULL, '池上逐涼二首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2c807d44-b9d9-4e39-bf52-faa461b4a4fb', '香山避暑二絕 一', '香山避暑二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六月灘聲如猛雨，香山樓北暢師房。","夜深起凭闌干立，滿耳潺湲滿面涼。"]', '["六月灘声如猛雨，香山楼北暢師房。","夜深起凭闌干立，满耳潺湲满面涼。"]', '诗', 'shi', '', NULL, '香山避暑二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e1f2e3b0-112c-460c-9b71-c975d025af71', '香山避暑二絕 二', '香山避暑二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紗巾草履竹疎衣，晚下香山蹋翠微。","一路涼風十八里，臥乘籃轝睡中歸。"]', '["紗巾草履竹疎衣，晚下香山蹋翠微。","一路涼风十八里，臥乘籃轝睡中归。"]', '诗', 'shi', '', NULL, '香山避暑二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ec4b3a3-bb95-460e-bab8-d4bd6b607e00', '老夫', '老夫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七八年來遊洛都，三分遊伴二分無。","風前月下花園裏，處處唯殘个老夫。","世事勞心非富貴，人間實事是歡娛。","誰能逐我來閑坐，時共酣歌傾一壺。"]', '["七八年来游洛都，三分游伴二分無。","风前月下花园裏，处处唯殘个老夫。","世事勞心非富貴，人间實事是歡娛。","誰能逐我来闲坐，时共酣歌傾一壺。"]', '诗', 'shi', '', NULL, '老夫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cf9d927-3dd4-4fd3-a330-c71b9b747934', '香山下卜居', '香山下卜居', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老須爲老計，老計在抽簪。","山下初投足，人間久息心。","亂藤遮石壁，絕澗護雲林。","若要深藏處，無如此處深。"]', '["老須爲老計，老計在抽簪。","山下初投足，人间久息心。","亂藤遮石壁，絕澗護云林。","若要深藏处，無如此处深。"]', '诗', 'shi', '', NULL, '香山下卜居 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4690d143-27fb-422e-9bd9-f071c3d64eaf', '無長物', '無长物', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["莫訝家居窄，無嫌活計貧。","只緣無長物，始得作閑人。","青竹單牀簟，烏紗獨幅巾。","其餘皆稱是，亦足奉吾身。"]', '["莫訝家居窄，無嫌活計貧。","只緣無长物，始得作闲人。","青竹單牀簟，烏紗独幅巾。","其餘皆稱是，亦足奉吾身。"]', '诗', 'shi', '', NULL, '無長物 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e560bf2f-cb08-4ed3-a71a-424778ea55b8', '宿香山寺酬廣陵牛相公見寄', '宿香山寺酬廣陵牛相公见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["手札八行詩一篇，無由相見但依然。","君匡聖主方行道，我事空王正坐禪。","支許徒思遊白月，夔龍未放下青天。","應須且爲蒼生住，猶去懸車十四年。"]', '["手札八行诗一篇，無由相见但依然。","君匡聖主方行道，我事空王正坐禪。","支許徒思游白月，夔龙未放下青天。","應須且爲蒼生住，猶去懸车十四年。"]', '诗', 'shi', '', NULL, '宿香山寺酬廣陵牛相公見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5dd7f13-2f06-4fcc-a2eb-02cf2d4de23e', '以詩代書寄戶部楊侍郎勸買東鄰王家宅', '以诗代书寄戶部楊侍郎勸買东鄰王家宅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["勸君買取東鄰宅，與我衡門相並開。","雲映嵩峰當戶牖，月和伊水入池臺。","林園亦要聞閑置，筋力應須及健迴。","莫學因循白賓客，欲年六十始歸來。"]', '["勸君買取东鄰宅，與我衡门相並开。","云映嵩峰當戶牖，月和伊水入池台。","林园亦要闻闲置，筋力應須及健迴。","莫学因循白賓客，欲年六十始归来。"]', '诗', 'shi', '', NULL, '以詩代書寄戶部楊侍郎勸買東鄰王家宅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0cd98c5e-1750-4bb8-a364-d23ed6768481', '贈談客', '贈談客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上客清談何亹亹，幽人閑思自寥寥。","請君休說長安事，膝上風清琴正調。"]', '["上客清談何亹亹，幽人闲思自寥寥。","請君休说长安事，膝上风清琴正調。"]', '诗', 'shi', '', NULL, '贈談客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b51cd92-94e4-4cc0-98f3-5a556228ba44', '初入香山院對月', '初入香山院对月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老住香山初到夜，秋逢白月正圓時。","從今便是家山月，試問清光知不知。"]', '["老住香山初到夜，秋逢白月正圓时。","從今便是家山月，試问清光知不知。"]', '诗', 'shi', '', NULL, '初入香山院對月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c973d4d6-e2ba-4a05-b6a8-73e79955fd10', '題龍門堰西澗', '題龙门堰西澗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東岸菊叢西岸柳，柳陰煙合菊花開。","一條秋水琉璃色，闊狹纔容小舫迴。","除却悠悠白少傅，何人解入此中來。"]', '["东岸菊叢西岸柳，柳陰煙合菊花开。","一條秋水琉璃色，闊狹纔容小舫迴。","除却悠悠白少傅，何人解入此中来。"]', '诗', 'shi', '', NULL, '題龍門堰西澗 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd3d8e0c-a549-44a9-b55c-4f1c9b9befed', '秋霖中奉裴令公見招早出赴會馬上先寄六韻', '秋霖中奉裴令公见招早出赴會马上先寄六韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雨暗三秋日，泥深一尺時。","老人平旦出，自問欲何之。","不是尋醫藥，非干送別離。","素書傳好語，絳帳赴佳期。","續借桃花馬，催迎楊柳姬。","只愁張錄事，罰我怪來遲。"]', '["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是尋醫藥，非干送別離。","素书傳好語，絳帳赴佳期。","續借桃花马，催迎楊柳姬。","只愁張錄事，罰我怪来遲。"]', '诗', 'shi', '', NULL, '秋霖中奉裴令公見招早出赴會馬上先寄六韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09976f6b-ed1e-4b35-9b1a-a3a3cebb9f6f', '嘗酒聽歌招客', '嘗酒听歌招客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一甕香醪新插芻，雙鬟小妓薄能謳。","管弦漸好新教得，羅綺雖貧免外求。","世上貪忙不覺苦，人間除醉即須愁。","不知此事君知否，君若知時從我遊。"]', '["一甕香醪新插芻，雙鬟小妓薄能謳。","管弦漸好新教得，羅綺雖貧免外求。","世上貪忙不覺苦，人间除醉即須愁。","不知此事君知否，君若知时從我游。"]', '诗', 'shi', '', NULL, '嘗酒聽歌招客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e1caa8a-5a9f-4ca9-98f0-c4e091a43d0e', '八月三日夜作', '八月三日夜作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["露白月微明，天涼景物清。","草頭珠顆冷，樓角玉鉤生。","氣爽衣裳健，風疎砧杵鳴。","夜衾香有思，秋簟冷無情。","夢短眠頻覺，宵長起暫行。","燭凝臨曉影，蟲怨欲寒聲。","槿老花先盡，蓮凋子始成。","四時無了日，何用歎衰榮。"]', '["露白月微明，天涼景物清。","草头珠顆冷，楼角玉鉤生。","氣爽衣裳健，风疎砧杵鳴。","夜衾香有思，秋簟冷無情。","梦短眠頻覺，宵长起暫行。","燭凝臨晓影，蟲怨欲寒声。","槿老花先尽，蓮凋子始成。","四时無了日，何用歎衰榮。"]', '诗', 'shi', '', NULL, '八月三日夜作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d54ddc0d-bcc6-4767-b42f-1961c07efe59', '病中贈南鄰覓酒', '病中贈南鄰覓酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["頭痛牙疼三日臥，妻看煎藥婢來扶。","今朝似校擡頭語，先問南鄰有酒無。"]', '["头痛牙疼三日臥，妻看煎藥婢来扶。","今朝似校擡头語，先问南鄰有酒無。"]', '诗', 'shi', '', NULL, '病中贈南鄰覓酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98feffbf-5801-4d93-bdfa-805b31a9a5b8', '曉眠後寄楊戶部', '晓眠後寄楊戶部', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["輭綾腰褥薄緜被，涼冷秋天穩暖身。","一覺曉眠殊有味，無因寄與早朝人。"]', '["輭綾腰褥薄緜被，涼冷秋天穩暖身。","一覺晓眠殊有味，無因寄與早朝人。"]', '诗', 'shi', '', NULL, '曉眠後寄楊戶部 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d91f5def-2309-41b2-b58c-80443c295fcb', '秋雨夜眠', '秋雨夜眠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["涼冷三秋夜，安閑一老翁。","臥遲燈滅後，睡美雨聲中。","灰宿溫瓶火，香添煖被籠。","曉晴寒未起，霜葉滿階紅。"]', '["涼冷三秋夜，安闲一老翁。","臥遲灯滅後，睡美雨声中。","灰宿溫瓶火，香添煖被籠。","晓晴寒未起，霜葉满階紅。"]', '诗', 'shi', '', NULL, '秋雨夜眠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6754d7b4-3ee7-4685-a5d6-f4d4d5b120bc', '喜夢得自馮翊歸洛兼呈令公', '喜梦得自馮翊归洛兼呈令公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["上客新從左輔迴，高陽興助洛陽才。","已將四海聲名去，又占三春風景來。","甲子等頭憐共老，文章敵手莫相猜。","鄒枚未用爭詩酒，且飲梁王賀喜杯。"]', '["上客新從左輔迴，高陽兴助洛陽才。","已將四海声名去，又占三春风景来。","甲子等头怜共老，文章敵手莫相猜。","鄒枚未用爭诗酒，且饮梁王賀喜杯。"]', '诗', 'shi', '', NULL, '喜夢得自馮翊歸洛兼呈令公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b063b5f-326b-43b4-aea5-f8a4a926e383', '齋戒滿夜戲招夢得', '斋戒满夜戲招梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["紗籠燈下道場前，白日持齋夜坐禪。","無復更思身外事，未能全盡世間緣。","明朝又擬親杯酒，今夕先聞理管弦。","方丈若能來問疾，不妨兼有散花天。"]', '["紗籠灯下道場前，白日持斋夜坐禪。","無复更思身外事，未能全尽世间緣。","明朝又擬親杯酒，今夕先闻理管弦。","方丈若能来问疾，不妨兼有散花天。"]', '诗', 'shi', '', NULL, '齋戒滿夜戲招夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f27f6e70-92a7-437b-ad15-49bff64bf675', '和令公問劉賓客歸來稱意無之作', '和令公问劉賓客归来稱意無之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水南秋一半，風景未蕭條。","皂蓋迴沙苑，藍轝上洛橋。","閑嘗黃菊酒，醉唱紫芝謠。","稱意那勞問，請錢不早朝。"]', '["水南秋一半，风景未蕭條。","皂蓋迴沙苑，藍轝上洛橋。","闲嘗黄菊酒，醉唱紫芝謠。","稱意那勞问，請錢不早朝。"]', '诗', 'shi', '', NULL, '和令公問劉賓客歸來稱意無之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8f53f24-6973-4d34-b8b6-5e81a06ae420', '酬夢得窮秋夜坐即事見寄', '酬梦得窮秋夜坐即事见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["焰細燈將盡，聲遙漏正長。","老人秋向火，小女夜縫裳。","菊悴籬經雨，萍銷水得霜。","今冬煖寒酒，先擬共君嘗。"]', '["焰細灯將尽，声遙漏正长。","老人秋向火，小女夜縫裳。","菊悴籬經雨，萍銷水得霜。","今冬煖寒酒，先擬共君嘗。"]', '诗', 'shi', '', NULL, '酬夢得窮秋夜坐即事見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd12c204-a136-437f-910a-1f9a7401d7d8', '偶於維揚牛相公處覓得箏箏未到先寄詩來走筆戲荅', '偶於維揚牛相公处覓得箏箏未到先寄诗来走笔戲荅', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["楚匠饒巧思，秦箏多好音。","如能惠一面，何啻直雙金。","玉柱調須品，朱弦染要深。","會教魔女弄，不動是禪心。"]', '["楚匠饒巧思，秦箏多好音。","如能惠一面，何啻直雙金。","玉柱調須品，朱弦染要深。","會教魔女弄，不动是禪心。"]', '诗', 'shi', '', NULL, '偶於維揚牛相公處覓得箏箏未到先寄詩來走筆戲荅 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c173ced7-76cd-4307-a17f-43dd77459c7e', '荅夢得秋庭獨坐見贈', '荅梦得秋庭独坐见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["林梢隱映夕陽殘，庭際蕭疎夜氣寒。","霜草欲枯蟲思急，風枝未定鳥棲難。","容衰見鏡同惆悵，身健逢杯且喜歡。","應是天教相煖熱，一時垂老與閑宮。"]', '["林梢隐映夕陽殘，庭際蕭疎夜氣寒。","霜草欲枯蟲思急，风枝未定鸟棲难。","容衰见镜同惆悵，身健逢杯且喜歡。","應是天教相煖熱，一时垂老與闲宮。"]', '诗', 'shi', '', NULL, '荅夢得秋庭獨坐見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fda608cb-dd18-45d9-8af1-7817e7268e92', '長齋月滿攜酒先與夢得對酌醉中同赴令公之宴戲贈夢得', '长斋月满携酒先與梦得对酌醉中同赴令公之宴戲贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["齋宮前日滿三旬，酒榼今朝一拂塵。","乘興還同訪戴客，解酲仍對姓劉人。","病心湯沃寒灰活，老面花生朽木春。","若怕平原怪先醉，知君未慣吐車茵。"]', '["斋宮前日满三旬，酒榼今朝一拂塵。","乘兴還同訪戴客，解酲仍对姓劉人。","病心湯沃寒灰活，老面花生朽木春。","若怕平原怪先醉，知君未慣吐车茵。"]', '诗', 'shi', '', NULL, '長齋月滿攜酒先與夢得對酌醉中同赴令公之宴戲贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de7d9cf-34a7-4d97-a6b4-3ff21fbe75d2', '奉酬淮南牛相公思黯見寄二十四韻', '奉酬淮南牛相公思黯见寄二十四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白老忘機客，牛公濟世賢。","鷗棲心戀水，鵬舉翅摩天。","累就優閑秩，連操造化權。","貧司甚蕭灑，榮路自喧闐。","望苑三千日，台階十五年。","是人皆棄忘，何物不陶甄。","籃轝遊嵩嶺，油幢鎮海壖。","竹篙撑釣艇，金甲擁樓船。","雪夜尋僧舍，春朝列妓筵。","長齋儼香火，密宴簇花鈿。","自覺閑勝鬧，遙知醉笑禪。","是非分未定，會合杳無緣。","我正思楊府，君應望洛川。","西來風褭褭，南去雁連連。","日落龍門外，潮生瓜步前。","秋同一時盡，月共兩鄉圓。","舊眷交歡在，新文氣調全。","慙無白雪曲，難荅碧雲篇。","金谷詩誰賞，蕪城賦衆傳。","珠應哂魚目，鉛未伏龍泉。","遠訊驚魔物，深情寄酒錢。","霜紈一百疋，玉柱十三弦。","楚醴來尊裏，秦聲送耳邊。","何時紅燭下，相對一陶然。"]', '["白老忘機客，牛公濟世賢。","鷗棲心戀水，鵬舉翅摩天。","累就優闲秩，連操造化權。","貧司甚蕭灑，榮路自喧闐。","望苑三千日，台階十五年。","是人皆棄忘，何物不陶甄。","籃轝游嵩嶺，油幢鎮海壖。","竹篙撑釣艇，金甲擁楼船。","雪夜尋僧舍，春朝列妓筵。","长斋儼香火，密宴簇花鈿。","自覺闲勝鬧，遙知醉笑禪。","是非分未定，會合杳無緣。","我正思楊府，君應望洛川。","西来风褭褭，南去雁連連。","日落龙门外，潮生瓜步前。","秋同一时尽，月共兩乡圓。","旧眷交歡在，新文氣調全。","慙無白雪曲，难荅碧云篇。","金谷诗誰賞，蕪城賦衆傳。","珠應哂鱼目，鉛未伏龙泉。","远訊驚魔物，深情寄酒錢。","霜紈一百疋，玉柱十三弦。","楚醴来尊裏，秦声送耳邊。","何时紅燭下，相对一陶然。"]', '诗', 'shi', '', NULL, '奉酬淮南牛相公思黯見寄二十四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89a1db3d-39bb-479e-ad72-3b4bb97ee9f9', '吳祕監每有美酒獨酌獨醉但蒙詩報不以飲招輙此戲酬兼呈夢得', '吳祕監每有美酒独酌独醉但蒙诗報不以饮招輙此戲酬兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["蓬山仙客下煙霄，對酒唯吟獨酌謠。","不怕道狂揮玉爵，亦曾乘興解金貂。","君稱名士誇能飲，我是愚夫肯見招。","賴有伯倫爲醉伴，何愁不解傲松喬。"]', '["蓬山仙客下煙霄，对酒唯吟独酌謠。","不怕道狂揮玉爵，亦曾乘兴解金貂。","君稱名士誇能饮，我是愚夫肯见招。","賴有伯倫爲醉伴，何愁不解傲松喬。"]', '诗', 'shi', '', NULL, '吳祕監每有美酒獨酌獨醉但蒙詩報不以飲招輙此戲酬兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53a99c15-6da0-4c6b-a361-34489ba4ec48', '酬夢得霜夜對月見懷', '酬梦得霜夜对月见懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淒清冬夜景，搖落長年情。","月帶新霜色，碪和遠雁聲。","暖憐爐火近，寒覺被衣輕。","枕上酬佳句，詩成夢不成。"]', '["淒清冬夜景，搖落长年情。","月带新霜色，碪和远雁声。","暖怜爐火近，寒覺被衣轻。","枕上酬佳句，诗成梦不成。"]', '诗', 'shi', '', NULL, '酬夢得霜夜對月見懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cded7e0-33d9-44d4-a3d6-e6f83d084824', '初冬月夜得皇甫澤州手札幷詩數篇因遣報書偶題長句', '初冬月夜得皇甫澤州手札幷诗數篇因遣報书偶題长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["清泠玉韻兩三章，落箔銀鉤七八行。","心逐報書懸雁足，夢尋來路繞羊腸。","水南地空多明月，山北天寒足早霜。","最恨潑醅新熟酒，迎冬不得共君嘗。"]', '["清泠玉韻兩三章，落箔銀鉤七八行。","心逐報书懸雁足，梦尋来路繞羊腸。","水南地空多明月，山北天寒足早霜。","最恨潑醅新熟酒，迎冬不得共君嘗。"]', '诗', 'shi', '', NULL, '初冬月夜得皇甫澤州手札幷詩數篇因遣報書偶題長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a849536b-d198-49f0-a04b-b7b90c96018d', '雪中酒熟欲攜訪吳監先寄此詩', '雪中酒熟欲携訪吳監先寄此诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新雪對新酒，憶同傾一杯。","自然須訪戴，不必待延枚。","陳榻無辭解，袁門莫嬾開。","笙歌與談笑，隨事自將來。"]', '["新雪对新酒，憶同傾一杯。","自然須訪戴，不必待延枚。","陳榻無辞解，袁门莫嬾开。","笙歌與談笑，隨事自將来。"]', '诗', 'shi', '', NULL, '雪中酒熟欲攜訪吳監先寄此詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf31380f-2482-448d-9ffc-250a0fdb0861', '酬令公雪中見贈訝不與夢得同相訪', '酬令公雪中见贈訝不與梦得同相訪', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["雪似鵝毛飛散亂，人披鶴氅立裴回。","鄒生枚叟非無興，唯待梁王召即來。"]', '["雪似鵝毛飞散亂，人披鹤氅立裴回。","鄒生枚叟非無兴，唯待梁王召即来。"]', '诗', 'shi', '', NULL, '酬令公雪中見贈訝不與夢得同相訪 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e98f5a29-cb12-43a1-be8a-21f447958a13', '題酒甕呈夢得', '題酒甕呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["若無清酒兩三甕，爭向白鬚千萬莖。","麴糵銷愁真得力，光陰催老苦無情。","凌煙閣上功無分，伏火爐中藥未成。","更擬共君何處去，且來同作醉先生。"]', '["若無清酒兩三甕，爭向白鬚千万莖。","麴糵銷愁真得力，光陰催老苦無情。","凌煙閣上功無分，伏火爐中藥未成。","更擬共君何处去，且来同作醉先生。"]', '诗', 'shi', '', NULL, '題酒甕呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3597bce-26c0-4816-ad39-b2b475acbaf7', '迂叟', '迂叟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一辭魏闕就商賓，散地閑居八九春。","初時被目爲迂叟，近日蒙呼作隱人。","冷暖俗情諳世路，是非閑論任交親。","應須繩墨機關外，安置疎愚鈍滯身。"]', '["一辞魏闕就商賓，散地闲居八九春。","初时被目爲迂叟，近日蒙呼作隐人。","冷暖俗情諳世路，是非闲論任交親。","應須繩墨機关外，安置疎愚鈍滯身。"]', '诗', 'shi', '', NULL, '迂叟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3a626f-e99c-4220-ba9c-f7184c7aad18', '洛下閑居寄山南令狐相公', '洛下闲居寄山南令狐相公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["已收身向園林下，猶寄名於祿仕間。","不鍛嵇康彌嬾靜，無金疎傅更貧閑。","支分門內餘生計，謝絕朝中舊往還。","唯是相君忘未得，時思漢水夢巴山。"]', '["已收身向园林下，猶寄名於祿仕间。","不鍛嵇康彌嬾静，無金疎傅更貧闲。","支分门內餘生計，謝絕朝中旧往還。","唯是相君忘未得，时思漢水梦巴山。"]', '诗', 'shi', '', NULL, '洛下閑居寄山南令狐相公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24648591-4aed-4e69-a011-26958c067a0a', '惜春贈李尹', '惜春贈李尹', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["春色有時盡，公門終日忙。","兩衙但不闕，一醉亦何妨。","芳樹花團雪，衰翁鬢撲霜。","知君倚年少，未苦惜風光。"]', '["春色有时尽，公门終日忙。","兩衙但不闕，一醉亦何妨。","芳樹花團雪，衰翁鬢撲霜。","知君倚年少，未苦惜风光。"]', '诗', 'shi', '', NULL, '惜春贈李尹 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fc37252-848e-42fd-9c59-773a1a2ca1a9', '對酒勸令公開春遊宴', '对酒勸令公开春游宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["時泰歲豐無事日，功成名遂自由身。","前頭更有忘憂日，向上應無快活人。","自去年來多事故，從今日去少交親。","宜須數數謀歡會，好作開成第二春。"]', '["时泰歲豐無事日，功成名遂自由身。","前头更有忘憂日，向上應無快活人。","自去年来多事故，從今日去少交親。","宜須數數謀歡會，好作开成第二春。"]', '诗', 'shi', '', NULL, '對酒勸令公開春遊宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f679b5a3-ba16-4cbc-88ae-9762a0261e81', '與夢得偶同到敦詩宅感而題壁', '與梦得偶同到敦诗宅感而題壁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["山東纔副蒼生願，川上俄驚逝水波。","履道淒涼新第宅，宣城零落舊笙歌。","園荒唯有薪堪採，門冷兼無雀可羅。","今日相逢偶同到，傷心不是故經過。"]', '["山东纔副蒼生願，川上俄驚逝水波。","履道淒涼新第宅，宣城零落旧笙歌。","园荒唯有薪堪採，门冷兼無雀可羅。","今日相逢偶同到，傷心不是故經過。"]', '诗', 'shi', '', NULL, '與夢得偶同到敦詩宅感而題壁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc84e41-c0c6-41f5-a399-58c6b3a95551', '楊六尚書新授東川節度使代妻戲賀兄嫂二絕 一', '楊六尚书新授东川節度使代妻戲賀兄嫂二絕 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["劉綱與婦共昇仙，弄玉隨夫亦上天。","何似沙哥領崔嫂，碧油幢引向東川。"]', '["劉綱與婦共昇仙，弄玉隨夫亦上天。","何似沙哥領崔嫂，碧油幢引向东川。"]', '诗', 'shi', '', NULL, '楊六尚書新授東川節度使代妻戲賀兄嫂二絕 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2d81f14-86be-4a33-a274-d2640249d826', '楊六尚書新授東川節度使代妻戲賀兄嫂二絕 二', '楊六尚书新授东川節度使代妻戲賀兄嫂二絕 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["金花銀椀饒君用，罨畫羅衣盡嫂裁。","覓得黔婁爲妹壻，可能空寄蜀茶來。"]', '["金花銀椀饒君用，罨畫羅衣尽嫂裁。","覓得黔婁爲妹壻，可能空寄蜀茶来。"]', '诗', 'shi', '', NULL, '楊六尚書新授東川節度使代妻戲賀兄嫂二絕 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e818e044-b74e-449c-bae7-3027fc00d799', '閑遊即事', '闲游即事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郊野遊行熟，村園次第過。","驀山尋浥澗，蹋水渡伊河。","寒食青青草，春風瑟瑟波。","逢人共杯酒，隨馬有笙歌。","勝事經非少，芳辰過亦多。","還須自知分，不老擬如何。"]', '["郊野游行熟，村园次第過。","驀山尋浥澗，蹋水渡伊河。","寒食青青草，春风瑟瑟波。","逢人共杯酒，隨马有笙歌。","勝事經非少，芳辰過亦多。","還須自知分，不老擬如何。"]', '诗', 'shi', '', NULL, '閑遊即事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d19fe25f-6188-47cf-b056-068b222ebf9f', '六十六', '六十六', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["七十欠四歲，此生那足論。","每因悲物故，還且喜身存。","安得頭長黑，爭教眼不昏。","交游成拱木，婢僕見曾孫。","瘦覺腰金重，衰憐鬢雪繁。","將何理老病，應付與空門。"]', '["七十欠四歲，此生那足論。","每因悲物故，還且喜身存。","安得头长黑，爭教眼不昏。","交游成拱木，婢僕见曾孫。","瘦覺腰金重，衰怜鬢雪繁。","將何理老病，應付與空门。"]', '诗', 'shi', '', NULL, '六十六 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f716ee9-0091-4f55-b488-9254a9822c20', '池上早春即事招夢得', '池上早春即事招梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老更驚年改，閑先覺日長。","晴熏榆莢黑，春染柳梢黃。","雲破山呈色，冰融水放光。","低平穩船舫，輕暖好衣裳。","白角三升榼，紅茵六尺牀。","偶遊難得伴，獨醉不成狂。","我有中心樂，君無外事忙。","經過莫慵嬾，相去兩三坊。"]', '["老更驚年改，闲先覺日长。","晴熏榆莢黑，春染柳梢黄。","云破山呈色，冰融水放光。","低平穩船舫，轻暖好衣裳。","白角三升榼，紅茵六尺牀。","偶游难得伴，独醉不成狂。","我有中心乐，君無外事忙。","經過莫慵嬾，相去兩三坊。"]', '诗', 'shi', '', NULL, '池上早春即事招夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('407ef767-6e67-4104-9f2a-c2377db682f9', '因夢得題公垂所寄蠟燭因寄公垂', '因梦得題公垂所寄蠟燭因寄公垂', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["照梁初日光相似，出水新蓮豔不如。","却寄兩條君令取，明年雙引入中書。"]', '["照梁初日光相似，出水新蓮豔不如。","却寄兩條君令取，明年雙引入中书。"]', '诗', 'shi', '', NULL, '因夢得題公垂所寄蠟燭因寄公垂 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf1bd48-8ce3-4e50-bbbb-e5b0f491c801', '令公南莊花柳正盛欲偷一賞先寄二篇 一', '令公南莊花柳正盛欲偷一賞先寄二篇 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["最憶樓花千萬朵，偏憐堤柳兩三株。","擬提社酒攜村妓，擅入朱門莫怪無。"]', '["最憶楼花千万朵，偏怜堤柳兩三株。","擬提社酒携村妓，擅入朱门莫怪無。"]', '诗', 'shi', '', NULL, '令公南莊花柳正盛欲偷一賞先寄二篇 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41ce0e5-b035-4626-aefd-dc9e4f8a5d7a', '令公南莊花柳正盛欲偷一賞先寄二篇 二', '令公南莊花柳正盛欲偷一賞先寄二篇 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可惜亭臺閑度日，欲偷風景暫遊春。","只愁花裏鶯饒舌，飛入宮城報主人。"]', '["可惜亭台闲度日，欲偷风景暫游春。","只愁花裏鶯饒舌，飞入宮城報主人。"]', '诗', 'shi', '', NULL, '令公南莊花柳正盛欲偷一賞先寄二篇 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48bf8656-8ff7-4380-bd51-9756b415c512', '春夜宴席上戲贈裴淄川', '春夜宴席上戲贈裴淄川', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["九十不衰真地仙，六旬猶健亦天憐。","今年相遇鶯花月，此夜同歡歌酒筵。","四座齊聲和絲竹，兩家隨分鬬金鈿。","留君到曉無他意，圖向君前作少年。"]', '["九十不衰真地仙，六旬猶健亦天怜。","今年相遇鶯花月，此夜同歡歌酒筵。","四座齊声和絲竹，兩家隨分鬬金鈿。","留君到晓無他意，圖向君前作少年。"]', '诗', 'shi', '', NULL, '春夜宴席上戲贈裴淄川 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6c94e80-a5eb-4519-89ab-d3b6a142330c', '贈夢得', '贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年顏老少與君同，眼未全昏耳未聾。","放醉臥爲春日伴，趂歡行入少年叢。","尋花借馬煩川守，弄水偷船惱令公。","聞道洛城人盡怪，呼爲劉白二狂翁。"]', '["年顏老少與君同，眼未全昏耳未聾。","放醉臥爲春日伴，趂歡行入少年叢。","尋花借马煩川守，弄水偷船惱令公。","闻道洛城人尽怪，呼爲劉白二狂翁。"]', '诗', 'shi', '', NULL, '贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8956f39-ab8c-4c5c-8057-39daad4b2d97', '晚春欲攜酒尋沈四著作先以六韻寄之', '晚春欲携酒尋沈四著作先以六韻寄之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病容衰慘澹，芳景晚蹉跎。","無計留春得，爭能奈老何。","篇章慵報荅，杯讌喜經過。","顧我酒狂久，負君詩債多。","敢辭攜綠蟻，只願見青娥。","最憶陽關唱，真珠一串歌。"]', '["病容衰慘澹，芳景晚蹉跎。","無計留春得，爭能奈老何。","篇章慵報荅，杯讌喜經過。","顧我酒狂久，負君诗債多。","敢辞携綠蟻，只願见青娥。","最憶陽关唱，真珠一串歌。"]', '诗', 'shi', '', NULL, '晚春欲攜酒尋沈四著作先以六韻寄之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('618258f5-94bc-441f-abfb-858611aca56e', '三月三日祓禊洛濱', '三月三日祓禊洛濱', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["三月草萋萋，黃鶯歇又啼。","柳橋晴有絮，沙路潤無泥。","禊事修初半，遊人到欲齊。","金鈿耀桃李，絲管駭鳧鷖。","轉岸迴船尾，臨流簇馬蹄。","鬧翻揚子渡，蹋破魏王堤。","妓接謝公宴，詩陪荀令題。","舟同李膺泛，醴爲穆生攜。","水引春心蕩，花牽醉眼迷。","塵街從鼓動，煙樹任鴉棲。","舞急紅腰軟，歌遲翠黛低。","夜歸何用燭，新月鳳樓西。"]', '["三月草萋萋，黄鶯歇又啼。","柳橋晴有絮，沙路潤無泥。","禊事修初半，游人到欲齊。","金鈿耀桃李，絲管駭鳧鷖。","轉岸迴船尾，臨流簇马蹄。","鬧翻揚子渡，蹋破魏王堤。","妓接謝公宴，诗陪荀令題。","舟同李膺泛，醴爲穆生携。","水引春心蕩，花牽醉眼迷。","塵街從鼓动，煙樹任鴉棲。","舞急紅腰軟，歌遲翠黛低。","夜归何用燭，新月鳳楼西。"]', '诗', 'shi', '', NULL, '三月三日祓禊洛濱 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd0a494f-a2e5-4b77-b828-ccaf9595e52e', '同夢得暮春寄賀東西川二楊尚書', '同梦得暮春寄賀东西川二楊尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["龍節對持真可愛，雁行相接更堪誇。","兩川風景同三月，千里江山屬一家。","魯衛定知連氣色，潘楊亦覺有光華。","應憐洛下分司伴，冷宴閑遊老看花。"]', '["龙節对持真可愛，雁行相接更堪誇。","兩川风景同三月，千里江山屬一家。","魯衛定知連氣色，潘楊亦覺有光华。","應怜洛下分司伴，冷宴闲游老看花。"]', '诗', 'shi', '', NULL, '同夢得暮春寄賀東西川二楊尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23d29c51-acf8-4d60-a761-c24675021791', '喜小樓西新柳抽條', '喜小楼西新柳抽條', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一行弱柳前年種，數尺柔條今日新。","漸欲拂他騎馬客，未多遮得上樓人。","須教碧玉羞眉黛，莫與紅桃作麴塵。","爲報金堤千萬樹，饒伊未敢苦爭春。"]', '["一行弱柳前年種，數尺柔條今日新。","漸欲拂他騎马客，未多遮得上楼人。","須教碧玉羞眉黛，莫與紅桃作麴塵。","爲報金堤千万樹，饒伊未敢苦爭春。"]', '诗', 'shi', '', NULL, '喜小樓西新柳抽條 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c3fc9e6-aac2-4497-a3f5-76f0a803478c', '晚春酒醒尋夢得', '晚春酒醒尋梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["料合同惆悵，花殘酒亦殘。","醉心忘老易，醒眼別春難。","獨出雖慵嬾，相逢定喜歡。","還攜小蠻去，試覓老劉看。"]', '["料合同惆悵，花殘酒亦殘。","醉心忘老易，醒眼別春难。","独出雖慵嬾，相逢定喜歡。","還携小蠻去，試覓老劉看。"]', '诗', 'shi', '', NULL, '晚春酒醒尋夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc2e3197-9444-4690-bf6b-bddc6f31df4f', '感事', '感事', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["服氣崔常侍，燒丹鄭舍人。","常期生羽翼，那忽化灰塵。","每遇淒涼事，還思潦倒身。","唯知趂杯酒，不解鍊金銀。","睡適三尸性，慵安五藏神。","無憂亦無喜，六十六年春。"]', '["服氣崔常侍，燒丹鄭舍人。","常期生羽翼，那忽化灰塵。","每遇淒涼事，還思潦倒身。","唯知趂杯酒，不解鍊金銀。","睡適三尸性，慵安五藏神。","無憂亦無喜，六十六年春。"]', '诗', 'shi', '', NULL, '感事 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b940a9-ec1a-4f14-a317-1feeb82ba04b', '和裴令公南莊絕句', '和裴令公南莊絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["陶廬僻陋那堪比，謝墅幽微不足攀。","何似嵩峰三十六，長隨申甫作家山。"]', '["陶廬僻陋那堪比，謝墅幽微不足攀。","何似嵩峰三十六，长隨申甫作家山。"]', '诗', 'shi', '', NULL, '和裴令公南莊絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82043ca1-e3da-45c3-93b1-82f8207a1ce8', '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 一', '宅西有流水牆下構小楼臨玩之时頗有幽趣因命歌酒聊以自娛独醉独吟偶題五絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["伊水分來不自由，無人解愛爲誰流。","家家拋向牆根底，唯我栽蓮越小樓。"]', '["伊水分来不自由，無人解愛爲誰流。","家家拋向牆根底，唯我栽蓮越小楼。"]', '诗', 'shi', '', NULL, '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c61a5c72-1cea-4aaf-85bd-15e7d9f61b55', '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 二', '宅西有流水牆下構小楼臨玩之时頗有幽趣因命歌酒聊以自娛独醉独吟偶題五絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水色波文何所似，麴塵羅帶一條斜。","莫言羅帶春無主，自置樓來屬白家。"]', '["水色波文何所似，麴塵羅带一條斜。","莫言羅带春無主，自置楼来屬白家。"]', '诗', 'shi', '', NULL, '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bd8f33b-6f97-4093-b7ad-9a2ec0ee4d36', '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 三', '宅西有流水牆下構小楼臨玩之时頗有幽趣因命歌酒聊以自娛独醉独吟偶題五絕句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["日灩水光搖素壁，風飄樹影拂朱欄。","皆言此處宜弦管，試奏霓裳一曲看。"]', '["日灩水光搖素壁，风飄樹影拂朱欄。","皆言此处宜弦管，試奏霓裳一曲看。"]', '诗', 'shi', '', NULL, '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bf6eec2-9e9b-4c5c-902e-28f3e1c1e043', '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 四', '宅西有流水牆下構小楼臨玩之时頗有幽趣因命歌酒聊以自娛独醉独吟偶題五絕句 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霓裳奏罷唱梁州，紅袖斜翻翠黛愁。","應是遙聞勝近聽，行人欲過盡迴頭。"]', '["霓裳奏罷唱梁州，紅袖斜翻翠黛愁。","應是遙闻勝近听，行人欲過尽迴头。"]', '诗', 'shi', '', NULL, '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('047cc6b5-d1d3-495f-8618-0d5422df595a', '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 五', '宅西有流水牆下構小楼臨玩之时頗有幽趣因命歌酒聊以自娛独醉独吟偶題五絕句 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["獨醉還須得歌舞，自娛何必要親賓。","當時一部清商樂，亦不長將樂外人。"]', '["独醉還須得歌舞，自娛何必要親賓。","當时一部清商乐，亦不长將乐外人。"]', '诗', 'shi', '', NULL, '宅西有流水牆下構小樓臨玩之時頗有幽趣因命歌酒聊以自娛獨醉獨吟偶題五絕句 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb7ba540-75dd-4717-9d0b-e4f88931d53e', '偶作', '偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["籃舁出即忘歸舍，柴戶昏猶未掩關。","聞客病時慙體健，見人忙處覺心閑。","清涼秋寺行香去，和暖春城拜表還。","木雁一篇須記取，致身才與不才間。"]', '["籃舁出即忘归舍，柴戶昏猶未掩关。","闻客病时慙體健，见人忙处覺心闲。","清涼秋寺行香去，和暖春城拜表還。","木雁一篇須記取，致身才與不才间。"]', '诗', 'shi', '', NULL, '偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cec4e78b-c91b-4bee-8b27-9a12fe6d6b43', '因夢得酬牛相公初到洛中小飲見贈', '因梦得酬牛相公初到洛中小饮见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淮南揮手拋紅斾，洛下迴頭向白雲。","政事堂中老丞相，制科場裏舊將軍。","宮城煙月饒全占，關塞風光請半分。","詩酒放狂猶得在，莫欺白叟與劉君。"]', '["淮南揮手拋紅斾，洛下迴头向白云。","政事堂中老丞相，制科場裏旧將軍。","宮城煙月饒全占，关塞风光請半分。","诗酒放狂猶得在，莫欺白叟與劉君。"]', '诗', 'shi', '', NULL, '因夢得酬牛相公初到洛中小飲見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eebcb493-b76b-4ccf-b258-0b704a24cd4c', '幽居早秋閑詠', '幽居早秋闲詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["幽僻囂塵外，清涼水木間。","臥風秋拂簟，步月夜開關。","且得身安泰，從他世險艱。","但休爭要路，不必入深山。","軒鶴留何用，泉魚放不還。","誰人知此味，臨老十年閑。"]', '["幽僻囂塵外，清涼水木间。","臥风秋拂簟，步月夜开关。","且得身安泰，從他世險艱。","但休爭要路，不必入深山。","軒鹤留何用，泉鱼放不還。","誰人知此味，臨老十年闲。"]', '诗', 'shi', '', NULL, '幽居早秋閑詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ae31a9a-1271-4bd1-8d56-b7be57aa5c5e', '和令狐僕射小飲聽阮咸', '和令狐僕射小饮听阮咸', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掩抑復淒清，非琴不是箏。","還彈樂府曲，別占阮家名。","古調何人識，初聞滿座驚。","落盤珠歷歷，搖珮玉琤琤。","似勸杯中物，如含林下情。","時移音律改，豈是昔時聲。"]', '["掩抑复淒清，非琴不是箏。","還彈乐府曲，別占阮家名。","古調何人識，初闻满座驚。","落盤珠歷歷，搖珮玉琤琤。","似勸杯中物，如含林下情。","时移音律改，豈是昔时声。"]', '诗', 'shi', '', NULL, '和令狐僕射小飲聽阮咸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228b1330-b470-4493-9dcb-77d4345e7a5d', '燒藥不成命酒獨醉', '燒藥不成命酒独醉', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮逢秋王，丹砂見火空。","不能留姹女，爭免作衰翁。","賴有杯中綠，能爲面上紅。","少年心不遠，只在半酣中。"]', '["白髮逢秋王，丹砂见火空。","不能留姹女，爭免作衰翁。","賴有杯中綠，能爲面上紅。","少年心不远，只在半酣中。"]', '诗', 'shi', '', NULL, '燒藥不成命酒獨醉 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4dbfde36-7fc1-4940-af75-cb372c122a11', '送盧郎中赴河東裴令公幕', '送盧郎中赴河东裴令公幕', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["別時暮雨洛橋岸，到日涼風汾水波。","荀令見君應問我，爲言秋草閉門多。"]', '["別时暮雨洛橋岸，到日涼风汾水波。","荀令见君應问我，爲言秋草閉门多。"]', '诗', 'shi', '', NULL, '送盧郎中赴河東裴令公幕 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eff91f7-73ae-479e-8358-eefc83eb8b44', '送李滁州', '送李滁州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君於覺路深留意，我亦禪門薄致功。","未悟病時須去病，已知空後莫依空。","白衣臥病嵩山下，皁蓋行春楚水東。","誰道三年千里別，兩心同在道場中。"]', '["君於覺路深留意，我亦禪门薄致功。","未悟病时須去病，已知空後莫依空。","白衣臥病嵩山下，皁蓋行春楚水东。","誰道三年千里別，兩心同在道場中。"]', '诗', 'shi', '', NULL, '送李滁州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e70c1682-d50e-4e24-8369-ed952f93ecd8', '長齋月滿寄思黯', '长斋月满寄思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一日不見如三月，一月相思如七年。","似隔山河千里地，仍當風雨九秋天。","明朝齋滿相尋去，挈榼抱衾同醉眠。"]', '["一日不见如三月，一月相思如七年。","似隔山河千里地，仍當风雨九秋天。","明朝斋满相尋去，挈榼抱衾同醉眠。"]', '诗', 'shi', '', NULL, '長齋月滿寄思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b900332c-ebca-4e16-a556-9c7618b87a2c', '冬夜對酒寄皇甫十', '冬夜对酒寄皇甫十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜殺中庭草，冰生後院池。","有風空動樹，無葉可辭枝。","十月苦長夜，百年強半時。","新開一瓶酒，那得不相思。"]', '["霜殺中庭草，冰生後院池。","有风空动樹，無葉可辞枝。","十月苦长夜，百年強半时。","新开一瓶酒，那得不相思。"]', '诗', 'shi', '', NULL, '冬夜對酒寄皇甫十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45715f0e-5271-42b5-bc67-69604b1ff5ce', '歲除夜對酒', '歲除夜对酒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["衰翁歲除夜，對酒思悠然。","草白經霜地，雲黃欲雪天。","醉依香枕坐，慵傍煖爐眠。","洛下閑來久，明朝是十年。"]', '["衰翁歲除夜，对酒思悠然。","草白經霜地，云黄欲雪天。","醉依香枕坐，慵傍煖爐眠。","洛下闲来久，明朝是十年。"]', '诗', 'shi', '', NULL, '歲除夜對酒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('269e39c7-8e54-43de-bad4-86909285f911', '寄獻北都留守裴令公', '寄獻北都留守裴令公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天上中台正，人間一品高。","休明值堯舜，勳業過蕭曹。","始擅文三捷，終兼武六韜。","動人名赫赫，憂國意忉忉。","盪蔡擒封豕，平齊斬巨鼇。","兩河收土宇，四海定波濤。","寵重移宮籥，恩新換閫旄。","保釐東宅靜，守護北門牢。","晉國封疆闊，幷州士馬豪。","胡兵驚赤幟，邊雁避烏號。","令下流如水，仁霑澤似膏。","路喧歌五袴，軍醉感單醪。","將校森貔武，賓僚儼雋髦。","客無煩夜柝，吏不犯秋毫。","神在臺駘助，魂亡獫狁逃。","德星銷彗孛，霖雨滅腥臊。","烽戍高臨代，關河遠控洮。","汾雲晴漠漠，朔吹冷颾颾。","豹尾交牙戟，蚪鬚捧佩刀。","通天白犀帶，照地紫麟袍。","羌管吹楊柳，燕姬酌蒲萄。","銀含鑿落醆，金屑琵琶槽。","遙想從軍樂，應忘報國勞。","紫微留北闕，綠野寄東臯。","忽憶前時會，多慙下客叨。","清宵陪讌話，美景從遊遨。","花月還同賞，琴詩雅自操。","朱弦拂宮徵，洪筆振風騷。","近竹開方丈，依林架桔槔。","春池八九曲，畫舫兩三艘。","徑滑苔黏屐，潭深水沒篙。","綠絲縈岸柳，紅粉映樓桃。","爲穆先陳醴，招劉共藉糟。","舞鬟金翡翠，歌頸玉蠐螬。","盛德終難過，明時豈易遭。","公雖慕張范，帝未舍伊臯。","眷戀心方結，踟躕首已搔。","鸞皇上寥廓，燕雀任蓬蒿。","欲獻文狂簡，徒煩思鬱陶。","可憐四百字，輕重抵鴻毛。"]', '["天上中台正，人间一品高。","休明值堯舜，勳業過蕭曹。","始擅文三捷，終兼武六韜。","动人名赫赫，憂国意忉忉。","盪蔡擒封豕，平齊斬巨鼇。","兩河收土宇，四海定波濤。","寵重移宮籥，恩新換閫旄。","保釐东宅静，守護北门牢。","晉国封疆闊，幷州士马豪。","胡兵驚赤幟，邊雁避烏號。","令下流如水，仁霑澤似膏。","路喧歌五袴，軍醉感單醪。","將校森貔武，賓僚儼雋髦。","客無煩夜柝，吏不犯秋毫。","神在台駘助，魂亡獫狁逃。","德星銷彗孛，霖雨滅腥臊。","烽戍高臨代，关河远控洮。","汾云晴漠漠，朔吹冷颾颾。","豹尾交牙戟，蚪鬚捧佩刀。","通天白犀带，照地紫麟袍。","羌管吹楊柳，燕姬酌蒲萄。","銀含鑿落醆，金屑琵琶槽。","遙想從軍乐，應忘報国勞。","紫微留北闕，綠野寄东臯。","忽憶前时會，多慙下客叨。","清宵陪讌話，美景從游遨。","花月還同賞，琴诗雅自操。","朱弦拂宮徵，洪笔振风騷。","近竹开方丈，依林架桔槔。","春池八九曲，畫舫兩三艘。","徑滑苔黏屐，潭深水沒篙。","綠絲縈岸柳，紅粉映楼桃。","爲穆先陳醴，招劉共藉糟。","舞鬟金翡翠，歌頸玉蠐螬。","盛德終难過，明时豈易遭。","公雖慕張范，帝未舍伊臯。","眷戀心方結，踟躕首已搔。","鸾皇上寥廓，燕雀任蓬蒿。","欲獻文狂簡，徒煩思鬱陶。","可怜四百字，轻重抵鴻毛。"]', '诗', 'shi', '', NULL, '寄獻北都留守裴令公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6555677c-1bfc-4c14-bd1a-97464811f003', '和東川楊慕巢尚書府中獨坐感戚在懷見寄十四韻', '和东川楊慕巢尚书府中独坐感戚在懷见寄十四韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["我是知君者，君今意若何。","窮通時不定，苦樂事相和。","東蜀歡殊渥，西江歎逝波。","只緣榮貴極，翻使感傷多。","行斷風驚雁，年侵日下坡。","片心休慘戚，雙鬢已蹉跎。","紫綬黃金印，青幢白玉珂。","老將榮補貼，愁用道銷磨。","外府饒杯酒，中堂有綺羅。","應須引滿飲，何不放狂歌？","錦水通巴峽，香山對洛河。","將軍馳鐵馬，少傅步銅駝。","深契憐松竹，高情憶薜蘿。","懸車年甚遠，未敢故相過。"]', '["我是知君者，君今意若何。","窮通时不定，苦乐事相和。","东蜀歡殊渥，西江歎逝波。","只緣榮貴極，翻使感傷多。","行斷风驚雁，年侵日下坡。","片心休慘戚，雙鬢已蹉跎。","紫綬黄金印，青幢白玉珂。","老將榮補貼，愁用道銷磨。","外府饒杯酒，中堂有綺羅。","應須引满饮，何不放狂歌？","錦水通巴峽，香山对洛河。","將軍驰鐵马，少傅步銅駝。","深契怜松竹，高情憶薜蘿。","懸车年甚远，未敢故相過。"]', '诗', 'shi', '', NULL, '和東川楊慕巢尚書府中獨坐感戚在懷見寄十四韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7911d0ba-5c2c-4e76-9c99-c884396c093c', '分司洛中多暇數與諸客宴遊醉後狂吟偶成十韻因招夢得賓客兼呈思黯奇章公', '分司洛中多暇數與諸客宴游醉後狂吟偶成十韻因招梦得賓客兼呈思黯奇章公', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["性與時相遠，身將世兩忘。","寄名朝士籍，寓興少年場。","老豈無談笑，貧猶有酒漿。","隨時來伴侶，逐日用風光。","數數遊何爽，些些病未妨。","天教榮啓樂，人恕接輿狂。","改業爲逋客，移家住醉鄉。","不論招夢得，兼擬誘奇章。","要路風波險，權門市井忙。","世間無可戀，不是不思量。"]', '["性與时相远，身將世兩忘。","寄名朝士籍，寓兴少年場。","老豈無談笑，貧猶有酒漿。","隨时来伴侶，逐日用风光。","數數游何爽，些些病未妨。","天教榮啓乐，人恕接輿狂。","改業爲逋客，移家住醉乡。","不論招梦得，兼擬誘奇章。","要路风波險，權门市井忙。","世间無可戀，不是不思量。"]', '诗', 'shi', '', NULL, '分司洛中多暇數與諸客宴遊醉後狂吟偶成十韻因招夢得賓客兼呈思黯奇章公 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61a52053-8753-4961-917f-f95ed1c3bea8', '小歲日喜談氏外孫女孩滿月', '小歲日喜談氏外孫女孩满月', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["今旦夫妻喜，他人豈得知。","自嗟生女晚，敢訝見孫遲。","物以稀爲貴，情因老更慈。","新年逢吉日，滿月乞名時。","桂燎熏花果，蘭湯洗玉肌。","懷中有可抱，何必是男兒。"]', '["今旦夫妻喜，他人豈得知。","自嗟生女晚，敢訝见孫遲。","物以稀爲貴，情因老更慈。","新年逢吉日，满月乞名时。","桂燎熏花果，蘭湯洗玉肌。","懷中有可抱，何必是男兒。"]', '诗', 'shi', '', NULL, '小歲日喜談氏外孫女孩滿月 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f32d7165-5a28-43c4-8559-5de69bd00c7f', '閑吟贈皇甫郎中親家翁', '闲吟贈皇甫郎中親家翁', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["誰能嗟歎光陰暮，豈復憂愁活計貧。","忽忽不知頭上事，時時猶憶眼中人。","早爲良友非交勢，晚接嘉姻不失親。","最喜兩家婚嫁畢，一時抽得尚平身。"]', '["誰能嗟歎光陰暮，豈复憂愁活計貧。","忽忽不知头上事，时时猶憶眼中人。","早爲良友非交勢，晚接嘉姻不失親。","最喜兩家婚嫁畢，一时抽得尚平身。"]', '诗', 'shi', '', NULL, '閑吟贈皇甫郎中親家翁 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('32277eaf-e49a-4772-97f7-157aa485f592', '夢得臥病攜酒相尋先以此寄', '梦得臥病携酒相尋先以此寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病來知少客，誰可以爲娛。","日晏開門未，秋寒有酒無。","自宜相慰問，何必待招呼。","小疾無妨飲，還須挈一壺。"]', '["病来知少客，誰可以爲娛。","日晏开门未，秋寒有酒無。","自宜相慰问，何必待招呼。","小疾無妨饮，還須挈一壺。"]', '诗', 'shi', '', NULL, '夢得臥病攜酒相尋先以此寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('416db338-76c7-40c3-b52a-b4543a4df824', '酬思黯戲贈同用狂字', '酬思黯戲贈同用狂字', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鍾乳三千兩，金釵十二行。","妬他心似火，欺我鬢如霜。","慰老資歌笑，銷愁仰酒漿。","眼看狂不得，狂得且須狂。"]', '["鍾乳三千兩，金釵十二行。","妬他心似火，欺我鬢如霜。","慰老資歌笑，銷愁仰酒漿。","眼看狂不得，狂得且須狂。"]', '诗', 'shi', '', NULL, '酬思黯戲贈同用狂字 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42cd174f-9d4a-4b03-90f9-ce1018fc0519', '又戲荅絕句', '又戲荅絕句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["狂夫與我兩相忘，故態些些亦不妨。","縱酒放歌聊自樂，接輿爭解教人狂。"]', '["狂夫與我兩相忘，故態些些亦不妨。","縱酒放歌聊自乐，接輿爭解教人狂。"]', '诗', 'shi', '', NULL, '又戲荅絕句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f85622f9-3067-4311-bd3c-12e69a6649e8', '令狐相公與夢得交情素深眷予分亦不淺一聞薨逝相顧泫然旋有使來得前月未歿之前數日書及詩寄贈夢得哀吟悲歎寄情于詩詩成示予感而繼和', '令狐相公與梦得交情素深眷予分亦不淺一闻薨逝相顧泫然旋有使来得前月未歿之前數日书及诗寄贈梦得哀吟悲歎寄情于诗诗成示予感而繼和', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["緘題重疊語殷勤，存沒交親自此分。","前月使來猶理命，今朝詩到是遺文。","銀鉤見晚書無報，玉樹埋深哭不聞。","最感一行絕筆字，尚言千萬樂天君。"]', '["緘題重叠語殷勤，存沒交親自此分。","前月使来猶理命，今朝诗到是遺文。","銀鉤见晚书無報，玉樹埋深哭不闻。","最感一行絕笔字，尚言千万乐天君。"]', '诗', 'shi', '', NULL, '令狐相公與夢得交情素深眷予分亦不淺一聞薨逝相顧泫然旋有使來得前月未歿之前數日書及詩寄贈夢得哀吟悲歎寄情于詩詩成示予感而繼和 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2edea3aa-144f-4168-b760-2517740699b0', '洛下雪中頻與劉李二賓客宴集因寄汴州李尚書', '洛下雪中頻與劉李二賓客宴集因寄汴州李尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["水南水北雪紛紛，雪裏歡遊莫厭頻。","日日暗來唯老病，年年少去是交親。","碧氈帳暖梅花濕，紅燎爐香竹葉春。","今日鄒枚俱在洛，梁園置酒召何人。"]', '["水南水北雪紛紛，雪裏歡游莫厭頻。","日日暗来唯老病，年年少去是交親。","碧氈帳暖梅花濕，紅燎爐香竹葉春。","今日鄒枚俱在洛，梁园置酒召何人。"]', '诗', 'shi', '', NULL, '洛下雪中頻與劉李二賓客宴集因寄汴州李尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ce7edb41-4bd3-4bc1-98e6-943f7c0ac145', '看夢得題荅李侍郎詩詩中有文星之句因戲和之', '看梦得題荅李侍郎诗诗中有文星之句因戲和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["看題錦繡報瓊瓌，俱是人天第一才。","好遣文星守躔次，亦須防有客星來。"]', '["看題錦繡報瓊瓌，俱是人天第一才。","好遣文星守躔次，亦須防有客星来。"]', '诗', 'shi', '', NULL, '看夢得題荅李侍郎詩詩中有文星之句因戲和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed7c5788-2d19-4cce-8b33-161f3db13e3d', '閑適', '闲適', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["祿俸優饒官不卑，就中閑適是分司。","風光暖助遊行處，雨雪寒供飲宴時。","肥馬輕裘還且有，麤歌薄酒亦相隨。","微躬所要今皆得，只是蹉跎得校遲。"]', '["祿俸優饒官不卑，就中闲適是分司。","风光暖助游行处，雨雪寒供饮宴时。","肥马轻裘還且有，麤歌薄酒亦相隨。","微躬所要今皆得，只是蹉跎得校遲。"]', '诗', 'shi', '', NULL, '閑適 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55109dea-a8a7-4de0-9e14-ab4d7c4f1a50', '戲荅思黯', '戲荅思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["何時得見十三弦，待取無雲有月天。","願得金波明似鏡，鏡中照出月中仙。"]', '["何时得见十三弦，待取無云有月天。","願得金波明似镜，镜中照出月中仙。"]', '诗', 'shi', '', NULL, '戲荅思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea0eef3c-8815-49b5-aafa-96bc981679e2', '酬裴令公贈馬相戲', '酬裴令公贈马相戲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["安石風流無奈何，欲將赤驥換青娥。","不辭便送東山去，臨老何人與唱歌。"]', '["安石风流無奈何，欲將赤驥換青娥。","不辞便送东山去，臨老何人與唱歌。"]', '诗', 'shi', '', NULL, '酬裴令公贈馬相戲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c06ae7be-028e-4861-b29c-e081eb3fa8bd', '新歲贈夢得', '新歲贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暮齒忽將及，同心私自憐。","漸衰宜減食，已喜更加年。","紫綬行聯袂，籃轝出比肩。","與君同甲子，歲酒合誰先。"]', '["暮齒忽將及，同心私自怜。","漸衰宜減食，已喜更加年。","紫綬行聯袂，籃轝出比肩。","與君同甲子，歲酒合誰先。"]', '诗', 'shi', '', NULL, '新歲贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5492348-63aa-4354-b6a0-b0940e15a419', '早春持齋荅皇甫十見贈', '早春持斋荅皇甫十见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["正月晴和風氣新，紛紛已有醉遊人。","帝城花笑長齋客，三十年來負早春。"]', '["正月晴和风氣新，紛紛已有醉游人。","帝城花笑长斋客，三十年来負早春。"]', '诗', 'shi', '', NULL, '早春持齋荅皇甫十見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53b02afe-b045-4c34-a0d5-f9db04e489dc', '戲贈夢得兼呈思黯', '戲贈梦得兼呈思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霜鬢莫欺今老矣，一杯莫笑便陶然。","陳郎中處爲高戶，裴使君前作少年。","顧我獨狂多自哂，與君同病最相憐。","月終齋滿誰開素，須擬奇章置一筵。"]', '["霜鬢莫欺今老矣，一杯莫笑便陶然。","陳郎中处爲高戶，裴使君前作少年。","顧我独狂多自哂，與君同病最相怜。","月終斋满誰开素，須擬奇章置一筵。"]', '诗', 'shi', '', NULL, '戲贈夢得兼呈思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c71472b-cd6e-4f4e-a90d-2f8a83136b39', '早春憶遊思黯南莊因寄長句', '早春憶游思黯南莊因寄长句', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["南莊勝處心常憶，借問軒車早晚遊。","美景難忘竹廊下，好風爭奈柳橋頭。","冰消見水多於地，雪霽看山盡入樓。","若待春深始同賞，鶯殘花落却堪愁。"]', '["南莊勝处心常憶，借问軒车早晚游。","美景难忘竹廊下，好风爭奈柳橋头。","冰消见水多於地，雪霽看山尽入楼。","若待春深始同賞，鶯殘花落却堪愁。"]', '诗', 'shi', '', NULL, '早春憶遊思黯南莊因寄長句 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08bee2c4-6577-460e-8223-ca08334ce6c0', '酬皇甫十早春對雪見贈', '酬皇甫十早春对雪见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["漠漠復雰雰，東風散玉塵。","明催竹窗曉，寒退柳園春。","綠醞香堪憶，紅爐暖可親。","忍心三兩日，莫作破齋人。"]', '["漠漠复雰雰，东风散玉塵。","明催竹窗晓，寒退柳园春。","綠醞香堪憶，紅爐暖可親。","忍心三兩日，莫作破斋人。"]', '诗', 'shi', '', NULL, '酬皇甫十早春對雪見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('625ab649-4839-418f-a65b-4c64feb00f5e', '奉和思黯自題南莊見示兼呈夢得', '奉和思黯自題南莊见示兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["謝家別墅最新奇，山展屏風花夾籬。","曉月漸沈橋脚底，晨光初照屋梁時。","臺頭有酒鶯呼客，水面無塵風洗池。","除却吟詩兩閑客，此中情狀更誰知。"]', '["謝家別墅最新奇，山展屏风花夾籬。","晓月漸沈橋脚底，晨光初照屋梁时。","台头有酒鶯呼客，水面無塵风洗池。","除却吟诗兩闲客，此中情狀更誰知。"]', '诗', 'shi', '', NULL, '奉和思黯自題南莊見示兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45fdc966-f43d-4336-b41c-bcc3b52f5273', '送蘄春李十九使君赴郡', '送蘄春李十九使君赴郡', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["可憐官職好文詞，五十專城未是遲。","曉日鏡前無白髮，春風門外有紅旗。","郡中何處堪攜酒，席上誰人解和詩。","唯共交親開口笑，知君不及洛陽時。"]', '["可怜官職好文词，五十專城未是遲。","晓日镜前無白髮，春风门外有紅旗。","郡中何处堪携酒，席上誰人解和诗。","唯共交親开口笑，知君不及洛陽时。"]', '诗', 'shi', '', NULL, '送蘄春李十九使君赴郡 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc4f12d4-0e21-46e5-a83b-38544402c509', '自題酒庫', '自題酒庫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["野鶴一辭籠，虛舟長任風。","送愁還鬧處，移老入閑中。","身更求何事，天將富此翁。","此翁何處富，酒庫不曾空。"]', '["野鹤一辞籠，虛舟长任风。","送愁還鬧处，移老入闲中。","身更求何事，天將富此翁。","此翁何处富，酒庫不曾空。"]', '诗', 'shi', '', NULL, '自題酒庫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('877bdb1e-9884-4059-9cc0-bff7e9364f72', '寒食日寄楊東川', '寒食日寄楊东川', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["不知楊六逢寒食，作底歡娛過此辰。","兜率寺高宜望月，嘉陵江近好遊春。","蠻旗似火行隨馬，蜀妓如花坐遶身。","不使黔婁夫婦看，誇張富貴向何人。"]', '["不知楊六逢寒食，作底歡娛過此辰。","兜率寺高宜望月，嘉陵江近好游春。","蠻旗似火行隨马，蜀妓如花坐遶身。","不使黔婁夫婦看，誇張富貴向何人。"]', '诗', 'shi', '', NULL, '寒食日寄楊東川 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2af83135-180d-4983-938d-f195dc4451fc', '醉後聽唱桂華曲', '醉後听唱桂华曲', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["桂華詞意苦丁寧，唱到常娥醉便醒。","此是人間腸斷曲，莫教不得意人聽。"]', '["桂华词意苦丁寧，唱到常娥醉便醒。","此是人间腸斷曲，莫教不得意人听。"]', '诗', 'shi', '', NULL, '醉後聽唱桂華曲 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e87f8bd-3832-4845-916e-6247ec4ff784', '酬夢得以予五月長齋延僧徒絕賓友見戲十韻', '酬梦得以予五月长斋延僧徒絕賓友见戲十韻', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賓客懶逢迎，翛然池館清。","簷閑空燕語，林靜未蟬鳴。","葷血還休食，杯觴亦罷傾。","三春多放逸，五月暫修行。","香印朝煙細，紗燈夕焰明。","交遊諸長老，師事古先生。","禪後心彌寂，齋來體更輕。","不唯忘肉味，兼擬滅風情。","蒙以聲聞待，難將戲論爭。","虛空若有佛，靈運恐先成。"]', '["賓客懶逢迎，翛然池館清。","簷闲空燕語，林静未蟬鳴。","葷血還休食，杯觴亦罷傾。","三春多放逸，五月暫修行。","香印朝煙細，紗灯夕焰明。","交游諸长老，師事古先生。","禪後心彌寂，斋来體更轻。","不唯忘肉味，兼擬滅风情。","蒙以声闻待，难將戲論爭。","虛空若有佛，靈運恐先成。"]', '诗', 'shi', '', NULL, '酬夢得以予五月長齋延僧徒絕賓友見戲十韻 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe2d8cab-b2da-4652-8bcf-98c58e85a4f7', '奉和裴令公三月上巳日遊太原龍泉憶去歲禊洛見示之作', '奉和裴令公三月上巳日游太原龙泉憶去歲禊洛见示之作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["去歲暮春上巳，共泛洛水中流。","今歲暮春上巳，獨立香山下頭。","風光閑寂寂，旌斾遠悠悠。","丞相府歸晉國，太行山礙幷州。","鵬背負天龜曳尾，雲泥不可得同遊。"]', '["去歲暮春上巳，共泛洛水中流。","今歲暮春上巳，独立香山下头。","风光闲寂寂，旌斾远悠悠。","丞相府归晉国，太行山礙幷州。","鵬背負天龟曳尾，云泥不可得同游。"]', '诗', 'shi', '', NULL, '奉和裴令公三月上巳日遊太原龍泉憶去歲禊洛見示之作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e53ca024-bac4-44c1-9fb9-ef5f8caa5c8f', '又和令公新開龍泉晉水二池', '又和令公新开龙泉晉水二池', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["舊有潢汚泊，今爲白水塘。","笙歌聞四面，樓閣在中央。","春變煙波色，晴添樹木光。","龍泉信爲美，莫忘午橋莊。"]', '["旧有潢汚泊，今爲白水塘。","笙歌闻四面，楼閣在中央。","春变煙波色，晴添樹木光。","龙泉信爲美，莫忘午橋莊。"]', '诗', 'shi', '', NULL, '又和令公新開龍泉晉水二池 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d6b3c0d-50b9-4a5d-9260-f9793744a54e', '早夏曉興贈夢得', '早夏晓兴贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["窗明簾薄透朝光，臥整巾簪起下牀。","背壁燈殘經宿焰，開箱衣帶隔年香。","無情亦任他春去，不醉爭銷得晝長。","一部清商一壺酒，與君明日暖新堂。"]', '["窗明簾薄透朝光，臥整巾簪起下牀。","背壁灯殘經宿焰，开箱衣带隔年香。","無情亦任他春去，不醉爭銷得晝长。","一部清商一壺酒，與君明日暖新堂。"]', '诗', 'shi', '', NULL, '早夏曉興贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b6db47a-31ac-454f-abb0-4d42d89f4cf5', '春日題乾元寺上方最高峰亭', '春日題乾元寺上方最高峰亭', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["危亭絕頂四無鄰，見盡三千世界春。","但覺虛空無障礙，不知高下幾由旬。","迴看官路三條線，却望都城一片塵。","賓客暫遊無半日，王侯不到便終身。","始知天造空閑境，不爲忙人富貴人。"]', '["危亭絕頂四無鄰，见尽三千世界春。","但覺虛空無障礙，不知高下幾由旬。","迴看官路三條線，却望都城一片塵。","賓客暫游無半日，王侯不到便終身。","始知天造空闲境，不爲忙人富貴人。"]', '诗', 'shi', '', NULL, '春日題乾元寺上方最高峰亭 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a23f935-734e-424b-b878-94c7abb31547', '奉和思黯相公以李蘇州所寄太湖石奇狀絕倫因題二十韻見示兼呈夢得', '奉和思黯相公以李蘇州所寄太湖石奇狀絕倫因題二十韻见示兼呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["錯落復崔嵬，蒼然玉一堆。","峰駢仙掌出，罅坼劒門開。","峭頂高危矣，盤根下壯哉。","精神欺竹樹，氣色壓亭臺。","隱起磷磷狀，凝成瑟瑟胚。","廉稜露鋒刃，清越扣瓊瑰。","岌嶪形將動，巍峩勢欲摧。","奇應潛鬼怪，靈合蓄雲雷。","黛潤霑新雨，斑明點古苔。","未曾栖鳥雀，不肯染塵埃。","尖削琅玕筍，窪剜瑪瑙罍。","海神移碣石，畫障簇天台。","在世爲尤物，如人負逸才。","渡江一葦載，入洛五丁推。","出處雖無意，升沈亦有媒。","拔從水府底，置向相庭隈。","對稱吟詩句，看宜把酒杯。","終隨金礪用，不學玉山頹。","疎傅心偏愛，園公眼屢迴。","共嗟無此分，虛管太湖來。"]', '["錯落复崔嵬，蒼然玉一堆。","峰駢仙掌出，罅坼劒门开。","峭頂高危矣，盤根下壯哉。","精神欺竹樹，氣色壓亭台。","隐起磷磷狀，凝成瑟瑟胚。","廉稜露鋒刃，清越扣瓊瑰。","岌嶪形將动，巍峩勢欲摧。","奇應潛鬼怪，靈合蓄云雷。","黛潤霑新雨，斑明点古苔。","未曾栖鸟雀，不肯染塵埃。","尖削琅玕筍，窪剜瑪瑙罍。","海神移碣石，畫障簇天台。","在世爲尤物，如人負逸才。","渡江一葦載，入洛五丁推。","出处雖無意，升沈亦有媒。","拔從水府底，置向相庭隈。","对稱吟诗句，看宜把酒杯。","終隨金礪用，不学玉山頹。","疎傅心偏愛，园公眼屢迴。","共嗟無此分，虛管太湖来。"]', '诗', 'shi', '', NULL, '奉和思黯相公以李蘇州所寄太湖石奇狀絕倫因題二十韻見示兼呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4adabd9f-fbac-40c4-ae32-3cb2f338d127', '奉和思黯相公雨後林園四韻見示', '奉和思黯相公雨後林园四韻见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["新晴夏景好，復此池邊地。","煙樹綠含滋，水風清有味。","便成林下隱，都忘門前事。","騎吏引歸軒，始知身富貴。"]', '["新晴夏景好，复此池邊地。","煙樹綠含滋，水风清有味。","便成林下隐，都忘门前事。","騎吏引归軒，始知身富貴。"]', '诗', 'shi', '', NULL, '奉和思黯相公雨後林園四韻見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd69db74-268c-466f-94df-26277d4c9afe', '晚夏閑居絕無賓客欲尋夢得先寄此詩', '晚夏闲居絕無賓客欲尋梦得先寄此诗', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["魚筍朝餐飽，蕉紗暑服輕。","欲爲窗下寢，先傍水邊行。","晴引鶴雙舞，秋生蟬一聲。","無人解相訪，有酒共誰傾。","老更諳時事，閑多見物情。","只應劉與白，二叟自相迎。"]', '["鱼筍朝餐飽，蕉紗暑服轻。","欲爲窗下寢，先傍水邊行。","晴引鹤雙舞，秋生蟬一声。","無人解相訪，有酒共誰傾。","老更諳时事，闲多见物情。","只應劉與白，二叟自相迎。"]', '诗', 'shi', '', NULL, '晚夏閑居絕無賓客欲尋夢得先寄此詩 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27b3c724-d5ec-4504-97a4-a9df022770e7', '寄李蘄州', '寄李蘄州', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["下車書奏龔黃課，動筆詩傳鮑謝風。","江郡謳謠誇杜母，洛城歡會憶車公。","笛愁春盡梅花裏，簟冷秋生薤葉中。","不道蘄州歌酒少，使君難稱與誰同。"]', '["下车书奏龔黄課，动笔诗傳鲍謝风。","江郡謳謠誇杜母，洛城歡會憶车公。","笛愁春尽梅花裏，簟冷秋生薤葉中。","不道蘄州歌酒少，使君难稱與誰同。"]', '诗', 'shi', '', NULL, '寄李蘄州 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04c605e1-caf5-4d03-958b-e1938a1ae10d', '酬思黯相公晚夏雨後感秋見贈', '酬思黯相公晚夏雨後感秋见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暮去朝來無歇期，炎涼闇向雨中移。","夜長祗合愁人覺，秋冷先應瘦客知。","兩幅彩箋揮逸翰，一聲寒玉振清辭。","無憂無病身榮貴，何故沈吟亦感時。"]', '["暮去朝来無歇期，炎涼闇向雨中移。","夜长祗合愁人覺，秋冷先應瘦客知。","兩幅彩箋揮逸翰，一声寒玉振清辞。","無憂無病身榮貴，何故沈吟亦感时。"]', '诗', 'shi', '', NULL, '酬思黯相公晚夏雨後感秋見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9721830-09b6-4f5c-9953-b5d260b54977', '久雨閑悶對酒偶吟', '久雨闲悶对酒偶吟', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["淒淒苦雨暗銅駞，嫋嫋涼風起漕河。","自夏及秋晴日少，從朝至暮悶時多。","鷺臨池立窺魚笱，隼傍林飛拂雀羅。","賴有杯中神聖物，百憂無奈十分何。"]', '["淒淒苦雨暗銅駞，嫋嫋涼风起漕河。","自夏及秋晴日少，從朝至暮悶时多。","鷺臨池立窺鱼笱，隼傍林飞拂雀羅。","賴有杯中神聖物，百憂無奈十分何。"]', '诗', 'shi', '', NULL, '久雨閑悶對酒偶吟 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8776313d-c1bd-4c33-9bfe-4b5c393189a2', '雨後秋涼', '雨後秋涼', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["夜來秋雨後，秋氣颯然新。","團扇先辭手，生衣不著身。","更添砧引思，難與簟相親。","此境誰偏覺，貧閑老瘦人。"]', '["夜来秋雨後，秋氣颯然新。","團扇先辞手，生衣不著身。","更添砧引思，难與簟相親。","此境誰偏覺，貧闲老瘦人。"]', '诗', 'shi', '', NULL, '雨後秋涼 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1b76a756-3d2f-457f-a63c-b2d3ffd09c55', '酬夢得早秋夜對月見寄', '酬梦得早秋夜对月见寄', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["吾衰寡情趣，君病懶經過。","其奈西樓上，新秋明月何。","庭蕪淒白露，池色澹金波。","況是初長夜，東城砧杵多。"]', '["吾衰寡情趣，君病懶經過。","其奈西楼上，新秋明月何。","庭蕪淒白露，池色澹金波。","況是初长夜，东城砧杵多。"]', '诗', 'shi', '', NULL, '酬夢得早秋夜對月見寄 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe9ae8b7-09f0-4ad6-8ee4-e49ee238809c', '題謝公東山障子', '題謝公东山障子', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["賢愚共在浮生內，貴賤同趨羣動間。","多見忙時已衰病，少聞健日肯休閑。","鷹飢受緤從難退，鶴老乘軒亦不還。","唯有風流謝安石，拂衣攜妓入東山。"]', '["賢愚共在浮生內，貴賤同趨羣动间。","多见忙时已衰病，少闻健日肯休闲。","鷹飢受緤從难退，鹤老乘軒亦不還。","唯有风流謝安石，拂衣携妓入东山。"]', '诗', 'shi', '', NULL, '題謝公東山障子 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1399a743-11cd-4b38-8e1d-efdcf9dafc5a', '謝楊東川寄衣服', '謝楊东川寄衣服', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["年年衰老交遊少，處處蕭條書信稀。","唯有巢兄不相忘，春茶未斷寄秋衣。"]', '["年年衰老交游少，处处蕭條书信稀。","唯有巢兄不相忘，春茶未斷寄秋衣。"]', '诗', 'shi', '', NULL, '謝楊東川寄衣服 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('03faced2-dc9b-47e2-a8f5-4841245a8b7a', '詠懷寄皇甫朗之', '詠懷寄皇甫朗之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["老大多情足往還，招僧待客夜開關。","學調氣後衰中健，不用心來鬧處閑。","養病未能辭薄俸，忘名何必入深山。","與君別有相知分，同置身於木雁間。"]', '["老大多情足往還，招僧待客夜开关。","学調氣後衰中健，不用心来鬧处闲。","養病未能辞薄俸，忘名何必入深山。","與君別有相知分，同置身於木雁间。"]', '诗', 'shi', '', NULL, '詠懷寄皇甫朗之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56442323-a7db-4c8c-8654-82e08f81daa9', '東城晚歸', '东城晚归', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一條邛杖懸龜榼，雙角吳童控馬銜。","晚入東城誰識我，短靴低帽白蕉衫。"]', '["一條邛杖懸龟榼，雙角吳童控马銜。","晚入东城誰識我，短靴低帽白蕉衫。"]', '诗', 'shi', '', NULL, '東城晚歸 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22074ea5-f85d-4525-8aef-48f6bcf9b733', '與夢得沽酒閑飲且約後期', '與梦得沽酒闲饮且約後期', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["少時猶不憂生計，老後誰能惜酒錢。","共把十千沽一斗，相看七十欠三年。","閑徵雅令窮經史，醉聽清吟勝管弦。","更待菊黃家醞熟，共君一醉一陶然。"]', '["少时猶不憂生計，老後誰能惜酒錢。","共把十千沽一斗，相看七十欠三年。","闲徵雅令窮經史，醉听清吟勝管弦。","更待菊黄家醞熟，共君一醉一陶然。"]', '诗', 'shi', '', NULL, '與夢得沽酒閑飲且約後期 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87a10927-f96a-4ae2-b70d-7b41699a860a', '與牛家妓樂雨後合宴', '與牛家妓乐雨後合宴', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["玉管清弦聲旖旎，翠釵紅袖坐參差。","兩家合奏洞房夜，八月連陰秋雨時。","歌臉有情凝睇久，舞腰無力轉帬遲。","人間歡樂無過此，上界西方即不知。"]', '["玉管清弦声旖旎，翠釵紅袖坐參差。","兩家合奏洞房夜，八月連陰秋雨时。","歌臉有情凝睇久，舞腰無力轉帬遲。","人间歡乐無過此，上界西方即不知。"]', '诗', 'shi', '', NULL, '與牛家妓樂雨後合宴 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b33c0f3-e255-439b-8199-f8ed1993cec8', '和楊六尚書喜兩弟漢公轉吳興魯士賜章服命賓開宴用慶恩榮賦長句見示', '和楊六尚书喜兩弟漢公轉吳兴魯士賜章服命賓开宴用慶恩榮賦长句见示', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["華筵賀客日紛紛，劒外歡娛洛下聞。","朱紱寵光新照地，彤襜喜氣遠凌雲。","榮聯花萼詩難和，樂助塤箎酒易[醺]。","感羨料應知我意，今生此事不如君。"]', '["华筵賀客日紛紛，劒外歡娛洛下闻。","朱紱寵光新照地，彤襜喜氣远凌云。","榮聯花萼诗难和，乐助塤箎酒易[醺]。","感羨料應知我意，今生此事不如君。"]', '诗', 'shi', '', NULL, '和楊六尚書喜兩弟漢公轉吳興魯士賜章服命賓開宴用慶恩榮賦長句見示 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('285171a0-cd41-498b-82dc-ded9ec1c22e2', '自詠', '自詠', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鬚白面微紅，醺醺半醉中。","百年隨手過，萬事轉頭空。","臥疾瘦居士，行歌狂老翁。","仍聞好事者，將我畫屏風。"]', '["鬚白面微紅，醺醺半醉中。","百年隨手過，万事轉头空。","臥疾瘦居士，行歌狂老翁。","仍闻好事者，將我畫屏风。"]', '诗', 'shi', '', NULL, '自詠 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a77c6de-1e8a-4530-ab13-9e58a269724d', '夢得相過援琴命酒因彈秋思偶詠所懷兼寄繼之待價二相府', '梦得相過援琴命酒因彈秋思偶詠所懷兼寄繼之待價二相府', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑居靜侶偶相招，小飲初酣琴欲調。","我正風前弄秋思，君應天上聽雲韶。","時和始見陶鈞力，物遂方知盛聖朝。","雙鳳栖梧魚在藻，飛沈隨分各逍遙。"]', '["闲居静侶偶相招，小饮初酣琴欲調。","我正风前弄秋思，君應天上听云韶。","时和始见陶鈞力，物遂方知盛聖朝。","雙鳳栖梧鱼在藻，飞沈隨分各逍遙。"]', '诗', 'shi', '', NULL, '夢得相過援琴命酒因彈秋思偶詠所懷兼寄繼之待價二相府 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7965882-61f3-48d2-9906-55bbc354c5d7', '九月八日酬皇甫十見贈', '九月八日酬皇甫十见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["君方對酒綴詩章，我正持齋坐道場。","處處追遊雖不去，時時吟詠亦無妨。","霜蓬舊鬢三分白，露菊新花一半黃。","惆悵東籬不同醉，陶家明日是重陽。"]', '["君方对酒綴诗章，我正持斋坐道場。","处处追游雖不去，时时吟詠亦無妨。","霜蓬旧鬢三分白，露菊新花一半黄。","惆悵东籬不同醉，陶家明日是重陽。"]', '诗', 'shi', '', NULL, '九月八日酬皇甫十見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90e147d-c139-49dd-9f93-c4da0348e9d3', '慕巢尚書書云室人欲爲置一歌者非所安也以詩相報因而和之', '慕巢尚书书云室人欲爲置一歌者非所安也以诗相報因而和之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["東川已過二三春，南國須求一兩人。","富貴大都多老大，歡娛太半爲親賓。","如愁翠黛應堪重，買笑黃金莫訴貧。","他日相逢一杯酒，尊前還要落梁塵。"]', '["东川已過二三春，南国須求一兩人。","富貴大都多老大，歡娛太半爲親賓。","如愁翠黛應堪重，買笑黄金莫訴貧。","他日相逢一杯酒，尊前還要落梁塵。"]', '诗', 'shi', '', NULL, '慕巢尚書書云室人欲爲置一歌者非所安也以詩相報因而和之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a58e6a3f-27fc-4ccc-8985-d1ad2c49daa5', '杪秋獨夜', '杪秋独夜', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["無限少年非我伴，可憐清夜與誰同。","歡娛牢落中心少，親故凋零四面空。","紅葉樹飄風起後，白鬚人立月明中。","前頭更有蕭條物，老菊衰蘭三兩叢。"]', '["無限少年非我伴，可怜清夜與誰同。","歡娛牢落中心少，親故凋零四面空。","紅葉樹飄风起後，白鬚人立月明中。","前头更有蕭條物，老菊衰蘭三兩叢。"]', '诗', 'shi', '', NULL, '杪秋獨夜 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04eb1ac2-3eca-4e96-8f3a-a37dbb02f274', '憑李睦州訪徐凝山人', '憑李睦州訪徐凝山人', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["郡守輕詩客，鄉人薄釣翁。","解憐徐處士，唯有李郎中。"]', '["郡守轻诗客，乡人薄釣翁。","解怜徐处士，唯有李郎中。"]', '诗', 'shi', '', NULL, '憑李睦州訪徐凝山人 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80cbc4ae-f7cc-418c-8588-e0230f2d4c99', '蘇州故吏', '蘇州故吏', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南故吏別來久，今日池邊識我無。","不獨使君頭似雪，華亭鶴死白蓮枯。"]', '["江南故吏別来久，今日池邊識我無。","不独使君头似雪，华亭鹤死白蓮枯。"]', '诗', 'shi', '', NULL, '蘇州故吏 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f8b4c6e-95ab-43d3-b9a1-9d8f8c1d701d', '得楊湖州書頗誇撫民接賓縱酒題詩因以絕句戲之', '得楊湖州书頗誇撫民接賓縱酒題诗因以絕句戲之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豈獨愛民兼愛客，不唯能飲又能文。","白蘋洲上春傳語，柳使君輸楊使君。"]', '["豈独愛民兼愛客，不唯能饮又能文。","白蘋洲上春傳語，柳使君輸楊使君。"]', '诗', 'shi', '', NULL, '得楊湖州書頗誇撫民接賓縱酒題詩因以絕句戲之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90858650-e9d6-47a3-83ed-72408ed80c74', '天宮閣秋晴晚望', '天宮閣秋晴晚望', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["洛城秋霽後，梵閣暮登時。","此日風煙好，今秋節候遲。","霞光紅泛豔，樹影碧參差。","莫慮言歸晚，牛家有宿期。"]', '["洛城秋霽後，梵閣暮登时。","此日风煙好，今秋節候遲。","霞光紅泛豔，樹影碧參差。","莫慮言归晚，牛家有宿期。"]', '诗', 'shi', '', NULL, '天宮閣秋晴晚望 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9a8f048-0419-426a-890b-bbd634251130', '酬夢得暮秋晴夜對月相憶', '酬梦得暮秋晴夜对月相憶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["霽月光如練，盈庭復滿池。","秋深無熱後，夜淺未寒時。","露葉團荒菊，風枝落病棃。","相思懶相訪，應是各年衰。"]', '["霽月光如練，盈庭复满池。","秋深無熱後，夜淺未寒时。","露葉團荒菊，风枝落病棃。","相思懶相訪，應是各年衰。"]', '诗', 'shi', '', NULL, '酬夢得暮秋晴夜對月相憶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae885dc7-7a55-4801-9405-38211ef4e6ee', '同夢得和思黯見贈來詩中先敘三人同讌之歡次有歎鬢髮漸衰嫌孫子催老之意因酬妍唱兼吟鄙懷', '同梦得和思黯见贈来诗中先敘三人同讌之歡次有歎鬢髮漸衰嫌孫子催老之意因酬妍唱兼吟鄙懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["醉伴騰騰白與劉，何朝何夕不同遊。","留連燈下明猶飲，斷送尊前倒即休。","催老莫嫌孫稚長，加年須喜鬢毛秋。","教他伯道爭存活，無子無孫亦白頭。"]', '["醉伴腾腾白與劉，何朝何夕不同游。","留連灯下明猶饮，斷送尊前倒即休。","催老莫嫌孫稚长，加年須喜鬢毛秋。","教他伯道爭存活，無子無孫亦白头。"]', '诗', 'shi', '', NULL, '同夢得和思黯見贈來詩中先敘三人同讌之歡次有歎鬢髮漸衰嫌孫子催老之意因酬妍唱兼吟鄙懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3873d0bb-b3ae-4e80-bfb1-b11621b84feb', '聽歌', '听歌', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["管妙弦清歌入雲，老人合眼醉醺醺。","誠知不及當年聽，猶覺聞時勝不聞。"]', '["管妙弦清歌入云，老人合眼醉醺醺。","誠知不及當年听，猶覺闻时勝不闻。"]', '诗', 'shi', '', NULL, '聽歌 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ee98955-3021-49da-823c-a5f12aa59d35', '三年冬隨事鋪設小堂寢處稍似穩暖因念衰病偶吟所懷', '三年冬隨事鋪設小堂寢处稍似穩暖因念衰病偶吟所懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["小宅非全陋，中堂不甚卑。","聊堪會親族，足以貯妻兒。","暖帳迎冬設，溫爐向夜施。","裘新青兔褐，褥軟白猨皮。","似鹿眠深草，如雞宿穩枝。","逐身安枕席，隨事有屏帷。","病致衰殘早，貧營活計遲。","由來蠶老後，方是繭成時。"]', '["小宅非全陋，中堂不甚卑。","聊堪會親族，足以貯妻兒。","暖帳迎冬設，溫爐向夜施。","裘新青兔褐，褥軟白猨皮。","似鹿眠深草，如雞宿穩枝。","逐身安枕席，隨事有屏帷。","病致衰殘早，貧營活計遲。","由来蠶老後，方是繭成时。"]', '诗', 'shi', '', NULL, '三年冬隨事鋪設小堂寢處稍似穩暖因念衰病偶吟所懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e200b631-9601-4e81-8da2-f4d863946124', '初冬即事呈夢得', '初冬即事呈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["青氈帳暖喜微雪，紅地爐深宜早寒。","走筆小詩能和否，潑醅新酒試嘗看。","僧來乞食因留宿，客到開尊便共歡。","臨老交親零落盡，希君恕我取人寬。"]', '["青氈帳暖喜微雪，紅地爐深宜早寒。","走笔小诗能和否，潑醅新酒試嘗看。","僧来乞食因留宿，客到开尊便共歡。","臨老交親零落尽，希君恕我取人寬。"]', '诗', 'shi', '', NULL, '初冬即事呈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04cd5186-589b-47df-8d3c-9a1706cf7fd0', '自罷河南已換七尹每一入府悵然舊遊因宿內廳偶題西壁兼呈韋尹常侍', '自罷河南已換七尹每一入府悵然旧游因宿內廳偶題西壁兼呈韋尹常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每入河南府，依然似到家。","杯嘗七尹酒，樹看十年花。","且健須歡喜，雖衰莫歎嗟。","迎門無故吏，侍坐有新娃。","暖閣謀宵宴，寒庭放晚衙。","主人留宿定，一任夕陽斜。"]', '["每入河南府，依然似到家。","杯嘗七尹酒，樹看十年花。","且健須歡喜，雖衰莫歎嗟。","迎门無故吏，侍坐有新娃。","暖閣謀宵宴，寒庭放晚衙。","主人留宿定，一任夕陽斜。"]', '诗', 'shi', '', NULL, '自罷河南已換七尹每一入府悵然舊遊因宿內廳偶題西壁兼呈韋尹常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00f7e2be-e515-412d-8e4e-aeb6e4923fb5', '天寒晚起引酌詠懷寄許州王尚書汝州李常侍', '天寒晚起引酌詠懷寄許州王尚书汝州李常侍', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["葉覆冰池雪滿山，日高慵起未開關。","寒來更亦無過醉，老後何由可得閑。","四海故交唯許汝，十年貧健是樊蠻。","相思莫忘櫻桃會，一放狂歌一破顏。"]', '["葉覆冰池雪满山，日高慵起未开关。","寒来更亦無過醉，老後何由可得闲。","四海故交唯許汝，十年貧健是樊蠻。","相思莫忘櫻桃會，一放狂歌一破顏。"]', '诗', 'shi', '', NULL, '天寒晚起引酌詠懷寄許州王尚書汝州李常侍 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b64f9672-3afb-44e4-a3e8-e6f516d86f10', '四年春', '四年春', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["柳梢黃嫩草芽新，又入開成第四春。","近日放慵多不出，少年嫌老可相親。","分司吉傅頻過舍，致仕崔卿擬卜鄰。","時輩推遷年事到，往還多是白頭人。"]', '["柳梢黄嫩草芽新，又入开成第四春。","近日放慵多不出，少年嫌老可相親。","分司吉傅頻過舍，致仕崔卿擬卜鄰。","时輩推遷年事到，往還多是白头人。"]', '诗', 'shi', '', NULL, '四年春 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c3f8f836-1304-4efc-8d0d-fbe54cee54af', '白髮', '白髮', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["白髮生來三十年，而今鬚鬢盡皤然。","歌吟終日如狂叟，衰疾多時似瘦仙。","八戒夜持香火印，三光朝念蘂珠篇。","其餘便被春收拾，不作閑遊即醉眠。"]', '["白髮生来三十年，而今鬚鬢尽皤然。","歌吟終日如狂叟，衰疾多时似瘦仙。","八戒夜持香火印，三光朝念蘂珠篇。","其餘便被春收拾，不作闲游即醉眠。"]', '诗', 'shi', '', NULL, '白髮 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('49a18eb8-0e61-41f1-a5c8-fe4af24c4891', '追歡偶作', '追歡偶作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["追歡逐樂少閑時，補貼平生得事遲。","何處花開曾後看，誰家酒熟不先知。","石樓月下吹蘆管，金谷風前舞柳枝。","十聽春啼變鶯舌，三嫌老醜換蛾眉。","樂天一過難知分，猶自咨嗟兩鬢絲。"]', '["追歡逐乐少闲时，補貼平生得事遲。","何处花开曾後看，誰家酒熟不先知。","石楼月下吹蘆管，金谷风前舞柳枝。","十听春啼变鶯舌，三嫌老醜換蛾眉。","乐天一過难知分，猶自咨嗟兩鬢絲。"]', '诗', 'shi', '', NULL, '追歡偶作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a78dbdf-7647-4db0-90b8-04ea7003a64a', '公垂尚書以白馬見寄光潔穩善以詩謝之', '公垂尚书以白马见寄光潔穩善以诗謝之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["翩翩白馬稱金羈，領綴銀花尾曳絲。","毛色鮮明人盡愛，性靈馴善主偏知。","免將妾換慙來處，試使奴牽欲上時。","不蹶不驚行步穩，最宜山簡醉中騎。"]', '["翩翩白马稱金羈，領綴銀花尾曳絲。","毛色鲜明人尽愛，性靈馴善主偏知。","免將妾換慙来处，試使奴牽欲上时。","不蹶不驚行步穩，最宜山簡醉中騎。"]', '诗', 'shi', '', NULL, '公垂尚書以白馬見寄光潔穩善以詩謝之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb96ce01-700a-4fb5-9557-8848041d43fe', '西樓獨立', '西楼独立', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["身著白衣頭似雪，時時醉立小樓中。","路人迴顧應相怪，十一年來見此翁。"]', '["身著白衣头似雪，时时醉立小楼中。","路人迴顧應相怪，十一年来见此翁。"]', '诗', 'shi', '', NULL, '西樓獨立 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94be7709-b798-4de7-bb59-673b3b770a34', '書事詠懷', '书事詠懷', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["官俸將生計，雖貧豈敢嫌。","金多輸陸賈，酒足勝陶潛。","牀煖僧敷坐，樓晴妓卷簾。","日遭齋破用，春賴閏加添。","老向歡彌切，狂於飲不廉。","十年閑未足，亦恐涉無厭。"]', '["官俸將生計，雖貧豈敢嫌。","金多輸陸賈，酒足勝陶潛。","牀煖僧敷坐，楼晴妓卷簾。","日遭斋破用，春賴閏加添。","老向歡彌切，狂於饮不廉。","十年闲未足，亦恐涉無厭。"]', '诗', 'shi', '', NULL, '書事詠懷 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c383d54-c121-4eac-815c-1dbd21ca38f2', '酬夢得比萱草見贈', '酬梦得比萱草见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杜康能散悶，萱草解忘憂。","借問萱逢杜，何如白見劉。","老衰勝少夭，閑樂笑忙愁。","試問同年內，何人得白頭。"]', '["杜康能散悶，萱草解忘憂。","借问萱逢杜，何如白见劉。","老衰勝少夭，闲乐笑忙愁。","試问同年內，何人得白头。"]', '诗', 'shi', '', NULL, '酬夢得比萱草見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cec7855-9481-4adf-b384-aa4e7594efab', '問皇甫十', '问皇甫十', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["苦樂心由我，窮通命任他。","坐傾張翰酒，行唱接輿歌。","榮盛傍看好，優閑自適多。","知君能斷事，勝負兩如何。"]', '["苦乐心由我，窮通命任他。","坐傾張翰酒，行唱接輿歌。","榮盛傍看好，優闲自適多。","知君能斷事，勝負兩如何。"]', '诗', 'shi', '', NULL, '問皇甫十 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ad3a839-62f3-4cb3-9bd0-962dded62589', '早春獨登天宮閣', '早春独登天宮閣', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["天宮日暖閣門開，獨上迎春飲一杯。","無限遊人遙怪我，緣何最老最先來。"]', '["天宮日暖閣门开，独上迎春饮一杯。","無限游人遙怪我，緣何最老最先来。"]', '诗', 'shi', '', NULL, '早春獨登天宮閣 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd397d21-27fd-4d22-854e-584a0074454e', '送蘇州李使君赴郡二絕句 一', '送蘇州李使君赴郡二絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["憶拋印綬辭吳郡，衰病當時已有餘。","今日賀君兼自喜，八迴看換舊銅魚。"]', '["憶拋印綬辞吳郡，衰病當时已有餘。","今日賀君兼自喜，八迴看換旧銅鱼。"]', '诗', 'shi', '', NULL, '送蘇州李使君赴郡二絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b13fb95-626c-4f35-a24f-161dc523a0b0', '送蘇州李使君赴郡二絕句 二', '送蘇州李使君赴郡二絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["館娃宮深春日長，烏鵲橋高秋夜涼。","風月不知人世變，奉君直似奉吳王。"]', '["館娃宮深春日长，烏鵲橋高秋夜涼。","风月不知人世变，奉君直似奉吳王。"]', '诗', 'shi', '', NULL, '送蘇州李使君赴郡二絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('203dd367-29fc-418a-9488-dca20941240f', '長洲曲新詞', '长洲曲新词', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["茂苑綺羅佳麗地，女湖桃李豔陽時。","心奴已死胡容老，後輩風流是阿誰。"]', '["茂苑綺羅佳丽地，女湖桃李豔陽时。","心奴已死胡容老，後輩风流是阿誰。"]', '诗', 'shi', '', NULL, '長洲曲新詞 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0b89b88-13fa-4f91-9db8-eb46ed6f2930', '憶江南詞三首 一', '憶江南词三首 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南好，風景舊曾諳。"]', '["江南好，风景旧曾諳。"]', '诗', 'shi', '', NULL, '憶江南詞三首 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e58ff68f-386c-4a12-b97a-965eb7958ca0', '憶江南詞三首 二', '憶江南词三首 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，最憶是杭州。"]', '["江南憶，最憶是杭州。"]', '诗', 'shi', '', NULL, '憶江南詞三首 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a80c92aa-57ea-4786-a155-4b6b3d484e64', '憶江南詞三首 三', '憶江南词三首 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["江南憶，其次憶吳宮。"]', '["江南憶，其次憶吳宮。"]', '诗', 'shi', '', NULL, '憶江南詞三首 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('429667fc-08e7-490a-a87b-14a7323ca688', '病中詩十五首 初病風', '病中诗十五首 初病风', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["六十八衰翁，乘衰百疾攻。","朽株難免蠹，空穴易來風。","肘痹宜生柳，頭旋劇轉蓬。","恬然不動處，虛白在胷中。"]', '["六十八衰翁，乘衰百疾攻。","朽株难免蠹，空穴易来风。","肘痹宜生柳，头旋劇轉蓬。","恬然不动处，虛白在胷中。"]', '诗', 'shi', '', NULL, '病中詩十五首 初病風 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95e07da8-bbb2-441c-b208-dec16a5bd882', '病中詩十五首 枕上作', '病中诗十五首 枕上作', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風疾侵凌臨老頭，血凝筋滯不調柔。","甘從此後支離臥，賴是從前爛漫遊。","迴思往事紛如夢，轉覺餘生杳若浮。","浩氣自能充靜室，驚飆何必蕩虛舟。","腹空先進松花酒，膝冷重裝桂布裘。","若問樂天憂病否，樂天知命了無憂。"]', '["风疾侵凌臨老头，血凝筋滯不調柔。","甘從此後支離臥，賴是從前爛漫游。","迴思往事紛如梦，轉覺餘生杳若浮。","浩氣自能充静室，驚飆何必蕩虛舟。","腹空先進松花酒，膝冷重裝桂布裘。","若问乐天憂病否，乐天知命了無憂。"]', '诗', 'shi', '', NULL, '病中詩十五首 枕上作 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea01d3d1-0257-4a25-89d4-599fe310addf', '病中詩十五首 荅閑上人來問因何風疾', '病中诗十五首 荅闲上人来问因何风疾', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["一牀方丈向陽開，勞動文殊問疾來。","欲界凡夫何足道，四禪天始免風災。"]', '["一牀方丈向陽开，勞动文殊问疾来。","欲界凡夫何足道，四禪天始免风災。"]', '诗', 'shi', '', NULL, '病中詩十五首 荅閑上人來問因何風疾 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2afa4a2b-d947-4575-a895-ddf92c1e4d31', '病中詩十五首 病中五絕句 一', '病中诗十五首 病中五絕句 一', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["世間生老病相隨，此事心中久自知。","今日行年將七十，猶須慙愧病來遲。"]', '["世间生老病相隨，此事心中久自知。","今日行年將七十，猶須慙愧病来遲。"]', '诗', 'shi', '', NULL, '病中詩十五首 病中五絕句 一 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55eb9051-846c-4295-94f5-4ffee3214054', '病中詩十五首 病中五絕句 二', '病中诗十五首 病中五絕句 二', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["方寸成灰鬢作絲，假如強健亦何爲。","家無憂累身無事，正是安閑好病時。"]', '["方寸成灰鬢作絲，假如強健亦何爲。","家無憂累身無事，正是安闲好病时。"]', '诗', 'shi', '', NULL, '病中詩十五首 病中五絕句 二 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cf51eb9-76d4-4d88-bf7d-46505a3e19d1', '病中詩十五首 病中五絕句 三', '病中诗十五首 病中五絕句 三', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["李君墓上松應拱，元相池頭竹盡枯。","多幸樂天今始病，不知合要苦治無。"]', '["李君墓上松應拱，元相池头竹尽枯。","多幸乐天今始病，不知合要苦治無。"]', '诗', 'shi', '', NULL, '病中詩十五首 病中五絕句 三 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6848d03f-3d0e-4dae-b0ed-6645899f729b', '病中詩十五首 病中五絕句 四', '病中诗十五首 病中五絕句 四', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["目昏思寢即安眠，足軟妨行便坐禪。","身作醫王心是藥，不勞和扁到門前。"]', '["目昏思寢即安眠，足軟妨行便坐禪。","身作醫王心是藥，不勞和扁到门前。"]', '诗', 'shi', '', NULL, '病中詩十五首 病中五絕句 四 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('831f46ab-a452-4de3-a264-6271026425e1', '病中詩十五首 病中五絕句 五', '病中诗十五首 病中五絕句 五', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["交親不要苦相憂，亦擬時時強出遊。","但有心情何用脚，陸乘肩轝水乘舟。"]', '["交親不要苦相憂，亦擬时时強出游。","但有心情何用脚，陸乘肩轝水乘舟。"]', '诗', 'shi', '', NULL, '病中詩十五首 病中五絕句 五 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01efda21-3c54-4fbf-a222-e79de3e5716a', '病中詩十五首 送嵩客', '病中诗十五首 送嵩客', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["登山臨水分無期，泉石煙霞今屬誰。","君到嵩陽吟此句，與教二十六峰知。"]', '["登山臨水分無期，泉石煙霞今屬誰。","君到嵩陽吟此句，與教二十六峰知。"]', '诗', 'shi', '', NULL, '病中詩十五首 送嵩客 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1938a424-341f-4a2c-9fe5-786be01d323e', '病中詩十五首 罷[灸]', '病中诗十五首 罷[灸]', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["病身佛說將何喻，變滅須臾豈不聞。","莫遣淨名知我笑，休將火艾[灸]浮雲。"]', '["病身佛说將何喻，变滅須臾豈不闻。","莫遣淨名知我笑，休將火艾[灸]浮云。"]', '诗', 'shi', '', NULL, '病中詩十五首 罷[灸] 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45e0b372-c3f1-4c6d-8537-75dbca4ed069', '病中詩十五首 賣駱馬', '病中诗十五首 賣駱马', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["五年花下醉騎行，臨賣回頭嘶一聲。","項籍顧騅猶解歎，樂天別駱豈無情。"]', '["五年花下醉騎行，臨賣回头嘶一声。","項籍顧騅猶解歎，乐天別駱豈無情。"]', '诗', 'shi', '', NULL, '病中詩十五首 賣駱馬 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('042f6a90-e4de-4b94-85ad-451b8d7a0325', '病中詩十五首 別柳枝', '病中诗十五首 別柳枝', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["兩枝楊柳小樓中，嫋嫋多年伴醉翁。","明日放歸歸去後，世間應不要春風。"]', '["兩枝楊柳小楼中，嫋嫋多年伴醉翁。","明日放归归去後，世间應不要春风。"]', '诗', 'shi', '', NULL, '病中詩十五首 別柳枝 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18b34c44-3006-438d-95ce-f6d5e8c33006', '病中詩十五首 就暖偶酌戲諸詩酒舊侶', '病中诗十五首 就暖偶酌戲諸诗酒旧侶', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["低屏軟褥臥藤牀，舁向前軒就日陽。","一足任他爲外物，三杯自要沃中腸。","頭風若見詩應愈，齒折仍誇笑不妨。","細酌徐吟猶得在，舊遊未必便相忘。"]', '["低屏軟褥臥藤牀，舁向前軒就日陽。","一足任他爲外物，三杯自要沃中腸。","头风若见诗應愈，齒折仍誇笑不妨。","細酌徐吟猶得在，旧游未必便相忘。"]', '诗', 'shi', '', NULL, '病中詩十五首 就暖偶酌戲諸詩酒舊侶 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34abad4b-3030-45ff-be95-4a95bfb26f04', '病中詩十五首 歲暮呈思黯相公皇甫朗之及夢得尚書', '病中诗十五首 歲暮呈思黯相公皇甫朗之及梦得尚书', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲暮皤然一老夫，十分流輩九分無。","莫嫌身病人扶侍，猶勝無身可遣扶。"]', '["歲暮皤然一老夫，十分流輩九分無。","莫嫌身病人扶侍，猶勝無身可遣扶。"]', '诗', 'shi', '', NULL, '病中詩十五首 歲暮呈思黯相公皇甫朗之及夢得尚書 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e673845c-b604-4175-99c7-9a98bc685ff4', '病中詩十五首 自解', '病中诗十五首 自解', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["房傳往世爲禪客王道前生應畫師。","我亦定中觀宿命，多生債負是歌詩。","不然何故狂吟詠，病後多於未病時。"]', '["房傳往世爲禪客王道前生應畫師。","我亦定中观宿命，多生債負是歌诗。","不然何故狂吟詠，病後多於未病时。"]', '诗', 'shi', '', NULL, '病中詩十五首 自解 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d581d39-7c63-4109-84aa-7ab12472e229', '歲暮病懷贈夢得', '歲暮病懷贈梦得', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["十年四海故交親，零落唯殘兩病身。","共遣數奇從是命，同教步蹇有何因。","眼隨老減嫌長夜，體待陽舒望早春。","新樂堂前舊池上，相過亦不要他人。"]', '["十年四海故交親，零落唯殘兩病身。","共遣數奇從是命，同教步蹇有何因。","眼隨老減嫌长夜，體待陽舒望早春。","新乐堂前旧池上，相過亦不要他人。"]', '诗', 'shi', '', NULL, '歲暮病懷贈夢得 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e14106-ad33-4839-8d56-331791812875', '雪後過集賢裴令公舊宅有感', '雪後過集賢裴令公旧宅有感', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["梁王捐館後，枚叟過門時。","有淚人還泣，無情雪不知。","臺亭留盡在，賓客散何之。","唯有蕭條雁，時來下故池。"]', '["梁王捐館後，枚叟過门时。","有泪人還泣，無情雪不知。","台亭留尽在，賓客散何之。","唯有蕭條雁，时来下故池。"]', '诗', 'shi', '', NULL, '雪後過集賢裴令公舊宅有感 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('132fc035-aaff-4582-8856-be885c18ca8f', '酬夢得貧居詠懷見贈', '酬梦得貧居詠懷见贈', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["歲陰生計兩蹉跎，相顧悠悠醉且歌。","廚冷難留烏止屋，門閑可與雀張羅。","病添莊舃吟聲苦，貧欠韓康藥債多。","日望揮金賀新命，俸錢依舊又如何。"]', '["歲陰生計兩蹉跎，相顧悠悠醉且歌。","廚冷难留烏止屋，门闲可與雀張羅。","病添莊舃吟声苦，貧欠韓康藥債多。","日望揮金賀新命，俸錢依旧又如何。"]', '诗', 'shi', '', NULL, '酬夢得貧居詠懷見贈 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b06152cd-7dda-4c46-a96a-6dd15b3850c9', '酬夢得見喜疾瘳', '酬梦得见喜疾瘳', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["暖臥摩綿褥，晨傾藥酒螺。","昏昏布裘底，病醉睡相和。","末疾徒云爾，餘年有幾何。","須知差與否，相去校無多。"]', '["暖臥摩綿褥，晨傾藥酒螺。","昏昏布裘底，病醉睡相和。","末疾徒云爾，餘年有幾何。","須知差與否，相去校無多。"]', '诗', 'shi', '', NULL, '酬夢得見喜疾瘳 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c55ceced-7b4b-4b02-a17c-47778a2f7ca4', '夜聞箏中彈瀟湘送神曲感舊', '夜闻箏中彈瀟湘送神曲感旧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["縹緲巫山女，歸來七八年。","殷勤湘水曲，留在十三弦。","苦調吟還出，深情咽不傳。","萬重雲水思，今夜月明前。"]', '["縹緲巫山女，归来七八年。","殷勤湘水曲，留在十三弦。","苦調吟還出，深情咽不傳。","万重云水思，今夜月明前。"]', '诗', 'shi', '', NULL, '夜聞箏中彈瀟湘送神曲感舊 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5426eda-9f02-4725-9b03-697baf405fd6', '感蘇州舊舫', '感蘇州旧舫', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["畫梁朽折紅窗破，獨立池邊盡日看。","守得蘇州船舫爛，此身爭合不衰殘。"]', '["畫梁朽折紅窗破，独立池邊尽日看。","守得蘇州船舫爛，此身爭合不衰殘。"]', '诗', 'shi', '', NULL, '感蘇州舊舫 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c0cc768-ace4-4077-a313-5f68f8a32331', '感舊石上字', '感旧石上字', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑撥船行尋舊池，幽情往事復誰知。","太湖石上鐫三字，十五年前陳結之。"]', '["闲撥船行尋旧池，幽情往事复誰知。","太湖石上鐫三字，十五年前陳結之。"]', '诗', 'shi', '', NULL, '感舊石上字 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1fc129e-ebed-4b85-bf8e-1bf428b47127', '見敏中初到邠寧秋日登城樓詩詩中頗多鄉思因以寄和', '见敏中初到邠寧秋日登城楼诗诗中頗多乡思因以寄和', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["想爾到邊頭，蕭條正值秋。","二年貧御史，八月古邠州。","絲管聞雖樂，風沙見亦愁。","望鄉心若苦，不用數登樓。"]', '["想爾到邊头，蕭條正值秋。","二年貧御史，八月古邠州。","絲管闻雖乐，风沙见亦愁。","望乡心若苦，不用數登楼。"]', '诗', 'shi', '', NULL, '見敏中初到邠寧秋日登城樓詩詩中頗多鄉思因以寄和 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bab6fbc-36f1-49cf-821d-aa86fa2d31a3', '齋戒', '斋戒', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["每因齋戒斷葷腥，漸覺塵勞染愛輕。","六賊定知無氣色，三尸應恨少恩情。","酒魔降伏終須盡，詩債填還亦欲平。","從此始堪爲弟子，竺乾師是古先生。"]', '["每因斋戒斷葷腥，漸覺塵勞染愛轻。","六賊定知無氣色，三尸應恨少恩情。","酒魔降伏終須尽，诗債填還亦欲平。","從此始堪爲弟子，竺乾師是古先生。"]', '诗', 'shi', '', NULL, '齋戒 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('41289609-342e-494a-8046-30428f857644', '戲禮經老僧', '戲禮經老僧', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["香火一爐燈一醆，白頭夜禮佛名經。","何年飲著聲聞酒，直到如今醉未醒。"]', '["香火一爐灯一醆，白头夜禮佛名經。","何年饮著声闻酒，直到如今醉未醒。"]', '诗', 'shi', '', NULL, '戲禮經老僧 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4bd890f-f11b-4f5c-8ea0-a616c9188dd3', '近見慕巢尚書詩中屢有歎老思退之意又於洛下新置郊居然寵寄方深歸心大速因以長句戲而諭之', '近见慕巢尚书诗中屢有歎老思退之意又於洛下新置郊居然寵寄方深归心大速因以长句戲而諭之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["近見詩中歎白髮，遙知閫外憶東都。","煙霞偷眼窺來久，富貴黏身擺得無。","新置林園猶濩落，未終婚嫁且踟躕。","應須待到懸車歲，然後東歸伴老夫。"]', '["近见诗中歎白髮，遙知閫外憶东都。","煙霞偷眼窺来久，富貴黏身擺得無。","新置林园猶濩落，未終婚嫁且踟躕。","應須待到懸车歲，然後东归伴老夫。"]', '诗', 'shi', '', NULL, '近見慕巢尚書詩中屢有歎老思退之意又於洛下新置郊居然寵寄方深歸心大速因以長句戲而諭之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9612102c-31cf-4e06-a6bd-f8eb606474b5', '對鏡偶吟贈張道士抱元', '对镜偶吟贈張道士抱元', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["閑來對鏡自思量，年貌衰殘分所當。","白髮萬莖何所怪，丹砂一粒不曾嘗。","眼昏久被書料理，肺渴多因酒損傷。","今日逢師雖已晚，枕中治老有何方。"]', '["闲来对镜自思量，年貌衰殘分所當。","白髮万莖何所怪，丹砂一粒不曾嘗。","眼昏久被书料理，肺渴多因酒損傷。","今日逢師雖已晚，枕中治老有何方。"]', '诗', 'shi', '', NULL, '對鏡偶吟贈張道士抱元 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('801050d8-45bb-40b6-a8cf-fc80a6317019', '病入新正', '病入新正', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["枕上驚新歲，花前念舊歡。","是身老所逼，非意病相干。","風月情猶在，杯觴興漸闌。","便休心未伏，更試一春看。"]', '["枕上驚新歲，花前念旧歡。","是身老所逼，非意病相干。","风月情猶在，杯觴兴漸闌。","便休心未伏，更試一春看。"]', '诗', 'shi', '', NULL, '病入新正 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2361fb2-9708-421e-a294-cd02f3fb140a', '臥疾來早晚', '臥疾来早晚', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["臥疾來早晚，懸懸將十旬。","婢能尋本草，犬不吠醫人。","酒甕全生醭，歌筵半委塵。","風光還欲好，爭向枕前春。"]', '["臥疾来早晚，懸懸將十旬。","婢能尋本草，犬不吠醫人。","酒甕全生醭，歌筵半委塵。","风光還欲好，爭向枕前春。"]', '诗', 'shi', '', NULL, '臥疾來早晚 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8a618145-31df-4c59-b047-f0c481e57962', '強起迎春戲寄思黯', '強起迎春戲寄思黯', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["杖策人扶廢病身，晴和強起一迎春。","他時蹇跛縱行得，笑殺平原樓上人。"]', '["杖策人扶廢病身，晴和強起一迎春。","他时蹇跛縱行得，笑殺平原楼上人。"]', '诗', 'shi', '', NULL, '強起迎春戲寄思黯 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ef65e05-065a-42b6-b4fc-c89361444b5a', '夢得前所酬篇有鍊盡美少年之句因思往事兼詠今懷重以長句荅之', '梦得前所酬篇有鍊尽美少年之句因思往事兼詠今懷重以长句荅之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["鍊盡少年成白首，憶初相識到今朝。","昔饒春桂長先折，今伴寒松取後凋。","生事縱貧猶可過，風情雖老未全銷。","聲華寵命人皆得，若箇如君歷七朝。"]', '["鍊尽少年成白首，憶初相識到今朝。","昔饒春桂长先折，今伴寒松取後凋。","生事縱貧猶可過，风情雖老未全銷。","声华寵命人皆得，若箇如君歷七朝。"]', '诗', 'shi', '', NULL, '夢得前所酬篇有鍊盡美少年之句因思往事兼詠今懷重以長句荅之 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b27218c9-b467-43e7-b625-9513fc7c6044', '病後寒食', '病後寒食', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["故紗絳帳舊青氈，藥酒醺醺引醉眠。","斗擻弊袍春晚後，摩挲病脚日陽前。","行無筋力尋山水，坐少精神聽管弦。","拋擲風光負寒食，曾來未省似今年。"]', '["故紗絳帳旧青氈，藥酒醺醺引醉眠。","斗擻弊袍春晚後，摩挲病脚日陽前。","行無筋力尋山水，坐少精神听管弦。","拋擲风光負寒食，曾来未省似今年。"]', '诗', 'shi', '', NULL, '病後寒食 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0c85a623-4112-4e32-8339-7b25e189760a', '老病相仍以詩自解', '老病相仍以诗自解', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["榮枯憂喜與彭殤，都是人間戲一場。","蟲臂鼠肝猶不怪，雞膚鶴髮復何傷。","昨因風發甘長往，今遇陽和又小康。","還似遠行裝束了，遲迴且住亦何妨。"]', '["榮枯憂喜與彭殤，都是人间戲一場。","蟲臂鼠肝猶不怪，雞膚鹤髮复何傷。","昨因风發甘长往，今遇陽和又小康。","還似远行裝束了，遲迴且住亦何妨。"]', '诗', 'shi', '', NULL, '老病相仍以詩自解 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9026eb8-1a77-4496-acb7-88df04bf8825', '皇甫郎中親家翁赴任絳州宴送出城贈別', '皇甫郎中親家翁赴任絳州宴送出城贈別', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["慕賢入室交先定，結援通家好復成。","新婦不嫌貧活計，嬌孫同慰老心情。","洛橋歌酒今朝散，絳路風煙幾日行。","欲識離羣相戀意，爲君扶病出都城。"]', '["慕賢入室交先定，結援通家好复成。","新婦不嫌貧活計，嬌孫同慰老心情。","洛橋歌酒今朝散，絳路风煙幾日行。","欲識離羣相戀意，爲君扶病出都城。"]', '诗', 'shi', '', NULL, '皇甫郎中親家翁赴任絳州宴送出城贈別 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c05a88ab-d4a5-47f3-9c30-47e9ac53e23c', '春暖', '春暖', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["風痹宜和暖，春來脚較輕。","鶯留花下立，鶴引水邊行。","髮少嫌巾重，顏衰訝鏡明。","不論親與故，自亦昧平生。"]', '["风痹宜和暖，春来脚較轻。","鶯留花下立，鹤引水邊行。","髮少嫌巾重，顏衰訝镜明。","不論親與故，自亦昧平生。"]', '诗', 'shi', '', NULL, '春暖 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84bbd8e3-6c52-4f4f-90ec-3483fb8d1fb8', '殘春晚起伴客笑談', '殘春晚起伴客笑談', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["掩戶下簾朝睡足，一聲黃鳥報殘春。","披衣岸幘日高起，兩角青衣扶老身。","策杖強行過里巷，引杯閑酌伴親賓。","莫言病後妨談笑，猶恐多於不病人。"]', '["掩戶下簾朝睡足，一声黄鸟報殘春。","披衣岸幘日高起，兩角青衣扶老身。","策杖強行過里巷，引杯闲酌伴親賓。","莫言病後妨談笑，猶恐多於不病人。"]', '诗', 'shi', '', NULL, '殘春晚起伴客笑談 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af649eb6-0717-4fc0-95c6-4f09eb17202b', '送唐州崔使君侍親赴任', '送唐州崔使君侍親赴任', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["連持使節歷專城，獨賀崔侯最慶榮。","烏府一拋霜簡去，朱輪四從板輿行。","發時止許沙鷗送，到日方乘竹馬迎。","唯慮郡齋賓友少，數杯春酒共誰傾。"]', '["連持使節歷專城，独賀崔侯最慶榮。","烏府一拋霜簡去，朱輪四從板輿行。","發时止許沙鷗送，到日方乘竹马迎。","唯慮郡斋賓友少，數杯春酒共誰傾。"]', '诗', 'shi', '', NULL, '送唐州崔使君侍親赴任 白居易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c905d9e5-0ce4-40d7-b779-a8a35fa3e21c', '春晚詠懷贈皇甫朗之', '春晚詠懷贈皇甫朗之', '30911bfe-abb2-471d-9f59-1fe94901459d', '唐', '["豔陽時節又蹉跎，遲暮光陰復若何。","一歲平分春日少，百年通計老時多。","多中更被愁牽引，少處兼遭病折磨。","賴有銷憂治悶藥，君家濃酎我狂歌。"]', '["豔陽时節又蹉跎，遲暮光陰复若何。","一歲平分春日少，百年通計老时多。","多中更被愁牽引，少处兼遭病折磨。","賴有銷憂治悶藥，君家濃酎我狂歌。"]', '诗', 'shi', '', NULL, '春晚詠懷贈皇甫朗之 白居易 shi');
